if not table.unpack and unpack then
    table.unpack = unpack
end
if not string.split then
    string.split = function(s, sep)
        sep = sep or ","
        local result = {}
        local sepLen = #sep
        local start = 1
        while true do
            local i = string.find(s, sep, start, true)
            if not i then
                result[#result + 1] = string.sub(s, start)
                break
            end
            result[#result + 1] = string.sub(s, start, i - 1)
            start = i + sepLen
        end
        return result
    end
end
if not os.date then
    os.date = function(fmt, t)
        t = t or os.time()
        if fmt == "*t" then
            local s = t % 60
            local m = math.floor(t / 60) % 60
            local h = math.floor(t / 3600) % 24
            local d = math.floor(t / 86400)
            local y = 1970 + math.floor(d / 365)
            local mo = math.floor((d % 365) / 30) + 1
            return { hour = h, min = m, sec = s, day = (d % 30) + 1, month = mo, year = y, wday = (d % 7) + 1, yday = d % 365 + 1 }
        end
        local s = t % 60
        local m = math.floor(t / 60) % 60
        local h = math.floor(t / 3600) % 24
        local result = fmt or "%H:%M:%S"
        result = result:gsub("%%H", string.format("%02d", h))
        result = result:gsub("%%M", string.format("%02d", m))
        result = result:gsub("%%S", string.format("%02d", s))
        result = result:gsub("%%Y", tostring(1970 + math.floor(t / 31536000)))
        result = result:gsub("%%d", string.format("%02d", math.floor(t / 86400) % 30 + 1))
        result = result:gsub("%%m", string.format("%02d", math.floor(t / 2592000) % 12 + 1))
        result = result:gsub("%%b", "---")
        return result
    end
end
local function SafeClipboard(text)
    text = tostring(text or "")
    local fns = { setclipboard, toclipboard, rbxsetclipboard,
                  (syn and syn.toclipboard),
                  (typeof(_G) == "table" and _G.setclipboard) }
    for _, fn in ipairs(fns) do
        if typeof(fn) == "function" then
            local ok = pcall(fn, text)
            if ok then return true end
        end
    end
    return false
end
local function _SafeEnum(enumType, member)
    local ok, v = pcall(function() return Enum[enumType][member] end)
    return ok and v or nil
end
local _AutomaticSizeY = _SafeEnum("AutomaticSize", "Y") or rawget(Enum.AutomaticSize or {}, "Y")
local _AutomaticSizeX = _SafeEnum("AutomaticSize", "X") or rawget(Enum.AutomaticSize or {}, "X")
local _ScrollBarInsetAlways = _SafeEnum("ScrollBarInset", "Always")
local _AssetFetchFailure   = _SafeEnum("AssetFetchStatus", "Failure")
if type(task) ~= "table" then task = {} end
if type(task.wait) ~= "function" then
    task.wait = function(t)
        t = tonumber(t) or 0
        local start = tick()
        if t > 0 then
            while tick() - start < t do
                game:GetService("RunService").Heartbeat:Wait()
            end
        end
        return tick() - start
    end
end
if type(task.spawn) ~= "function" then
    task.spawn = function(fn, ...)
        local args = { ... }
        return coroutine.wrap(function() fn(table.unpack(args)) end)()
    end
end
if type(task.delay) ~= "function" then
    task.delay = function(t, fn, ...)
        local args = { ... }
        return coroutine.wrap(function()
            task.wait(t)
            fn(table.unpack(args))
        end)()
    end
end
if type(task.defer) ~= "function" then
    task.defer = function(fn, ...)
        local args = { ... }
        return coroutine.wrap(function()
            game:GetService("RunService").Heartbeat:Wait()
            fn(table.unpack(args))
        end)()
    end
end
if type(task.cancel) ~= "function" then
    task.cancel = function(thread)
        if type(thread) == "thread" and coroutine.status(thread) ~= "dead" then
            if coroutine.close then
                pcall(coroutine.close, thread)
            else
                pcall(function() coroutine.resume(thread) end)
            end
        end
    end
end
local _ZL = {}
_ZL.smoothLerp = function(a, b, t)
    a, b, t = tonumber(a) or 0, tonumber(b) or 0, tonumber(t) or 0
    return a + (b - a) * (1 - math.exp(-t * 5))
end
_ZL.throttle = function(signal, interval, fn)
    local last = 0
    return signal:Connect(function(...)
        local n = tick()
        if n - last >= interval then last = n
        fn(...) end
    end)
end
_ZL.lagStats = {
    fpsHistory = {},
    avgFPS = 120,
    lagStreak = 0,
    normalStreak = 0,
    lastGCTime = 0,
    gcInterval = 120,
    lowQuality = false,
    frameSkipCounter = 0,
    frameSkipRate = 0,
    janitorLastRun = 0,
}
local _COOLDOWN = {
    shadow    = 45,
    particle  = 25,
    streaming = 30,
    lod       = 20,
}
local _STATE = {
    shadow    = { supressed = false, lockedUntil = 0, origShadow = nil },
    particle  = { supressed = false, lockedUntil = 0, affected = {}, cachedDescendants = {} },
    streaming = { tightened = false, lockedUntil = 0, origMin = nil, origTarget = nil },
    lod       = { active = false, lockedUntil = 0, connections = {} },
}
local function _canToggle(kind)
    return tick() >= (_STATE[kind].lockedUntil or 0)
end
local function _lockToggle(kind, duration)
    _STATE[kind].lockedUntil = tick() + (duration or 20)
end
_ZL.autoLagManager = function(dt)
    local s   = _ZL.lagStats
    local fps = 1 / math.max(dt, 0.001)
    table.insert(s.fpsHistory, 1, fps)
    if #s.fpsHistory > 40 then table.remove(s.fpsHistory) end
    local sum = 0
    for _, v in ipairs(s.fpsHistory) do sum = sum + v end
    s.avgFPS = sum / #s.fpsHistory
    if s.avgFPS < 18 then
        s.lagStreak    = s.lagStreak + 1
        s.normalStreak = math.max(0, s.normalStreak - 1)
    elseif s.avgFPS > 50 then
        s.normalStreak = s.normalStreak + 1
        s.lagStreak    = math.max(0, s.lagStreak - 1)
    else
        s.lagStreak    = math.max(0, s.lagStreak - 0.4)
        s.normalStreak = math.max(0, s.normalStreak - 0.4)
    end
    if s.lagStreak >= 3 and not s.lowQuality then
        s.lowQuality    = true
        s.frameSkipRate = 1
        if _canToggle("streaming") then
            _ZL.tightenStreaming()
            _lockToggle("streaming", _COOLDOWN.streaming)
        end
        warn("[JEYHUB-ZL] FPS rendah ("..math.floor(s.avgFPS).."). Mode hemat aktif.")
    end
    if s.lagStreak >= 8 then
        s.frameSkipRate = 2
        if _canToggle("particle") then
            _ZL.suppressParticles()
            _lockToggle("particle", _COOLDOWN.particle)
        end
    end
    if s.lagStreak >= 15 then
        if _canToggle("shadow") then
            _ZL.suppressShadows()
            _lockToggle("shadow", _COOLDOWN.shadow)
        end
        if _canToggle("lod") then
            _ZL.applyCharLOD()
            _lockToggle("lod", _COOLDOWN.lod)
        end
        local now = tick()
        if now - s.lastGCTime > 20 then
            s.lastGCTime = now
            task.defer(function()
                pcall(function() collectgarbage("step", 300) end)
            end)
        end
    end
    if s.normalStreak >= 5 and s.frameSkipRate > 0 then
        s.frameSkipRate = math.max(0, s.frameSkipRate - 1)
        s.normalStreak = 0
    end
    if s.normalStreak >= 10 then
        if _canToggle("lod") then _ZL.restoreCharLOD() end
    end
    if s.normalStreak >= 18 then
        if _canToggle("particle") then _ZL.restoreParticles() end
    end
    if s.normalStreak >= 30 then
        if _canToggle("shadow") then _ZL.restoreShadows() end
        if _canToggle("streaming") then _ZL.restoreStreaming() end
        if s.lowQuality then
            s.lowQuality = false
            warn("[JEYHUB-ZL] FPS stabil. Semua mode hemat dimatikan.")
        end
    end
    local now = tick()
    if now - s.lastGCTime > s.gcInterval and s.avgFPS > 25 then
        s.lastGCTime = now
        task.defer(function()
            local before = collectgarbage("count")
            pcall(function() collectgarbage("step", 400) end)
            local freed = before - collectgarbage("count")
            if freed > 200 then
                warn("[JEYHUB-ZL] Auto-GC membebaskan "..math.floor(freed).." KB")
            end
        end)
    end
    if now - s.janitorLastRun > 15 then
        s.janitorLastRun = now
        if getgenv and getgenv().JEYHUB_CONNECTIONS then
            local alive = {}
            for _, conn in pairs(getgenv().JEYHUB_CONNECTIONS) do
                if typeof(conn) == "RBXScriptConnection" and conn.Connected then
                    table.insert(alive, conn)
                end
            end
            getgenv().JEYHUB_CONNECTIONS = alive
        end
    end
end
_ZL.shouldSkipFrame = function()
    local s = _ZL.lagStats
    if s.frameSkipRate <= 0 then return false end
    s.frameSkipCounter = s.frameSkipCounter + 1
    local cycle = s.frameSkipRate + 1
    return (s.frameSkipCounter % cycle) ~= 0
end
_ZL.gameNormalizer = function()
    pcall(function()
        local r = settings().Rendering
        if r and r.QualityLevel then
            local current = r.QualityLevel.Value
            if current > 7 then
                local target = math.max(current - 2, 5)
                r.QualityLevel = target
                warn("[JEYHUB-ZL] Kualitas render diturunkan ke Level "..target.." agar game lancar.")
            end
        end
    end)
    pcall(function()
        local ss = game:GetService("SoundService")
        if ss then ss.RespectFilteringEnabled = true end
    end)
    pcall(function()
        local ws = game:GetService("Workspace")
        if ws and ws.StreamingEnabled then
            ws.StreamingMinRadius    = math.min(ws.StreamingMinRadius or 64, 64)
            ws.StreamingTargetRadius = math.min(ws.StreamingTargetRadius or 1024, 512)
        end
    end)
end
_ZL.suppressShadows = function()
    local st = _STATE.shadow
    if st.supressed or not _canToggle("shadow") then return end
    st.supressed = true
    pcall(function()
        local lighting = game:GetService("Lighting")
        st.origShadow = lighting.GlobalShadows
        lighting.GlobalShadows = false
        pcall(function() lighting.ShadowSoftness = 0 end)
        pcall(function() lighting.EnvironmentDiffuseScale = 0 end)
        pcall(function() lighting.EnvironmentSpecularScale = 0 end)
        warn("[JEYHUB-ZL] Shadow dimatikan " .. _CHR.EM_DASH .. " FPS kritis. (Lock 45s)")
    end)
end
_ZL.restoreShadows = function()
    local st = _STATE.shadow
    if not st.supressed or not _canToggle("shadow") then return end
    st.supressed = false
    pcall(function()
        local lighting = game:GetService("Lighting")
        lighting.GlobalShadows = (st.origShadow ~= nil) and st.origShadow or true
        pcall(function() lighting.ShadowSoftness = 1 end)
        pcall(function() lighting.EnvironmentDiffuseScale = 1 end)
        pcall(function() lighting.EnvironmentSpecularScale = 1 end)
        warn("[JEYHUB-ZL] Shadow dipulihkan.")
    end)
end
_ZL.suppressParticles = function()
    local st = _STATE.particle
    if st.supressed or not _canToggle("particle") then return end
    st.supressed = true
    task.defer(function()
        local count = 0
        local ws = game:GetService("Workspace")
        local desc = ws:GetDescendants()
        st.cachedDescendants = desc
        for _, v in ipairs(desc) do
            if v:IsA("ParticleEmitter") or v:IsA("Trail") or v:IsA("Beam") then
                if v.Enabled then
                    v.Enabled = false
                    table.insert(st.affected, { obj = v, prev = true })
                    count = count + 1
                    if count >= 150 then break end
                end
            end
        end
        if count > 0 then warn("[JEYHUB-ZL] "..count.." partikel dimatikan sementara.") end
    end)
end
_ZL.restoreParticles = function()
    local st = _STATE.particle
    if not st.supressed or not _canToggle("particle") then return end
    st.supressed = false
    task.defer(function()
        for _, entry in ipairs(st.affected) do
            pcall(function()
                if entry.obj and entry.obj.Parent then entry.obj.Enabled = entry.prev end
            end)
        end
        st.affected = {}
        warn("[JEYHUB-ZL] Partikel dipulihkan.")
    end)
end
_ZL.tightenStreaming = function()
    local st = _STATE.streaming
    if st.tightened or not _canToggle("streaming") then return end
    st.tightened = true
    pcall(function()
        local ws = game:GetService("Workspace")
        if not ws.StreamingEnabled then return end
        st.origMin    = ws.StreamingMinRadius
        st.origTarget = ws.StreamingTargetRadius
        ws.StreamingMinRadius    = 32
        ws.StreamingTargetRadius = 256
        warn("[JEYHUB-ZL] Streaming radius diperketat.")
    end)
end
_ZL.restoreStreaming = function()
    local st = _STATE.streaming
    if not st.tightened or not _canToggle("streaming") then return end
    st.tightened = false
    pcall(function()
        local ws = game:GetService("Workspace")
        if not ws.StreamingEnabled then return end
        ws.StreamingMinRadius    = st.origMin    or 64
        ws.StreamingTargetRadius = st.origTarget or 1024
        warn("[JEYHUB-ZL] Streaming radius dipulihkan.")
    end)
end
_ZL.applyCharLOD = function()
    local st = _STATE.lod
    if st.active or not _canToggle("lod") then return end
    st.active = true
    task.defer(function()
        local Plrs  = game:GetService("Players")
        local lp    = Plrs.LocalPlayer
        local lpChar = lp and lp.Character
        local lpRoot = lpChar and lpChar:FindFirstChild("HumanoidRootPart")
        local count = 0
        for _, plr in ipairs(Plrs:GetPlayers()) do
            if plr ~= lp and plr.Character then
                local root = plr.Character:FindFirstChild("HumanoidRootPart")
                if root and lpRoot and (root.Position - lpRoot.Position).Magnitude > 60 then
                    local anim = plr.Character:FindFirstChildWhichIsA("Animator")
                    if anim then
                        pcall(function() anim.PlaybackSpeed = 0 end)
                        table.insert(st.connections, { anim = anim })
                        count = count + 1
                    end
                end
            end
        end
        if count > 0 then warn("[JEYHUB-ZL] LOD aktif " .. _CHR.EM_DASH .. " "..count.." animator diperlambat.") end
    end)
end
_ZL.restoreCharLOD = function()
    local st = _STATE.lod
    if not st.active or not _canToggle("lod") then return end
    st.active = false
    task.defer(function()
        for _, entry in ipairs(st.connections) do
            pcall(function()
                if entry.anim and entry.anim.Parent then entry.anim.PlaybackSpeed = 1 end
            end)
        end
        st.connections = {}
        warn("[JEYHUB-ZL] LOD karakter dinonaktifkan.")
    end)
end
_ZL.aggressiveGC = function()
    task.defer(function()
        pcall(function() collectgarbage("step", 500) end)
    end)
end
if typeof(getgenv) == "function" then
    if getgenv().JEYHUB_CONNECTIONS then
        for _, conn in pairs(getgenv().JEYHUB_CONNECTIONS) do
            if conn then pcall(function() conn:Disconnect() end) end
        end
    end
    getgenv().JEYHUB_CONNECTIONS = {}
    getgenv().JEYHUB_INTRO_DONE = nil
end
local JEYHUB_RUN_TOKEN = (typeof(getgenv) == "function") and (tick() .. "_" .. tostring(math.random(1, 1e9))) or nil
if typeof(getgenv) == "function" and not getgenv()._JEYHUB_ZERO_LAG_PATCH then
    getgenv()._JEYHUB_ZERO_LAG_PATCH = true
end
if typeof(getgenv) == "function" then
    getgenv().JEYHUB_RUN_TOKEN = JEYHUB_RUN_TOKEN
end
local function IsCurrentRun()
    if not JEYHUB_RUN_TOKEN or typeof(getgenv) ~= "function" then return true end
    return getgenv().JEYHUB_RUN_TOKEN == JEYHUB_RUN_TOKEN
end
local function TrackConnection(conn)
    if conn and typeof(getgenv) == "function" then
        pcall(function() table.insert(getgenv().JEYHUB_CONNECTIONS, conn) end)
    end
    return conn
end
local function SafeService(name)
    local ok, svc = pcall(function() return game:GetService(name) end)
    if ok and typeof(svc) == "Instance" then return svc end
    if ok and svc ~= nil then
        warn("[JEYHUB] Service", name, "returned an unexpected type:", typeof(svc))
        return nil
    end
    warn("[JEYHUB] Failed to get service:", name, svc)
    return nil
end
local TweenService       = SafeService("TweenService")
local UserInputService   = SafeService("UserInputService")
local Players            = SafeService("Players")
local VoiceChatService   = SafeService("VoiceChatService")
local ContentProvider    = SafeService("ContentProvider")
local RunService         = SafeService("RunService")
local _JEYHUB_FPS     = 60
local _JEYHUB_FPS_EMA = 60
local _JEYHUB_SNOW_REGISTRY = {}
local _JEYHUB_SNOW_STARTED  = false
local _UDim2 = UDim2.new
local _mrand = math.random
local _snowSin      = math.sin
local _snowCos      = math.cos
local _snowPI2      = math.pi * 2
local _snowExp      = math.exp
local _snowAbs      = math.abs
local _snowRand     = math.random
local _snowClamp    = math.clamp
local _SNOW_INIT_DONE = false
local function _InitFlakeExtended(fl)
    for _, sys in ipairs(_JEYHUB_SNOW_REGISTRY) do
        for _, f in ipairs(sys.flakes) do
            if not f._smooth then
                f._smooth  = true
                f._vx      = 0
                f._vy      = 0
                f._rx      = f.x
                f._ry      = f.y
                f._phase   = _snowRand() * _snowPI2
                f._sway    = _snowRand() * 0.00028 + 0.00012
                f._swayF   = _snowRand() * 0.20 + 0.12
            end
        end
    end
end
local function _SnowMasterStart()
    if _JEYHUB_SNOW_STARTED or not RunService then return end
    _JEYHUB_SNOW_STARTED = true
    RunService.RenderStepped:Connect(function(dt)
        if not IsCurrentRun() then return end
        local safeDt   = math.max(dt, 0.0001)
        local frameFPS = 1 / safeDt
        _JEYHUB_FPS_EMA = _JEYHUB_FPS_EMA * 0.88 + frameFPS * 0.12
        _JEYHUB_FPS     = _JEYHUB_FPS_EMA
        if _JEYHUB_FPS < 10 then return end
        local cdt = safeDt * (1 - _snowExp(-safeDt * 24))
        cdt = _snowClamp(cdt, 0.0001, 0.025)
        local now = tick()
        if not _SNOW_INIT_DONE and #_JEYHUB_SNOW_REGISTRY > 0 then
            _SNOW_INIT_DONE = true
            _InitFlakeExtended()
        end
        for si = 1, #_JEYHUB_SNOW_REGISTRY do
            local sys = _JEYHUB_SNOW_REGISTRY[si]
            if sys.guardFn() then
                local fl  = sys.flakes
                local sy  = sys.sy
                local sx  = sys.sx
                local mxY = sys.mxY
                local rsY = sys.rsY
                for i = 1, #fl do
                    local f = fl[i]
                    if f._smooth then
                        local sway = _snowSin(now * f._swayF * _snowPI2 + f._phase) * f._sway * sx
                        local tvx = (f.drift + sway) * sx
                        local tvy = f.speed * sy
                        local lerpK = 1 - _snowExp(-cdt * 18)
                        f._vx = f._vx + (tvx - f._vx) * lerpK
                        f._vy = f._vy + (tvy - f._vy) * lerpK
                        local ny = f.y + f._vy * cdt
                        local nx = f.x + f._vx * cdt
                        if ny > mxY then
                            ny = rsY
                            nx = _snowRand()
                            f._vx = 0
                            f._vy = 0
                            f._rx = nx
                            f._ry = ny
                        end
                        if nx < -0.02 then nx = 1.02 elseif nx > 1.02 then nx = -0.02 end
                        f.y = ny
                        f.x = nx
                        local rk = 1 - _snowExp(-cdt * 55)
                        f._rx = f._rx + (nx - f._rx) * rk
                        f._ry = f._ry + (ny - f._ry) * rk
                        f.frame.Position = _UDim2(f._rx, 0, f._ry, 0)
                    else
                        local ny = f.y + f.speed * cdt * sy
                        local nx = f.x + f.drift * cdt * sx
                        if ny > mxY then ny = rsY
                        nx = _mrand() end
                        if nx < -0.02 then nx = 1.02 elseif nx > 1.02 then nx = -0.02 end
                        f.y = ny
                        f.x = nx
                        f.frame.Position = _UDim2(nx, 0, ny, 0)
                    end
                end
            end
        end
    end)
end
local function _RegisterSnow(flakes, canvas, sy, sx, mxY, rsY, guardFn)
    table.insert(_JEYHUB_SNOW_REGISTRY, {
        flakes  = flakes,
        canvas  = canvas,
        sy      = sy,
        sx      = sx,
        mxY     = mxY,
        rsY     = rsY,
        guardFn = guardFn,
    })
    _SnowMasterStart()
end
if not (getgenv and getgenv()._JEYHUB_ZL_INIT) then
    if getgenv then getgenv()._JEYHUB_ZL_INIT = true end
    _ZL.gameNormalizer()
    if RunService then
        local _zlLastTick = tick()
        RunService.Heartbeat:Connect(function()
            if not IsCurrentRun() then return end
            local now = tick()
            local dt  = now - _zlLastTick
            _zlLastTick = now
            _ZL.autoLagManager(dt)
        end)
    end
end
local LocalPlayer = Players and Players.LocalPlayer
local HttpService = SafeService("HttpService")
local JD_FOLDER = "JEYHUB"
local JD_PATH = JD_FOLDER .. "/data.json"
local JD_MAX_BYTES = 8 * 1024 * 1024
local hasFS = (typeof(writefile) == "function") and (typeof(readfile) == "function")
local JD_Store = {
    _meta = { version = 1 },
}
local JD_Loaded = false
local function JD_EnsureFolder()
    pcall(function()
        if typeof(makefolder) == "function" and typeof(isfolder) == "function" then
            if not isfolder(JD_FOLDER) then makefolder(JD_FOLDER) end
        end
