local function SafeCall(fn, ...)
    if type(fn) ~= "function" then return end
    local ok, err = pcall(fn, ...)
    if not ok then
        warn("[JEYHUB] Runtime error caught (safe, UI keeps running):", tostring(err))
    end
end
local function ThrottledCall(fn, interval)
    interval = tonumber(interval) or 0.5
    local last = 0
    return function(...)
        local now = tick()
        if now - last >= interval then
            last = now
            local args = { ... }
            task.spawn(function()
                SafeCall(fn, table.unpack(args))
            end)
        end
    end
end
local function DebouncedCall(fn, delayTime)
    delayTime = tonumber(delayTime) or 0.3
    local thread = nil
    return function(...)
        local args = { ... }
        if thread then
            pcall(function() task.cancel(thread) end)
        end
        thread = task.delay(delayTime, function()
            thread = nil
            SafeCall(fn, table.unpack(args))
        end)
    end
end
