    local _acHooked = {}
    for _, v in getgc(true) do
        if typeof(v) == "table" then
            local DetectFunc = rawget(v, "Detected")
            local KillFunc   = rawget(v, "Kill")
            if typeof(DetectFunc) == "function" and not _acDetected then
                _acDetected = DetectFunc
                pcall(function()
                    hookfunction(_acDetected, function(Action, Info, NoCrash)
                        return true
                    end)
                end)
                table.insert(_acHooked, _acDetected)
            end
            if rawget(v, "Variables") and rawget(v, "Process")
                and typeof(KillFunc) == "function" and not _acKill then
                _acKill = KillFunc
                pcall(function()
                    hookfunction(_acKill, function(Info)
                    end)
                end)
                table.insert(_acHooked, _acKill)
            end
        end
    end
    pcall(function()
        local _dbgOld
        _dbgOld = hookfunction(getrenv().debug.info, newcclosure(function(a, ...)
            local LevelOrFunc = a
            if _acDetected and LevelOrFunc == _acDetected then
                return coroutine.yield(coroutine.running())
            end
            return _dbgOld(a, ...)
        end))
    end)
    setthreadidentity(7)
end)
