        Font             = Enum.Font.GothamBold,
        TextColor3       = Palette.SubText,
        TextSize         = 10,
        Parent           = _card,
    })
    Round(_closeBtn, 7)
    local _btnStr = Stroke(_closeBtn, Color3.fromRGB(55, 55, 55), 1, 0.35)
    _closeBtn.MouseEnter:Connect(function()
        Tween(_closeBtn, 0.1, nil, nil, { BackgroundColor3 = Color3.fromRGB(40, 10, 10), TextColor3 = Color3.fromRGB(210, 70, 70) })
        Tween(_btnStr,   0.1, nil, nil, { Color = Color3.fromRGB(170, 50, 50), Transparency = 0.1 })
    end)
    _closeBtn.MouseLeave:Connect(function()
        Tween(_closeBtn, 0.15, nil, nil, { BackgroundColor3 = Color3.fromRGB(20, 20, 20), TextColor3 = Palette.SubText })
        Tween(_btnStr,   0.15, nil, nil, { Color = Color3.fromRGB(55, 55, 55), Transparency = 0.35 })
    end)
    _closeBtn.MouseButton1Click:Connect(function()
        Tween(_overlay, 0.2, nil, nil, { BackgroundTransparency = 1 })
        Tween(_card, 0.2, Enum.EasingStyle.Back, Enum.EasingDirection.In, {
            Size = UDim2.new(0, 0, 0, 0),
        })
        task.delay(0.25, function() _sg:Destroy() end)
    end)
    task.defer(function()
        Tween(_card, 0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out, {
            Size = UDim2.new(0, 260, 0, 144),
        })
        LoopTween(_cardStroke, 2, { Transparency = 0.7 })
    end)
    return
end
local function Pad(inst, l, r, t, b)
    New("UIPadding", {
        PaddingLeft = UDim.new(0, l or 8),
        PaddingRight = UDim.new(0, r or 8),
        PaddingTop = UDim.new(0, t or 8),
        PaddingBottom = UDim.new(0, b or 8),
        Parent = inst,
    })
end
local _hoverEnterInfo = TweenInfo.new(0.16, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)
local _hoverLeaveInfo = TweenInfo.new(0.28, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)
local function AddButtonHover(btn, strokeRef, bgLift)
    if not btn then return end
    bgLift = bgLift == nil and 0.12 or bgLift
    local baseTransp = 0
    pcall(function() baseTransp = btn.BackgroundTransparency end)
    local baseStroke = nil
    if strokeRef then
        local okStroke, val = pcall(function() return strokeRef.Transparency end)
        if okStroke then baseStroke = val end
    end
    local hoverTransp  = bgLift > 0 and math.max(0, baseTransp - bgLift) or nil
    local hoverStroke  = (strokeRef and baseStroke) and math.max(0, baseStroke - 0.35) or nil
    SafeConnect(GetSignal(btn, "MouseEnter"), function()
        if hoverTransp and btn.Parent then
            TweenService:Create(btn, _hoverEnterInfo, { BackgroundTransparency = hoverTransp }):Play()
        end
        if strokeRef and hoverStroke and strokeRef.Parent then
            TweenService:Create(strokeRef, _hoverEnterInfo, { Transparency = hoverStroke }):Play()
        end
    end)
    SafeConnect(GetSignal(btn, "MouseLeave"), function()
        if hoverTransp and btn.Parent then
            TweenService:Create(btn, _hoverLeaveInfo, { BackgroundTransparency = baseTransp }):Play()
        end
        if strokeRef and baseStroke and strokeRef.Parent then
            TweenService:Create(strokeRef, _hoverLeaveInfo, { Transparency = baseStroke }):Play()
        end
    end)
end
local function ApplyBtnGradient(btn, c1, c2, rot)
    if not btn then return end
    c1  = c1  or BUTTON_COLOR
    c2  = c2  or BUTTON_COLOR_DARK
    rot = rot or 135
    pcall(function() btn.BackgroundColor3 = Color3.new(1, 1, 1) end)
    pcall(function() btn.TextColor3 = Color3.fromRGB(15, 15, 15) end)
    for _, child in ipairs(btn:GetChildren()) do
        pcall(function()
            if child:IsA("TextLabel") or child:IsA("TextButton") then
                child.TextColor3 = Color3.fromRGB(15, 15, 15)
            elseif child:IsA("ImageLabel") or child:IsA("ImageButton") then
                child.ImageColor3 = Color3.fromRGB(15, 15, 15)
            end
        end)
    end
    local grad = New("UIGradient", {
        Color    = ColorSequence.new(c1, c2),
        Rotation = rot,
        Parent   = btn,
    })
    SafeConnect(GetSignal(btn, "MouseEnter"), function()
        Tween(grad, 0.18, nil, nil, { Rotation = rot + 180 })
    end)
    SafeConnect(GetSignal(btn, "MouseLeave"), function()
        Tween(grad, 0.18, nil, nil, { Rotation = rot })
    end)
    return grad
end
