local function ApplyGradientFallback(imageLabel)
    if not imageLabel or not imageLabel.Parent then return end
    pcall(function()
        imageLabel.Image             = ""
        imageLabel.ImageTransparency = 1
        for _, c in ipairs(imageLabel:GetChildren()) do
            if c:IsA("Frame") and c:GetAttribute("JeyhubGrad") then pcall(function() c:Destroy() end) end
        end
        local pair = GRADIENT_FALLBACKS[math.random(1, #GRADIENT_FALLBACKS)]
        local gf            = Instance.new("Frame")
        gf:SetAttribute("JeyhubGrad", true)
        gf.Size             = UDim2.new(1, 0, 1, 0)
        gf.BackgroundColor3 = pair[1]
        gf.BorderSizePixel  = 0
        gf.ZIndex           = imageLabel.ZIndex
        local ug            = Instance.new("UIGradient")
        ug.Color            = ColorSequence.new(pair[1], pair[2])
        ug.Rotation         = math.random(120, 155)
        ug.Parent           = gf
        gf.Parent           = imageLabel
    end)
end
local function LoadThumbnail(imageLabel, url, retryOnce)
    if not imageLabel then return end
    pcall(function() imageLabel.Image = url end)
    if not ContentProvider then return end
    task.spawn(function()
        local status
        local ok = pcall(function()
            ContentProvider:PreloadAsync({ url }, function(_, fetchStatus)
                status = fetchStatus
            end)
        end)
        if not (imageLabel and imageLabel.Parent) then return end
        if ok and (status == _AssetFetchFailure or status == Enum.AssetFetchStatus.Failure) then
            if retryOnce ~= false then
                task.wait(0.4)
                if imageLabel and imageLabel.Parent then
                    LoadThumbnail(imageLabel, url, false)
                end
            else
                ApplyGradientFallback(imageLabel)
            end
        end
    end)
end
local _DRAG = {
    active      = false,
    target      = nil,
    startInput  = nil,
    startPos    = nil,
    pendingX    = 0,
    pendingY    = 0,
}
local _DRAG_UDim2 = UDim2.new
local _DRAG_GLOBAL_OK = false
local function _EnsureDragGlobal()
    if _DRAG_GLOBAL_OK then return end
    _DRAG_GLOBAL_OK = true
    if UserInputService then
        UserInputService.InputChanged:Connect(function(inp)
            local d = _DRAG
            if not d.active then return end
            if inp.UserInputType == Enum.UserInputType.MouseMovement
                or inp.UserInputType == Enum.UserInputType.Touch then
                local delta = inp.Position - d.startInput
                d.pendingX  = d.startPos.X.Offset + delta.X
                d.pendingY  = d.startPos.Y.Offset + delta.Y
            end
        end)
        UserInputService.InputEnded:Connect(function(inp)
            if inp.UserInputType == Enum.UserInputType.MouseButton1
                or inp.UserInputType == Enum.UserInputType.Touch then
                _DRAG.active = false
            end
        end)
    end
    if RunService then
        local _dragLerpX, _dragLerpY = 0, 0
        local _dragLerpK = 1.0
        RunService.RenderStepped:Connect(function(dt)
            local d = _DRAG
            if not d.active or not d.target then
                _dragLerpX = d.pendingX
                _dragLerpY = d.pendingY
                return
            end
            local k = 1 - math.exp(-dt * 110)
            _dragLerpX = _dragLerpX + (d.pendingX - _dragLerpX) * k
            _dragLerpY = _dragLerpY + (d.pendingY - _dragLerpY) * k
            d.target.Position = _DRAG_UDim2(
                d.startPos.X.Scale, _dragLerpX,
                d.startPos.Y.Scale, _dragLerpY
            )
        end)
    end
end
local function MakeDraggable(handle, target)
    if not handle or not target then return end
    _EnsureDragGlobal()
    SafeConnect(GetSignal(handle, "InputBegan"), function(inp)
        if inp.UserInputType == Enum.UserInputType.MouseButton1
            or inp.UserInputType == Enum.UserInputType.Touch then
            local d    = _DRAG
            local pos  = target.Position
            d.active      = true
            d.target      = target
            d.startInput  = inp.Position
            d.startPos    = pos
            d.pendingX    = pos.X.Offset
            d.pendingY    = pos.Y.Offset
            SafeConnect(GetSignal(inp, "Changed"), function()
                if inp.UserInputState == Enum.UserInputState.End then
                    if _DRAG.target == target then _DRAG.active = false end
                end
            end)
        end
    end)
end
local function NewElementRoot(parent, height)
    local root = New("Frame", {
        Size = UDim2.new(1, 0, 0, height or 40),
        BackgroundColor3 = Palette.Element,
        BackgroundTransparency = 0.15,
        Parent = parent,
    })
    Round(root, 8)
    Stroke(root, Palette.StrokeSoft, 1, 0.4)
    return root
end
local function AddTitles(root, title, subtitle, rightInset)
    local holder = New("Frame", {
        Size = UDim2.new(1, -(rightInset or 0), 1, 0),
        BackgroundTransparency = 1,
        Parent = root,
    })
    Pad(holder, 10, 10, 4, 4)
    New("UIListLayout", {
        FillDirection = Enum.FillDirection.Vertical,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 1),
        Parent = holder,
    })
    local titleLabel = New("TextLabel", {
        Text = (title and tostring(title)) or "Example",
        Font = Enum.Font.GothamMedium,
        TextSize = 13,
        TextColor3 = Palette.Text,
        TextXAlignment = Enum.TextXAlignment.Left,
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, 16),
        LayoutOrder = 1,
        Parent = holder,
    })
    local subtitleLabel = nil
    if subtitle and tostring(subtitle) ~= "" then
        subtitleLabel = New("TextLabel", {
            Text = tostring(subtitle),
            Font = Enum.Font.Gotham,
            TextSize = 11,
            TextColor3 = Palette.SubText,
            TextXAlignment = Enum.TextXAlignment.Left,
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 13),
            LayoutOrder = 2,
            Parent = holder,
        })
    end
    return { Holder = holder, TitleLabel = titleLabel, SubtitleLabel = subtitleLabel }
end
local ActiveFloatingPopup = { close = nil }
local function CloseActiveFloatingPopup(exceptCloseFn)
