        Rotation = 90,
        Parent = self.Frame,
    })
    local hasSubtitle = subtitle and tostring(subtitle) ~= ""
    local headerHeight = hasSubtitle and 48 or 30
    local header = New("Frame", {
        Size = UDim2.new(1, 0, 0, headerHeight),
        BackgroundTransparency = 1,
        Parent = self.Frame,
    })
    Pad(header, 10, 12, 0, 0)
    local tickH = hasSubtitle and 30 or 14
    local tickBar = New("Frame", {
        Size = UDim2.new(0, 3, 0, tickH),
        Position = UDim2.new(0, 0, 0, 6),
