        Color = ColorSequence.new(self.Accent, Color3.new(0.9961, 0.9961, 0.9961)),
        Rotation = 90,
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0),
            NumberSequenceKeypoint.new(1, 0.55),
        }),
        Parent = tickBar,
    })
    RegisterThemeApplier(function(c, darker)
        pcall(function()
            self.Accent = c
            if _sectionStroke and _sectionStroke.Parent then
                _sectionStroke.Color = c
            end
            if tickBar and tickBar.Parent then
                tickBar.BackgroundColor3 = c
            end
            if _tickGradient and _tickGradient.Parent then
                _tickGradient.Color = ColorSequence.new(c, Color3.new(0.9961, 0.9961, 0.9961))
            end
        end)
    end)
    local titleSize = hasSubtitle and UDim2.new(1, -12, 0, 16) or UDim2.new(1, -12, 1, 0)
    local titlePos  = hasSubtitle and UDim2.new(0, 12, 0, 6) or UDim2.new(0, 12, 0, 0)
    New("TextLabel", {
        Text = (title and tostring(title)) or "Example",
        Font = Enum.Font.GothamBold,
        TextSize = 13,
        TextColor3 = Palette.Text,
        TextXAlignment = Enum.TextXAlignment.Left,
        BackgroundTransparency = 1,
        Position = titlePos,
        Size = titleSize,
        Parent = header,
    })
    if hasSubtitle then
        New("TextLabel", {
            Text = tostring(subtitle),
            Font = Enum.Font.Gotham,
            TextSize = 11,
            TextColor3 = Palette.SubText,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextWrapped = true,
            BackgroundTransparency = 1,
            Position = UDim2.new(0, 12, 0, 24),
            Size = UDim2.new(1, -24, 0, 18),
            Parent = header,
        })
    end
    self.Body = New("Frame", {
        Size = UDim2.new(1, 0, 0, 0),
        AutomaticSize = _AutomaticSizeY or Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        Position = UDim2.new(0, 0, 0, headerHeight),
        Parent = self.Frame,
    })
    Pad(self.Body, 10, 10, 0, 10)
    New("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 6),
        Parent = self.Body,
    })
    return self
end
function Section.new(parent, accent, title, subtitle)
    local ok, result = pcall(Section.newImpl, parent, accent, title, subtitle)
    if ok and result then return result end
    warn("[JEYHUB] Section failed to build, using safe fallback Section:", result)
    local fallback = setmetatable({}, Section)
    fallback.Accent = accent or Palette.Accent
    fallback.Frame = New("Frame", { Size = UDim2.new(1,0,0,0), AutomaticSize = _AutomaticSizeY or Enum.AutomaticSize.Y, BackgroundTransparency = 1, Parent = parent })
    fallback.Body = fallback.Frame
    return fallback
end
function Section:CreateButtonImpl(config)
    config = (type(config) == "table") and config or {}
    local root = NewElementRoot(self.Body, 40)
    AddTitles(root, config.Title, config.Subtitle, 70)
    local btn = New("TextButton", {
        Text = config.ButtonText or "Run",
        Font = Enum.Font.GothamMedium,
        TextSize = 12,
        TextColor3 = Color3.fromRGB(10, 10, 10),
        AutoButtonColor = false,
        BackgroundColor3 = Color3.new(1, 1, 1),
        Size = UDim2.new(0, 56, 0, 24),
        Position = UDim2.new(1, -64, 0.5, -12),
        Parent = root,
    })
    Round(btn, 6)
    local btnGradient = New("UIGradient", {
        Color = ColorSequence.new(BUTTON_COLOR, BUTTON_COLOR_DARK),
        Rotation = 135,
        Parent = btn,
    })
    local sheen = New("Frame", {
        Size = UDim2.new(1, 0, 0.5, 0),
        BackgroundColor3 = Color3.new(0.9961, 0.9961, 0.9961),
        BackgroundTransparency = 0.88,
        Parent = btn,
    })
    Round(sheen, 6)
    New("UIGradient", {
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0),
            NumberSequenceKeypoint.new(1, 1),
        }),
        Rotation = 90,
        Parent = sheen,
    })
    SafeConnect(GetSignal(btn, "MouseEnter"), function()
        Tween(btnGradient, 0.18, nil, nil, { Rotation = 315 })
    end)
    SafeConnect(GetSignal(btn, "MouseLeave"), function()
        Tween(btnGradient, 0.18, nil, nil, { Rotation = 135 })
    end)
    local lastClick = 0
    local function performClick()
        if os.clock() - lastClick < 0.1 then return end
        lastClick = os.clock()
        CreateRipple(btn)
        Tween(btn, 0.08, nil, nil, { Size = UDim2.new(0, 52, 0, 22), Position = UDim2.new(1, -62, 0.5, -11) })
        task.delay(0.08, function()
            Tween(btn, 0.12, Enum.EasingStyle.Back, nil, { Size = UDim2.new(0, 56, 0, 24), Position = UDim2.new(1, -64, 0.5, -12) })
        end)
        if config.Callback then SafeCall(config.Callback) end
    end
    SafeConnect(GetSignal(btn, "MouseButton1Click"), performClick)
    SafeConnect(GetSignal(btn, "Activated"), performClick)
    return root
end
function Section:CreateButton(config)
