            DirectConnect(GetSignal(RunService, "RenderStepped"), function()
                local now = os.clock()
                if now - lastUpdate < 1.5 then return end
                lastUpdate = now
                if Window and Window.Minimized then return end
                if root.Visible and MouseSpotlight.Parent then
                    local relX = UserMouse.X - root.AbsolutePosition.X
                    local relY = UserMouse.Y - root.AbsolutePosition.Y
                    local dx, dy = relX - lastSpotX, relY - lastSpotY
                    if dx*dx + dy*dy < 64 then return end
                    lastSpotX, lastSpotY = relX, relY
                    Tween(MouseSpotlight, 0.5, Enum.EasingStyle.Sine, nil, { Position = UDim2.new(0, relX, 0, relY) })
