function Library.new(title, subtitle)
    local ok, result = pcall(Library.newImpl, title, subtitle)
    if ok and result then return result end
    warn("[JEYHUB] Window creation failed entirely (caught safely):", result)
    return setmetatable({ Tabs = {}, CurrentTab = nil }, Library)
end
local function GetSidebarTooltip(library)
    if library.SidebarTooltip then return library.SidebarTooltip end
    if not library.Main then return nil end
    local tooltip = New("TextLabel", {
        Font = Enum.Font.GothamMedium, TextSize = 11,
        TextColor3 = Palette.Text,
        BackgroundColor3 = Palette.Glass,
        BackgroundTransparency = 0.05,
        AutomaticSize = _AutomaticSizeX or Enum.AutomaticSize.X,
        Size = UDim2.new(0, 0, 0, 24),
        Visible = false,
        ZIndex = 50,
        TextXAlignment = Enum.TextXAlignment.Center,
        Parent = library.Main,
    })
    Round(tooltip, 6)
    Stroke(tooltip, Palette.Accent, 1, 0.4)
    Pad(tooltip, 8, 8, 0, 0)
    library.SidebarTooltip = tooltip
    return tooltip
end
function Library:CreateTabImpl(name)
    if not self.Sidebar then
        return {
            CreateSection = function() return setmetatable({ Body = Instance.new("Folder") }, Section) end,
            OnBuild = function() end,
        }
    end
    name = tostring(name or "Tab")
    local accent = TabAccents[name] or Palette.Accent
    local btn = New("TextButton", {
        Size = UDim2.new(1, 0, 0, 38),
        BackgroundColor3 = Palette.Element,
        BackgroundTransparency = 0.2,
        Text = "",
        Parent = self.Sidebar,
    })
    Round(btn, 9)
    local btnGlow = Stroke(btn, accent, 1, 1)
    local tick = New("Frame", {
        Size = UDim2.new(0, 3, 0, 16),
        Position = UDim2.new(0, 3, 0.5, -8),
        BackgroundColor3 = accent,
        BackgroundTransparency = 1,
        Parent = btn,
    })
    Round(tick, 2)
    New("UIGradient", {
        Color = ColorSequence.new(accent, Color3.new(0.9961, 0.9961, 0.9961)),
        Rotation = 90,
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0),
            NumberSequenceKeypoint.new(1, 0.5),
        }),
        Parent = tick,
    })
    local icon = TabIcons[name]
    local label = New("ImageLabel", {
        Image = icon or "",
        BackgroundTransparency = 1,
        ImageColor3 = Palette.SubText,
        ScaleType = Enum.ScaleType.Fit,
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.new(0.5, 2, 0.5, 0),
        Size = UDim2.fromOffset(18, 18),
        Parent = btn,
    })
    local function makeFallbackLetter()
        label.Visible = false
        New("TextLabel", {
            Text = string.sub(name, 1, 1), Font = Enum.Font.GothamMedium, TextSize = 16,
            TextColor3 = Palette.SubText, BackgroundTransparency = 1,
            TextXAlignment = Enum.TextXAlignment.Center,
            TextYAlignment = Enum.TextYAlignment.Center,
            Position = UDim2.new(0, 4, 0, 0), Size = UDim2.new(1, -4, 1, 0),
            Parent = btn,
        })
    end
    if not icon then
        makeFallbackLetter()
    else
        task.spawn(function()
            local cp = pcall(function()
                game:GetService("ContentProvider"):PreloadAsync({label}, function(_, status)
                    if status == _AssetFetchFailure or status == Enum.AssetFetchStatus.Failure then
                        makeFallbackLetter()
                    end
                end)
            end)
            if not cp then makeFallbackLetter() end
        end)
    end
    local page = New("ScrollingFrame", {
        Size = UDim2.new(1, 0, 1, 0),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ScrollBarThickness = 3,
        ScrollBarImageColor3 = accent,
        VerticalScrollBarInset = _ScrollBarInsetAlways or Enum.ScrollBarInset.Always,
        CanvasSize = UDim2.new(0,0,0,0),
        AutomaticCanvasSize = _AutomaticSizeY or Enum.AutomaticSize.Y,
        Visible = false,
        Parent = self.Pages,
    })
    Pad(page, 8, 8, 8, 8)
    New("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0,8), Parent = page })
    local tabObj = {
        Name = name, Accent = accent, Page = page, Button = btn,
        Label = label, Tick = tick, Glow = btnGlow, GlowLoop = nil,
        Built = false, BuildFn = nil,
    }
    function tabObj:CreateSection(title, subtitle)
        return Section.new(self.Page, self.Accent, title, subtitle)
    end
    function tabObj:OnBuild(fn)
        self.BuildFn = fn
    end
    local library = self
    local function selectTab()
        if library.CurrentTab == tabObj then return end
        CloseActiveFloatingPopup(nil)
        local prevTabObj = library.CurrentTab
        if library._pageActiveTween then
            pcall(function() library._pageActiveTween:Cancel() end)
            library._pageActiveTween = nil
        end
        if library._pageOutTween then
            pcall(function() library._pageOutTween:Cancel() end)
            library._pageOutTween = nil
        end
        library._tabSwitchToken = (library._tabSwitchToken or 0) + 1
        local myToken = library._tabSwitchToken
        for _, t in ipairs(library.Tabs) do
            if t.Page and t ~= tabObj and t ~= prevTabObj then
                pcall(function()
                    t.Page.Visible  = false
                    t.Page.Position = UDim2.new(0, 0, 0, 0)
                    t.Page.ZIndex   = 1
                end)
            end
            Tween(t.Button, 0.15, nil, nil, { BackgroundColor3 = Palette.Element, BackgroundTransparency = 0.2 })
            if t.Label then Tween(t.Label, 0.15, nil, nil, { ImageColor3 = Palette.SubText }) end
            if t.Tick  then Tween(t.Tick,  0.15, nil, nil, { BackgroundTransparency = 1 }) end
            if t.GlowLoop then
                pcall(function() t.GlowLoop:Cancel() end)
                t.GlowLoop = nil
            end
            if t.Glow then Tween(t.Glow, 0.15, nil, nil, { Transparency = 1 }) end
        end
        if not tabObj.Built and tabObj.BuildFn then
            tabObj.Built = true
            SafeCall(tabObj.BuildFn)
        end
        local OUT_TIME  = 0.25
        local IN_TIME   = 0.38
        local SLIDE_OFF = UDim2.new(-1, 0, 0, 0)
        if prevTabObj and prevTabObj.Page and prevTabObj.Page.Parent then
            local prevPage     = prevTabObj.Page
            local capturedPrev = prevTabObj
            pcall(function()
                prevPage.Position = UDim2.new(0, 0, 0, 0)
                prevPage.ZIndex   = 2
            end)
            library._pageOutTween = Tween(prevPage, OUT_TIME, Enum.EasingStyle.Quad, Enum.EasingDirection.In, {
                Position = SLIDE_OFF,
            })
            local capturedToken = myToken
