            page.Visible  = true
            page.ZIndex   = 3
        end)
        library._pageActiveTween = Tween(page, IN_TIME, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, {
            Position = UDim2.new(0, 0, 0, 0),
        })
        local capturedToken2 = myToken
        task.delay(IN_TIME + 0.06, function()
            if library._tabSwitchToken ~= capturedToken2 then return end
            pcall(function()
                if page and page.Parent then
                    page.ZIndex = 1
                    page.CanvasPosition = Vector2.new(0, 0)
                end
            end)
            library._pageActiveTween = nil
        end)
        Tween(btn,   0.15, nil, nil, { BackgroundColor3 = accent, BackgroundTransparency = 0.75 })
        Tween(label, 0.15, nil, nil, { ImageColor3 = Palette.Text })
        Tween(tick,  0.15, nil, nil, { BackgroundTransparency = 0 })
        tabObj.GlowLoop = LoopTween(btnGlow, 2.4, { Transparency = 0.85 })
        library.CurrentTab = tabObj
    end
    tabObj.Select = selectTab
    SafeConnect(GetSignal(btn, "MouseButton1Click"), function()
        if library.CurrentTab ~= tabObj then
            PlayUISound("Tab")
            CreateRipple(btn)
        end
        selectTab()
    end)
    SafeConnect(GetSignal(btn, "Activated"), selectTab)
    SafeConnect(GetSignal(btn, "MouseEnter"), function()
        local tooltip = GetSidebarTooltip(library)
        if tooltip then
            pcall(function()
                local relY = btn.AbsolutePosition.Y - library.Main.AbsolutePosition.Y + (btn.AbsoluteSize.Y / 2) - 12
                local relX = btn.AbsolutePosition.X - library.Main.AbsolutePosition.X + btn.AbsoluteSize.X + 8
                tooltip.Position = UDim2.new(0, relX, 0, relY)
                tooltip.Text = name
                tooltip.Visible = true
            end)
        end
        if library.CurrentTab ~= tabObj then
            Tween(btn, 0.10, nil, nil, { BackgroundTransparency = 0.05 })
            Tween(btnGlow, 0.10, nil, nil, { Transparency = 0.75 })
        end
    end)
    SafeConnect(GetSignal(btn, "MouseLeave"), function()
        if library.SidebarTooltip then library.SidebarTooltip.Visible = false end
        if library.CurrentTab ~= tabObj then
            Tween(btn, 0.10, nil, nil, { BackgroundTransparency = 0.2 })
            Tween(btnGlow, 0.10, nil, nil, { Transparency = 1 })
        end
    end)
    table.insert(self.Tabs, tabObj)
    if #self.Tabs == 1 then
        task.defer(selectTab)
    end
    return tabObj
end
function Library:CreateTab(name)
    local ok, result = pcall(function() return self:CreateTabImpl(name) end)
    if ok and result then return result end
    warn("[JEYHUB] Tab '"..tostring(name).."' failed to build, using safe fallback tab:", result)
    return {
        CreateSection = function() return setmetatable({ Body = Instance.new("Folder") }, Section) end,
        OnBuild = function() end,
    }
end
local function WaitForGameLoaded()
    pcall(function()
        if not game:IsLoaded() then
            local finished = false
            local conn
            conn = game.Loaded:Connect(function() finished = true end)
            local waited = 0
            while not finished and waited < 20 do
                task.wait(0.5)
                waited = waited + 0.5
            end
            if conn then pcall(function() conn:Disconnect() end) end
        end
    end)
end
