        liveStatGen = liveStatGen + 1
    end
    local CACHE_TTL = 300
    local PlayerDataCache = {}
    function H.MakeRequestQueue(gapSeconds)
        local queue = {}
        local running = false
        local q = {}
        function q.Enqueue(job, highPriority)
            if highPriority then
                table.insert(queue, 1, job)
            else
                table.insert(queue, job)
            end
            if running then return end
            running = true
            task.spawn(function()
                while #queue > 0 do
                    local job2 = table.remove(queue, 1)
                    pcall(job2)
                    task.wait(gapSeconds)
                end
                running = false
            end)
        end
        return q
    end
    local UsersQueue = H.MakeRequestQueue(1.0)
    local AccountInfoQueue = H.MakeRequestQueue(1.0)
    local CatalogQueue = H.MakeRequestQueue(1.5)
    local GamesQueue = H.MakeRequestQueue(1.2)
    local GroupsQueue = H.MakeRequestQueue(1.2)
    local FriendsCountQueue = H.MakeRequestQueue(1.0)
    local GenericQueue = H.MakeRequestQueue(1.0)
    function H.EnqueueRequest(job, highPriority) GenericQueue.Enqueue(job, highPriority) end
    local FRIENDS_REQUEST_GAP = 2.5
    local FRIENDS_BACKOFF_ON_429 = 45
    local friendsQueue = {}
    local friendsQueueRunning = false
    local friendsBackoffUntil = 0
    function H.EnqueueFriendsRequest(job, highPriority)
        if highPriority then
            table.insert(friendsQueue, 1, job)
        else
            table.insert(friendsQueue, job)
        end
        if friendsQueueRunning then return end
        friendsQueueRunning = true
        task.spawn(function()
            while #friendsQueue > 0 do
                local now = os.clock()
                if now < friendsBackoffUntil then
                    task.wait(friendsBackoffUntil - now)
                end
                local job2 = table.remove(friendsQueue, 1)
                pcall(job2)
                task.wait(FRIENDS_REQUEST_GAP)
            end
            friendsQueueRunning = false
        end)
    end
    function H.GetCacheEntry(userId)
        local key = tostring(userId)
        local entry = PlayerDataCache[key]
        if not entry then
            entry = {}
            PlayerDataCache[key] = entry
        end
        return entry
    end
    local currentDisplayedUserId = nil
    local RenderMoreMutualFriends = nil
    local RenderMoreMutualGlobalFriends = nil
    local activeFriendsMap = {}
    local friendsInServerText = {}
    local FRIENDS_LEFT_MAX = 15
    local friendsLeftMap = {}
    local friendsLeftText = {}
    function H.saveFriendsLeftData()
        local out = {}
        for userId, list in pairs(friendsLeftMap) do
            out[tostring(userId)] = list
        end
        JD_Set("friendsLeft", out)
    end
    function H.loadFriendsLeftData()
        local data = JD_Get("friendsLeft", nil)
        if type(data) ~= "table" then return end
        local clean = {}
        for key, list in pairs(data) do
            local userId = tonumber(key)
            if userId and type(list) == "table" then
                local cleanList = {}
                for _, rec in ipairs(list) do
                    if type(rec) == "table" and type(rec.name) == "string" and type(rec.at) == "number" then
                        table.insert(cleanList, { name = rec.name, at = rec.at })
                    end
                end
                if #cleanList > 0 then clean[userId] = cleanList end
            end
        end
        friendsLeftMap = clean
    end
    H.loadFriendsLeftData()
    function H.RebuildFriendsLeftText(userId)
        local list = friendsLeftMap[userId]
        if list and #list > 0 then
            local parts = {}
            for _, rec in ipairs(list) do
                table.insert(parts, rec.name .. " (pukul " .. os.date("%H:%M:%S", rec.at) .. ")")
            end
            friendsLeftText[userId] = table.concat(parts, ", ")
        else
            friendsLeftText[userId] = "No friends have left the server while monitored"
        end
        if currentDisplayedUserId == userId and Stats.statFriendsLeft then
            pcall(function() Stats.statFriendsLeft.Text = friendsLeftText[userId] end)
        end
    end
    function H.RecordFriendLeft(forUserId, leftName)
        local list = friendsLeftMap[forUserId]
        if not list then
            list = {}
            friendsLeftMap[forUserId] = list
        end
        table.insert(list, 1, { name = leftName, at = os.time() })
        while #list > FRIENDS_LEFT_MAX do table.remove(list) end
        H.saveFriendsLeftData()
        H.RebuildFriendsLeftText(forUserId)
    end
    for userId in pairs(friendsLeftMap) do H.RebuildFriendsLeftText(userId) end
    function H.RebuildFriendsInServerText(userId)
        local names = {}
        local map = activeFriendsMap[userId]
        if map then
            for otherId, _ in pairs(map) do
                local otherPlr = Players:GetPlayerByUserId(otherId)
                if otherPlr then
                    table.insert(names, (otherPlr.DisplayName or otherPlr.Name) .. " (@" .. otherPlr.Name .. ")")
                end
            end
        end
        if #names > 0 then
            friendsInServerText[userId] = table.concat(names, ", ")
        else
            friendsInServerText[userId] = "No friends currently in this server"
        end
        if currentDisplayedUserId == userId and Stats.statFriendsInServer then
            pcall(function() Stats.statFriendsInServer.Text = friendsInServerText[userId] end)
        end
    end
    function H.RebuildMutualFriendsDisplay()
        local uid = currentDisplayedUserId
        if not uid or not Stats.statMutualCount or not statMutualNames then return end
        if uid == (LocalPlayer and LocalPlayer.UserId) then
            Stats.statMutualCount.Text = "This is you"
            statMutualNames.Text = "-"
            if statMutualLoadMoreBtn then statMutualLoadMoreBtn.Visible = false end
            return
        end
        local myMap = LocalPlayer and activeFriendsMap[LocalPlayer.UserId]
        local targetMap = activeFriendsMap[uid]
        local mutualPlrs = {}
        if myMap and targetMap then
            for otherId, _ in pairs(myMap) do
                if targetMap[otherId] then
                    local otherPlr = Players:GetPlayerByUserId(otherId)
                    if otherPlr then table.insert(mutualPlrs, otherPlr) end
                end
            end
        end
        Stats.statMutualCount.Text = tostring(#mutualPlrs)
        if #mutualPlrs == 0 then
            statMutualNames.Text = "No mutual friends currently in this server"
            if statMutualLoadMoreBtn then statMutualLoadMoreBtn.Visible = false end
            RenderMoreMutualFriends = nil
            return
        end
        local MUTUAL_PAGE_SIZE = 8
        local shown = 0
        local function RenderMutualPage()
            shown = math.min(shown + MUTUAL_PAGE_SIZE, #mutualPlrs)
            local names = {}
            for i = 1, shown do
                local p = mutualPlrs[i]
                table.insert(names, (p.DisplayName or p.Name) .. " (@" .. p.Name .. ")")
            end
            statMutualNames.Text = ("(%d total, showing %d) "):format(#mutualPlrs, shown)
                .. table.concat(names, ", ")
            if statMutualLoadMoreBtn then statMutualLoadMoreBtn.Visible = shown < #mutualPlrs end
        end
        RenderMutualPage()
        RenderMoreMutualFriends = RenderMutualPage
    end
    function H.CheckFriendPair(p1, p2)
        if not (p1 and p2 and p1.Parent and p2.Parent) then return end
        if activeFriendsMap[p1.UserId] and activeFriendsMap[p1.UserId][p2.UserId] then return end
        local ok, isFriend = pcall(function() return p1:IsFriendsWith(p2.UserId) end)
        if ok and isFriend then
            activeFriendsMap[p1.UserId] = activeFriendsMap[p1.UserId] or {}
            activeFriendsMap[p1.UserId][p2.UserId] = true
            activeFriendsMap[p2.UserId] = activeFriendsMap[p2.UserId] or {}
            activeFriendsMap[p2.UserId][p1.UserId] = true
            H.RebuildFriendsInServerText(p1.UserId)
            H.RebuildFriendsInServerText(p2.UserId)
            H.RebuildMutualFriendsDisplay()
        end
    end
    function H.ScanAllFriendPairs()
        local plrs = Players:GetPlayers()
        for i = 1, #plrs do
            for j = i + 1, #plrs do
                H.CheckFriendPair(plrs[i], plrs[j])
                task.wait(0.05)
            end
        end
    end
    SafeConnect(Players.PlayerAdded, function(newPlr)
        H.RebuildFriendsInServerText(newPlr.UserId)
        task.spawn(function()
            task.wait(1)
            for _, other in ipairs(Players:GetPlayers()) do
                if other ~= newPlr then
                    H.CheckFriendPair(newPlr, other)
                    task.wait(0.05)
                end
            end
        end)
    end)
    SafeConnect(Players.PlayerRemoving, function(leavingPlr)
        local leavingName = leavingPlr.DisplayName and (leavingPlr.DisplayName .. " (@" .. leavingPlr.Name .. ")") or leavingPlr.Name
        activeFriendsMap[leavingPlr.UserId] = nil
        for uid, map in pairs(activeFriendsMap) do
            if map[leavingPlr.UserId] then
                map[leavingPlr.UserId] = nil
                H.RebuildFriendsInServerText(uid)
                H.RecordFriendLeft(uid, leavingName)
            end
        end
        H.RebuildMutualFriendsDisplay()
    end)
    task.spawn(H.ScanAllFriendPairs)
    task.spawn(function()
        while true do
            task.wait(480)
            if not IsCurrentRun() then break end
            if not (Window and Window.Minimized) then
            H.ScanAllFriendPairs()
                end
        end
    end)
    local FAILED_CACHE_TTL = 20
    function H.FormatFriendLabel(record)
        if not record then return "?" end
        local display = record.name or tostring(record.id)
        local username = record.username
        if username and username ~= "" and username ~= display then
            return display .. " (@" .. username .. ")"
        end
        return display
    end
    function H.AttemptFriendsFetch(userId, highPriority, attemptNumber)
        H.EnqueueFriendsRequest(function()
            local body, httpErr = SafeHttpGet("https://friends.roblox.com/v1/users/" .. tostring(userId) .. "/friends")
            local records = nil
            local errText = nil
            local wasRateLimited = false
            if body then
                local okDecode, data = pcall(function() return HttpService:JSONDecode(body) end)
                if okDecode and type(data) == "table" and type(data.data) == "table" then
                    records = {}
                    for _, f in ipairs(data.data) do
                        if type(f) == "table" and f.id then
                            table.insert(records, {
                                id = f.id,
                                name = f.displayName or f.name or tostring(f.id),
                                username = f.name or tostring(f.id),
                            })
                        end
                    end
                elseif okDecode and type(data) == "table" and type(data.errors) == "table" then
                    local msg = (data.errors[1] and data.errors[1].message) or "Rate limited or blocked by Roblox API."
                    errText = "Roblox API error: " .. tostring(msg)
                    if tostring(msg):lower():find("too many requests") or tostring(msg):find("429") then
                        friendsBackoffUntil = os.clock() + FRIENDS_BACKOFF_ON_429
                        wasRateLimited = true
                    end
                else
                    errText = "Failed to read friend data (unrecognized format)."
                end
            else
                errText = "Failed to fetch friend data: " .. tostring(httpErr or "unknown")
                if httpErr and tostring(httpErr):find("429") then
                    friendsBackoffUntil = os.clock() + FRIENDS_BACKOFF_ON_429
                    wasRateLimited = true
                end
            end
            local e = H.GetCacheEntry(userId)
            if not records and not wasRateLimited and (attemptNumber or 1) < 2 then
                task.delay(2, function()
                    H.AttemptFriendsFetch(userId, highPriority, (attemptNumber or 1) + 1)
                end)
                return
            end
            e.friends = records
            e.friendsError = errText
            e.friendsAt = os.clock()
            e.friendsPending = false
            local waiters = e.friendsWaiters or {}
            e.friendsWaiters = {}
            for _, cb in ipairs(waiters) do pcall(cb, records, errText) end
        end, highPriority)
    end
    local LOCAL_PLAYER_FRIENDS_TTL = 1800
    function H.GetOrFetchFriends(userId, callback, highPriority)
        local entry = H.GetCacheEntry(userId)
        if entry.friendsAt then
            local age = os.clock() - entry.friendsAt
            local ttl
            if entry.friends then
                ttl = (LocalPlayer and userId == LocalPlayer.UserId) and LOCAL_PLAYER_FRIENDS_TTL or CACHE_TTL
            else
                ttl = FAILED_CACHE_TTL
            end
            if age < ttl then
                if callback then pcall(callback, entry.friends, entry.friendsError) end
                return
            end
        end
        if entry.friendsPending then
            if callback then table.insert(entry.friendsWaiters or {}, callback) end
            return
        end
        entry.friendsPending = true
        entry.friendsWaiters = entry.friendsWaiters or {}
        if callback then table.insert(entry.friendsWaiters, callback) end
        H.AttemptFriendsFetch(userId, highPriority, 1)
    end
    local GROUPS_PREFETCH_TTL = 240
    local lastGroupsPrefetchTick = {}
    function H.BackgroundPrefetchGroups(userId)
        if not userId then return end
        if lastGroupsPrefetchTick[userId] and (tick() - lastGroupsPrefetchTick[userId]) < GROUPS_PREFETCH_TTL then
            return
        end
        lastGroupsPrefetchTick[userId] = tick()
        GroupsQueue.Enqueue(function()
            local body = SafeHttpGet("https://groups.roblox.com/v1/users/" .. tostring(userId) .. "/groups/roles")
            if not body then return end
            local okDecode, data = pcall(function() return HttpService:JSONDecode(body) end)
            if not (okDecode and type(data) == "table" and type(data.data) == "table") then return end
            local okGameGroup, gameCreatorType, gameCreatorId = pcall(function()
                return game.CreatorType, game.CreatorId
            end)
            local isGameGroupOwned = okGameGroup and gameCreatorType == Enum.CreatorType.Group
            local groupCount = #data.data
            local groupNamesText
            local gameGroupRankText = nil
            if groupCount == 0 then
                groupNamesText = "Not following any groups"
            else
                local names = {}
                for _, g in ipairs(data.data) do
                    if type(g) == "table" and type(g.group) == "table" and g.group.name then
                        table.insert(names, g.group.name)
                        if isGameGroupOwned and g.group.id == gameCreatorId and type(g.role) == "table" then
                            gameGroupRankText = (g.role.name or "?") .. " (Rank " .. tostring(g.role.rank or "?") .. ")"
                        end
                    end
                end
                groupNamesText = (#names > 0) and table.concat(names, ", ") or "-"
            end
            local finalGameGroupRank = (not isGameGroupOwned) and "This game isn't owned by a group"
                or (gameGroupRankText or "Not a member of this game's owner group")
            if PersistExtendedField then
                PersistExtendedField(userId, "groups", groupCount)
                PersistExtendedField(userId, "allGroups", groupNamesText)
                PersistExtendedField(userId, "gameGroupRank", finalGameGroupRank)
            end
        end, false)
    end
    local AVATAR_PREFETCH_GAP = 5.0
    local avatarPrefetchQueue = {}
    local avatarPrefetchRunning = false
    local avatarPrefetchPending = {}
    function H.EnqueueAvatarPrefetch(userId)
        if not userId then return end
        if avatarPrefetchPending[userId] then return end
        local c = H.EnsureCache(userId)
        if c.online or c.clonedChar then return end
        avatarPrefetchPending[userId] = true
        table.insert(avatarPrefetchQueue, userId)
        if avatarPrefetchRunning then return end
        avatarPrefetchRunning = true
        task.spawn(function()
            while #avatarPrefetchQueue > 0 do
                local uid = table.remove(avatarPrefetchQueue, 1)
                avatarPrefetchPending[uid] = nil
                local cc = H.EnsureCache(uid)
                if not cc.online and not cc.clonedChar then
                    local okModel, model = pcall(function()
                        return Players:CreateHumanoidModelFromUserId(uid)
                    end)
                    if okModel and model and not cc.clonedChar and not cc.online then
                        SanitizeClonedCharacter(model)
                        cc.clonedChar = model
                    elseif okModel and model then
                        pcall(function() model:Destroy() end)
                    end
                end
                task.wait(AVATAR_PREFETCH_GAP)
            end
            avatarPrefetchRunning = false
        end)
    end
    function H.PrefetchHeadshots(userIds)
        if not ContentProvider or #userIds == 0 then return end
        task.spawn(function()
            local urls = {}
            for _, uid in ipairs(userIds) do
                table.insert(urls, "rbxthumb://type=AvatarHeadShot&id=" .. tostring(uid) .. "&w=150&h=150")
            end
        end)
    end
    function H.PrefetchAllTargetAvatars()
        for _, uid in ipairs(TargetPlayers) do
            H.EnqueueAvatarPrefetch(uid)
        end
        H.PrefetchHeadshots(TargetPlayers)
    end
    local BG_EXTRA_PREFETCH_TTL = 240
    local lastBgExtraPrefetchTick = {}
    function H.BackgroundPrefetchExtras(userId)
        if not userId then return end
        if lastBgExtraPrefetchTick[userId] and (tick() - lastBgExtraPrefetchTick[userId]) < BG_EXTRA_PREFETCH_TTL then
            return
        end
        lastBgExtraPrefetchTick[userId] = tick()
        UsersQueue.Enqueue(function()
            local body = SafeHttpGet("https://users.roblox.com/v1/users/" .. tostring(userId))
            if body then
                local okDecode, data = pcall(function() return HttpService:JSONDecode(body) end)
                if okDecode and type(data) == "table" and type(data.description) == "string" then
                    local bioText = (data.description ~= "") and data.description or "(Kosong, tidak ada bio)"
                    if PersistExtendedField then PersistExtendedField(userId, "bio", bioText) end
                end
            end
        end, false)
        local function bgFetchCount(url, field)
            FriendsCountQueue.Enqueue(function()
                local body = SafeHttpGet(url)
                if body then
                    local okDecode, data = pcall(function() return HttpService:JSONDecode(body) end)
                    if okDecode and type(data) == "table" and data.count and PersistExtendedField then
                        PersistExtendedField(userId, field, data.count)
                    end
                end
            end, false)
        end
        bgFetchCount("https://friends.roblox.com/v1/users/" .. tostring(userId) .. "/friends/count", "friendsCount")
        bgFetchCount("https://friends.roblox.com/v1/users/" .. tostring(userId) .. "/followers/count", "followers")
        bgFetchCount("https://friends.roblox.com/v1/users/" .. tostring(userId) .. "/followings/count", "following")
    end
    function H.BackgroundPrefetchPlayer(plr)
        if not plr or plr == LocalPlayer then return end
        local ok, userId = pcall(function() return plr.UserId end)
        if not ok or not userId then return end
        H.GetOrFetchFriends(userId, nil)
        H.BackgroundPrefetchGroups(userId)
        H.BackgroundPrefetchExtras(userId)
    end
    function H.BackgroundScanAllPlayers()
        for _, plr in ipairs(Players:GetPlayers()) do
            H.BackgroundPrefetchPlayer(plr)
        end
    end
