        local _exSlide  = 0
        local _exTarget = 0
        local _exConn   = nil
        local function exReadRoot()
            local r = Window and Window.Root
            if not r or not r.Parent then return nil end
            local rp = r.AbsolutePosition
            local rs = r.AbsoluteSize
            return {
                right  = rp.X + rs.X,
                midY   = rp.Y + rs.Y / 2,
                height = rs.Y,
            }
        end
        local function exApply()
            local geo = exReadRoot()
            if not geo then return end
            local hiddenX = geo.right - EXAMPLE_WINDOW_WIDTH
            local shownX  = geo.right + EXAMPLE_WINDOW_GAP
            local curX    = hiddenX + (shownX - hiddenX) * _exSlide
            local curH    = geo.height
            local curY    = geo.midY
            exampleWindow.Size     = UDim2.new(0, EXAMPLE_WINDOW_WIDTH, 0, curH)
            exampleWindow.Position = UDim2.new(0, curX, 0, curY)
            exampleWindow.BackgroundTransparency = 0.25
            local wantVisible = (_exSlide > 0.005) or (_exTarget > 0)
            if wantVisible and not exampleWindow.Visible then
                exampleWindow.Visible = true
            end
            if exampleGlowOuter then
                exampleGlowOuter.Position               = UDim2.new(0, curX + EXAMPLE_WINDOW_WIDTH/2, 0, geo.midY)
                exampleGlowOuter.Size                   = UDim2.new(0, EXAMPLE_WINDOW_WIDTH + 24, 0, curH + 24)
                exampleGlowOuter.BackgroundTransparency = 1.0 - (0.07 * _exSlide)
                if wantVisible and not exampleGlowOuter.Visible then exampleGlowOuter.Visible = true end
            end
            if exampleGlowInner then
                exampleGlowInner.Position               = UDim2.new(0, curX + EXAMPLE_WINDOW_WIDTH/2, 0, geo.midY)
                exampleGlowInner.Size                   = UDim2.new(0, EXAMPLE_WINDOW_WIDTH + 14, 0, curH + 14)
                exampleGlowInner.BackgroundTransparency = 1.0 - (0.14 * _exSlide)
                if wantVisible and not exampleGlowInner.Visible then exampleGlowInner.Visible = true end
            end
            if _exSlide <= 0.005 and _exTarget <= 0 then
                pcall(function() exampleWindow.Visible = false end)
                if exampleGlowOuter then pcall(function() exampleGlowOuter.Visible = false end) end
                if exampleGlowInner then pcall(function() exampleGlowInner.Visible = false end) end
            end
        end
        local function exSetTarget(v)
            _exTarget = v
            if v > 0 then
                exampleWindow.Visible = true
                if exampleGlowOuter then exampleGlowOuter.Visible = true end
                if exampleGlowInner then exampleGlowInner.Visible = true end
            end
        end
        local RunSvcMain = RunService
        if RunSvcMain then
            if _exConn then pcall(function() _exConn:Disconnect() end) end
            _exConn = DirectConnect(GetSignal(RunSvcMain, "RenderStepped"), function(dt)
                if Window and Window.Minimized then
                    if _exSlide > 0 or _exTarget > 0 then
                        _exTarget = 0
                        _exSlide  = 0
                        pcall(function() exampleWindow.Visible = false end)
                        if exampleGlowOuter then pcall(function() exampleGlowOuter.Visible = false end) end
                        if exampleGlowInner then pcall(function() exampleGlowInner.Visible = false end) end
                    end
                    return
                end
                _exTarget = (Window.CurrentTab == mainTab) and 1 or 0
                local k = 1 - math.exp(-dt * 30)
                local diff = _exTarget - _exSlide
                if math.abs(diff) < 0.0005 then
                    _exSlide = _exTarget
                else
                    _exSlide = _exSlide + diff * k
                end
                exApply()
            end)
        end
        if Window and Window.Tabs then
            for _, tObj in ipairs(Window.Tabs) do
                local tBtn = tObj.Button
                if tBtn then
                    SafeConnect(GetSignal(tBtn, "MouseButton1Click"), function()
                        if Window and Window.Minimized then return end
                        exSetTarget((tObj == mainTab) and 1 or 0)
                    end)
                end
            end
        end
        if Window and Window.CurrentTab == mainTab and not Window.Minimized then
            _exSlide  = 1
            _exTarget = 1
        else
            _exSlide  = 0
            _exTarget = 0
            exampleWindow.Visible = false
            if exampleGlowOuter then exampleGlowOuter.Visible = false end
            if exampleGlowInner then exampleGlowInner.Visible = false end
        end
        exApply()
    else
        exampleWindow = New("Frame", { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = _AutomaticSizeY or Enum.AutomaticSize.Y, BackgroundTransparency = 1, Parent = wrapper })
        exampleScroll = exampleWindow
    end
