    local RunSvcCheat = RunService
    local UISCheat           = UserInputService
    local cheatBaseRot       = CFrame.Angles(0, math.rad(180), 0)
    local isSpectating       = false
    local safeFollowActive   = false
    local spectateConn       = nil
    local function GetCurrentTargetPlayer()
        if #TargetPlayers == 0 then return nil end
        local uid = TargetPlayers[CurrentTargetIndex]
        return uid and Players:GetPlayerByUserId(uid)
    end
    local function ApplySpectateCamera()
        if spectateConn then spectateConn:Disconnect() spectateConn = nil end
        if not isSpectating then return end
        local cam = workspace and workspace.CurrentCamera
        if not cam then return end
        pcall(function() cam.CameraType = Enum.CameraType.Follow end)
        if spectateConn then pcall(function() spectateConn:Disconnect() end) end
        spectateConn = TrackConnection(RunSvcCheat.RenderStepped:Connect(function()
            if not isSpectating then return end
            local camNow = workspace and workspace.CurrentCamera
            if not camNow then return end
            local t = GetCurrentTargetPlayer()
            if t and t.Character and t.Character:FindFirstChild("Humanoid") then
                local targetHum = t.Character.Humanoid
                if camNow.CameraSubject ~= targetHum then
                    pcall(function()
                        camNow.CameraType   = Enum.CameraType.Follow
                        camNow.CameraSubject = targetHum
                    end)
                end
                if cheatStatus and cheatStatus.Parent then
                    pcall(function()
                        cheatStatus.Text = "Spectating: " .. (t.DisplayName or t.Name)
                    end)
                end
            else
                if cheatStatus and cheatStatus.Parent then
                    pcall(function()
                        cheatStatus.Text = "Spectate: target has no character"
                    end)
                end
            end
        end))
    end
    local ugOffsetVal        = 25
    local isUnderground      = false
    local isNoisyUnderground = false
    local isInvisible        = false
    local undergroundOriginalCFrame = nil
    local undergroundConn           = nil
    local invisibleParts            = {}
    local invisibleConn             = nil
    local safeFollowConn            = nil
    local function CheatTeleport(targetCFrame)
        local char = LocalPlayer and LocalPlayer.Character
        if not char or not char.PrimaryPart then return end
        local root = char.PrimaryPart
        local hum  = char:FindFirstChildOfClass("Humanoid")
        for _ = 1, 2 do
            root.AssemblyLinearVelocity  = Vector3.new(0,0,0)
            root.AssemblyAngularVelocity = Vector3.new(0,0,0)
        end
        if hum then hum:ChangeState(Enum.HumanoidStateType.Physics) end
        char:PivotTo(targetCFrame)
        if RunSvcCheat then RunSvcCheat.Heartbeat:Wait() end
        for _ = 1, 2 do
            root.AssemblyLinearVelocity  = Vector3.new(0,0,0)
            root.AssemblyAngularVelocity = Vector3.new(0,0,0)
        end
        if hum then hum:ChangeState(Enum.HumanoidStateType.GettingUp) end
    end
    local cheatStatus = New("TextLabel", {
        BackgroundColor3 = Palette.Glass,
        BackgroundTransparency = 0.2,
        Size = UDim2.new(1, 0, 0, 28),
        Font = Enum.Font.GothamMedium,
        Text = "Target Actions " .. _CHR.EM_DASH .. " select a player first.",
        TextColor3 = Palette.SubText,
        TextSize = 9,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextWrapped = true,
        Parent = scrollArea,
    })
    Round(cheatStatus, 8)
    Stroke(cheatStatus, accent, 1, 0.7)
    Pad(cheatStatus, 10, 10, 0, 0)
    H.CreateMainToggle({
        Title = "Spectate",
        Subtitle = "Lock camera to selected target",
        Default = false,
        Callback = function(s)
            isSpectating = s
            _mainSpectateActive = s
            if s and _physSpectateToggleRef then
                _physSpectateToggleRef.Set(false, false)
            end
            local cam = workspace and workspace.CurrentCamera
            if not cam then return end
            if isSpectating then
                ApplySpectateCamera()
            else
                if spectateConn then spectateConn:Disconnect() spectateConn = nil end
                pcall(function()
                    cam.CameraType = Enum.CameraType.Custom
                    if LocalPlayer and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("Humanoid") then
                        cam.CameraSubject = LocalPlayer.Character.Humanoid
                    end
                end)
                cheatStatus.Text = "Spectate OFF"
            end
        end,
    })
    H.CreateMainButton({
        Title = "Teleport",
        Subtitle = "Instant TP behind the selected target",
        Callback = function()
            local t = GetCurrentTargetPlayer()
            local myChar = LocalPlayer and LocalPlayer.Character
            if not t or not t.Character or not myChar or not myChar.PrimaryPart then
                cheatStatus.Text = "Teleport FAILED " .. _CHR.EM_DASH .. " no valid target"
                return
            end
            local tr = t.Character.PrimaryPart
            if not tr then return end
            local lookVec = tr.CFrame.LookVector
            local offset  = math.random(0, 1) == 0 and 2 or -2
            local dest    = Vector3.new(
                tr.Position.X + lookVec.X * offset,
                tr.Position.Y + 1.5,
                tr.Position.Z + lookVec.Z * offset
            )
            CheatTeleport(CFrame.new(dest, tr.Position))
            cheatStatus.Text = "Teleported to: " .. (t.DisplayName or t.Name)
        end,
    })
    H.CreateMainToggle({
        Title = "Safe Follow",
        Subtitle = "Walk toward target, stop at ~8 studs",
        Default = false,
        Callback = function(s)
            safeFollowActive = s
            if safeFollowConn then safeFollowConn:Disconnect() safeFollowConn = nil end
            if s then
                safeFollowConn = RunSvcCheat.Heartbeat:Connect(function()
                    if not safeFollowActive then return end
                    local t = GetCurrentTargetPlayer()
                    if t and t.Character and t.Character.PrimaryPart then
                        local char = LocalPlayer.Character
                        local hum  = char and char:FindFirstChildOfClass("Humanoid")
                        local root = char and char:FindFirstChild("HumanoidRootPart")
                        if hum and root then
                            local dist = (root.Position - t.Character.PrimaryPart.Position).Magnitude
                            if dist > 8 then hum:MoveTo(t.Character.PrimaryPart.Position)
                            else hum:MoveTo(root.Position) end
                        end
                    end
                end)
                cheatStatus.Text = "Safe Follow ON"
            else
                local char = LocalPlayer and LocalPlayer.Character
                local hum  = char and char:FindFirstChildOfClass("Humanoid")
                local root = char and char:FindFirstChild("HumanoidRootPart")
                if hum and root then hum:MoveTo(root.Position) end
                cheatStatus.Text = "Safe Follow OFF"
            end
        end,
    })
    H.CreateMainStepper({
        Title = "UG Offset",
        Subtitle = "Studs below target for Underground",
        Min = 5, Max = 100, Step = 5, Default = 25,
        Callback = function(v)
            ugOffsetVal = v
            cheatStatus.Text = "UG Offset: " .. tostring(v) .. " studs"
        end,
    })
    H.CreateMainToggle({
        Title = "Underground",
        Subtitle = "Phase below the map under the target",
        Default = false,
        Callback = function(s)
            isUnderground = s
            local char = LocalPlayer and LocalPlayer.Character
            local root = char and char:FindFirstChild("HumanoidRootPart")
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            if isUnderground then
                if root and hum then
                    undergroundOriginalCFrame = root.CFrame
                    root.Anchored = false
                    for _, track in pairs(hum:GetPlayingAnimationTracks()) do track:AdjustSpeed(0) end
                    local t = GetCurrentTargetPlayer()
                    if t and t.Character and t.Character:FindFirstChild("HumanoidRootPart") then
                        local tr = t.Character.HumanoidRootPart
                        local underY = math.max(tr.Position.Y - ugOffsetVal, (workspace and workspace.FallenPartsDestroyHeight or -500) + 25)
                        local tp = Vector3.new(tr.Position.X, underY, tr.Position.Z)
                        local fcf = CFrame.new(tp) * cheatBaseRot
                        task.spawn(function()
                            CheatTeleport(fcf)
                            undergroundConn = TrackConnection(RunSvcCheat.Heartbeat:Connect(function()
                                pcall(function()
                                    local t2 = GetCurrentTargetPlayer()
                                    if t2 and t2.Character and t2.Character:FindFirstChild("HumanoidRootPart") then
                                        local tr2 = t2.Character.HumanoidRootPart
                                        local uy2 = math.max(tr2.Position.Y - ugOffsetVal, (workspace and workspace.FallenPartsDestroyHeight or -500) + 25)
                                        local up = Vector3.new(tr2.Position.X, uy2, tr2.Position.Z)
                                        local myC = LocalPlayer.Character
                                        local myR = myC and myC:FindFirstChild("HumanoidRootPart")
                                        local myH = myC and myC:FindFirstChildOfClass("Humanoid")
                                        if myR then
                                            myR.CFrame = CFrame.new(up) * cheatBaseRot
                                            if isNoisyUnderground then
                                                local stateChoice = math.random(1, 2)
                                                if stateChoice == 1 then
                                                    if myH then myH:ChangeState(Enum.HumanoidStateType.Swimming) end
                                                else
                                                    if myH then myH:ChangeState(Enum.HumanoidStateType.Freefall) end
                                                end
                                                if math.random() < 0.05 then
                                                    myR.AssemblyLinearVelocity = Vector3.new(
                                                        math.random(-10000, 10000),
                                                        math.random(-1000,  1000),
                                                        math.random(-10000, 10000)
                                                    )
                                                end
                                                for _, snd in pairs(myC:GetDescendants()) do
                                                    if snd:IsA("Sound") then
                                                        local n = snd.Name
                                                        if n == "Splash" or n == "Swimming" or n == "Wading"
                                                        or n == "Running" or n == "Climbing" or n == "FreeFalling"
                                                        or n == "GettingUp" or n == "Jumping" or n == "Landing"
                                                        or n == "Died" then
                                                            pcall(function() snd.Volume = 0 end)
                                                            if snd.IsPlaying then pcall(function() snd:Stop() end) end
                                                        end
                                                    end
                                                end
                                            else
                                                myR.AssemblyLinearVelocity  = Vector3.new(0, 0, 0)
                                                myR.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                                                if myH then myH:ChangeState(Enum.HumanoidStateType.Freefall) end
                                            end
                                            for _, v in pairs(myC:GetDescendants()) do
                                                if v:IsA("BasePart") and v.CanCollide then v.CanCollide = false end
                                            end
                                        end
                                    end
                                end)
                            end))
                        end)
                    end
                end
                cheatStatus.Text = "Underground ON"
            else
                if undergroundConn then undergroundConn:Disconnect() undergroundConn = nil end
                if root and undergroundOriginalCFrame then
                    root.Anchored = false
                    task.spawn(function() CheatTeleport(undergroundOriginalCFrame) end)
                    if hum then
                        hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                        for _, track in pairs(hum:GetPlayingAnimationTracks()) do track:AdjustSpeed(1) end
                    end
                end
                cheatStatus.Text = "Underground OFF"
            end
        end,
    })
