    local function buildEmoteButtons(scrollFrame, emotes)
        for i, emote in ipairs(emotes) do
            local col = (i - 1) % ECOLS
            local row = math.floor((i - 1) / ECOLS)
            local btn = New("TextButton", {
                Name                   = emote.name:gsub(" ", ""),
                BackgroundColor3       = Palette.Element,
                BackgroundTransparency = 0.1,
                BorderSizePixel        = 0,
                Position               = UDim2.new(0, ESTART_X + col * (EBTN_W + EPAD),
                                                   0, ESTART_Y + row * (EBTN_H + EPAD)),
                Size                   = UDim2.new(0, EBTN_W, 0, EBTN_H),
                Font                   = Enum.Font.GothamSemibold,
                Text                   = emote.name,
                TextColor3             = Palette.SubText,
                TextSize               = 12,
                TextWrapped            = true,
                AutoButtonColor        = false,
                Parent                 = scrollFrame,
            })
            Round(btn, 8)
            local btnStroke = Stroke(btn, Palette.StrokeSoft, 1, 0.7)
            AddButtonHover(btn, btnStroke, 0.08)
            local currentTool = nil
            local isEquipped  = false
            local function getHumanoid()
                local ch = LocalPlayer and (LocalPlayer.Character or nil)
                return ch and ch:FindFirstChildOfClass("Humanoid")
            end
            local function makeTrack(id)
                local hum = getHumanoid()
                if not hum then return nil end
                local ok, track = pcall(function()
                    local a = Instance.new("Animation")
                    a.AnimationId = "rbxassetid://" .. tostring(id)
                    return hum:LoadAnimation(a)
                end)
                return ok and track or nil
            end
            local track = makeTrack(emote.id)
            local function resetBtn()
                isEquipped  = false
                currentTool = nil
                if track and track.IsPlaying then pcall(function() track:Stop() end) end
                pcall(function()
                    Tween(btn, 0.12, nil, nil, {
                        BackgroundColor3       = Palette.Element,
                        BackgroundTransparency = 0.1,
                        TextColor3             = Palette.SubText,
                    })
                    Tween(btnStroke, 0.12, nil, nil, { Color = Palette.StrokeSoft, Transparency = 0.7 })
                end)
            end
            SafeConnect(GetSignal(btn, "MouseButton1Click"), function()
                if currentTool then
                    pcall(function() currentTool:Destroy() end)
                    resetBtn()
                else
                    track = makeTrack(emote.id)
                    if not track then return end
                    local tool = Instance.new("Tool")
                    tool.Name           = "[JeyEmote] " .. emote.name
                    tool.RequiresHandle = false
                    tool.ToolTip        = emote.name
                    tool.GripPos        = Vector3.new(0, 0, 0)
                    tool.Parent         = LocalPlayer.Backpack
                    currentTool = tool
                    Tween(btn, 0.12, nil, nil, {
                        BackgroundColor3       = Palette.ElementHover,
                        BackgroundTransparency = 0,
                        TextColor3             = Palette.Text,
                    })
                    Tween(btnStroke, 0.12, nil, nil, { Color = accent, Transparency = 0.3 })
                    SafeConnect(GetSignal(tool, "Equipped"), function()
                        if currentTool ~= tool then return end
                        isEquipped = true
                        Tween(btn, 0.12, nil, nil, {
                            BackgroundColor3       = accent,
                            BackgroundTransparency = 0,
                            TextColor3             = Palette.Background,
                        })
                        Tween(btnStroke, 0.12, nil, nil, { Color = Palette.Accent, Transparency = 0.1 })
                        if emote.loop then
                            task.spawn(function()
                                while isEquipped and currentTool == tool do
                                    if track and not track.IsPlaying then
                                        pcall(function() track:Play(0.1, emote.weight, emote.speed) end)
                                    end
                                    task.wait(0.05)
                                end
                            end)
                        else
                            pcall(function() track:Play(0.1, emote.weight, emote.speed) end)
                        end
                    end)
                    SafeConnect(GetSignal(tool, "Unequipped"), function()
                        if currentTool ~= tool then return end
                        isEquipped = false
                        pcall(function() if track then track:Stop() end end)
                        Tween(btn, 0.12, nil, nil, {
                            BackgroundColor3       = Palette.ElementHover,
                            BackgroundTransparency = 0,
                            TextColor3             = Palette.Text,
                        })
                        Tween(btnStroke, 0.12, nil, nil, { Color = accent, Transparency = 0.3 })
                    end)
                    SafeConnect(GetSignal(tool, "AncestryChanged"), function(_, newParent)
                        if newParent == nil and currentTool == tool then
                            resetBtn()
                        end
                    end)
                end
            end)
        end
        local rows   = math.ceil(#emotes / ECOLS)
        local totalH = ESTART_Y + rows * (EBTN_H + EPAD) + EPAD
        scrollFrame.CanvasSize = UDim2.new(0, 0, 0, totalH)
        local clampedH = math.min(totalH + 4, 240)
        pcall(function() scrollFrame.Size = UDim2.new(1, 0, 0, clampedH) end)
    end
