local _linkedAntiSitActive      = false
local _usefullAntiFlingActive   = false
local _usefullAntiRagdollActive = false
local function BuildUsefullTab()
    local tab = CreatedTabs and CreatedTabs["Usefull"]
    if not tab or not tab.CreateSection then return end
    local RunService = RunService
    local TeleportSvc = SafeService("TeleportService")
    local VirtualUserSvc = SafeService("VirtualUser")
    local function getChar() return LocalPlayer and LocalPlayer.Character end
    local function getHum()
        local c = getChar()
        return c and c:FindFirstChildOfClass("Humanoid")
    end
    local function getRoot()
        local c = getChar()
        return c and c:FindFirstChild("HumanoidRootPart")
    end
    local function safeInstantTeleport(targetCFrame)
        local root = getRoot()
        if not root then return end
        local hum = getHum()
        for _ = 1, 2 do
            root.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
            root.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
        end
        if hum then pcall(function() hum:ChangeState(Enum.HumanoidStateType.Physics) end) end
        root.CFrame = targetCFrame
        if RunService then pcall(function() RunService.Heartbeat:Wait() end) end
        for _ = 1, 2 do
            root.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
            root.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
        end
        if hum then pcall(function() hum:ChangeState(Enum.HumanoidStateType.GettingUp) end) end
    end
    local movementSec = tab:CreateSection("Movement Controls", "Speed, fly, sprint, bhop")
    local wsValue, jpValue, flySpeedVal = 16, 50, 50
    local flyEnabled = false
    local autoSprintEnabled, sprintSpeedVal = false, 25
    local autoJumpEnabled = false
    local airSwimEnabled = false
    local flyBodyGyro, flyBodyVel = nil, nil
    local crouchFeatureEnabled = false
    local crouchEnabled       = false
    local crouchHbConn        = nil
    local crouchIdleAnim      = nil
    local crouchWalkAnim      = nil
    local crouchDefaultSpeed  = 16
    local crouchIdleId        = nil
    local crouchWalkId        = nil
    local CROUCH_WALK_SPEED   = 5
    local CROUCH_ANIM_SPEED   = 0.8
    local CROUCH_IDLE_ANIMID  = "rbxassetid://107078800928182"
    local CROUCH_WALK_ANIMID  = "rbxassetid://137525751454426"
    local CROUCH_BTN_IMG      = "rbxassetid://109660173469064"
    local CROUCH_BTN_ACTIVE   = "rbxassetid://139705395031155"
    local crouchMobileBtn     = nil
    local crouchJumpBtnRef    = nil
    movementSec:CreateSlider({
        Title = "Walk Speed",
        Subtitle = "Atur kecepatan jalan",
        Min = 1, Max = 300, Step = 1, Default = 16,
        Callback = function(v) wsValue = v end,
    })
    movementSec:CreateSlider({
        Title = "Jump Power",
        Subtitle = "Atur tinggi lompatan",
        Min = 0, Max = 300, Step = 1, Default = 50,
        Callback = function(v) jpValue = v end,
    })
    movementSec:CreateToggle({
        Title = "Fly",
        Subtitle = "Terbang bebas (WASD)",
        Default = false,
        Callback = function(state)
            flyEnabled = state
            if not state then
                if flyBodyGyro then pcall(function() flyBodyGyro:Destroy() end) flyBodyGyro = nil end
                if flyBodyVel  then pcall(function() flyBodyVel:Destroy()  end) flyBodyVel  = nil end
                local hum = getHum()
                if hum then pcall(function() hum.PlatformStand = false end) end
            end
        end,
    })
    movementSec:CreateSlider({
        Title = "Fly Speed",
        Subtitle = "Atur kecepatan terbang",
        Min = 0, Max = 300, Step = 1, Default = 50,
        Callback = function(v) flySpeedVal = v end,
    })
    movementSec:CreateToggle({
        Title = "Auto Sprint",
        Subtitle = "Auto lari saat bergerak",
        Default = false,
        Callback = function(state) autoSprintEnabled = state end,
    })
    movementSec:CreateSlider({
        Title = "Sprint Speed",
        Subtitle = "Atur kecepatan sprint",
        Min = 16, Max = 300, Step = 1, Default = 25,
        Callback = function(v) sprintSpeedVal = v end,
    })
    movementSec:CreateToggle({
        Title = "Auto Jump (Bhop)",
        Subtitle = "Auto lompat terus",
        Default = false,
        Callback = function(state) autoJumpEnabled = state end,
    })
    movementSec:CreateToggle({
        Title = "Air Swim",
        Subtitle = "State renang di udara",
        Default = false,
        Callback = function(state)
            airSwimEnabled = state
            if not state then
                local hum = getHum()
                if hum then pcall(function() hum:ChangeState(Enum.HumanoidStateType.GettingUp) end) end
            end
        end,
    })
    local function crouchCacheAnims()
        local char = getChar()
        if not char then return end
        local animate = char:FindFirstChild("Animate")
        if not animate then return end
        if not crouchIdleId then
            local idleNode = animate:FindFirstChild("idle")
            local anim = idleNode and idleNode:FindFirstChild("Animation1")
            if anim then crouchIdleId = anim.AnimationId end
        end
        if not crouchWalkId then
            local walkNode = animate:FindFirstChild("walk")
            local anim = walkNode and walkNode:FindFirstChild("WalkAnim")
            if anim then crouchWalkId = anim.AnimationId end
        end
    end
    local function deactivateCrouch()
        if not crouchEnabled then return end
        crouchEnabled = false
        if crouchHbConn then
            pcall(function() crouchHbConn:Disconnect() end)
            crouchHbConn = nil
        end
        if crouchIdleAnim then pcall(function() crouchIdleAnim:Stop() end) crouchIdleAnim = nil end
        if crouchWalkAnim then pcall(function() crouchWalkAnim:Stop() end) crouchWalkAnim = nil end
        if crouchMobileBtn  then pcall(function() crouchMobileBtn.Image = CROUCH_BTN_IMG end) end
        if crouchJumpBtnRef then pcall(function() crouchJumpBtnRef.Visible = true end) end
        pcall(function()
            local hum = getHum()
            if not hum then return end
            hum.WalkSpeed = 16
            hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true)
            local char = getChar()
            local animate = char and char:FindFirstChild("Animate")
            if animate then
                if crouchIdleId then
                    local idle = animate:FindFirstChild("idle")
                    local anim = idle and idle:FindFirstChild("Animation1")
                    if anim then anim.AnimationId = crouchIdleId end
                end
                if crouchWalkId then
                    local walk = animate:FindFirstChild("walk")
                    local anim = walk and walk:FindFirstChild("WalkAnim")
                    if anim then anim.AnimationId = crouchWalkId end
                end
            end
        end)
    end
    local function activateCrouch()
        if crouchEnabled then return end
        local hum = getHum()
        if not hum then return end
        crouchEnabled = true
        crouchCacheAnims()
        crouchDefaultSpeed = 16
        pcall(function()
            local idleAnim = Instance.new("Animation")
            idleAnim.AnimationId = CROUCH_IDLE_ANIMID
            local walkAnim = Instance.new("Animation")
            walkAnim.AnimationId = CROUCH_WALK_ANIMID
            crouchIdleAnim = hum:LoadAnimation(idleAnim)
            crouchWalkAnim = hum:LoadAnimation(walkAnim)
            crouchWalkAnim:AdjustSpeed(CROUCH_ANIM_SPEED)
            crouchWalkAnim:Play()
        end)
        pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, false) end)
        if crouchMobileBtn  then pcall(function() crouchMobileBtn.Image = CROUCH_BTN_ACTIVE end) end
        if crouchJumpBtnRef then pcall(function() crouchJumpBtnRef.Visible = false end) end
        crouchHbConn = SafeConnect(GetSignal(RunService, "Heartbeat"), function()
            if not crouchEnabled then
                if crouchHbConn then
                    pcall(function() crouchHbConn:Disconnect() end)
                    crouchHbConn = nil
                end
                return
            end
            pcall(function()
                local h = getHum()
                if not h or h.Health <= 0 then deactivateCrouch() return end
                local isMoving = h.MoveDirection.Magnitude > 0
                h.WalkSpeed = CROUCH_WALK_SPEED
                if isMoving then
                    if crouchWalkAnim and crouchWalkAnim.IsPlaying then crouchWalkAnim:Stop() end
                    if crouchIdleAnim and not crouchIdleAnim.IsPlaying then crouchIdleAnim:Play() end
                else
                    if crouchIdleAnim and crouchIdleAnim.IsPlaying then crouchIdleAnim:Stop() end
                    if crouchWalkAnim and not crouchWalkAnim.IsPlaying then crouchWalkAnim:Play() end
                end
                if h:GetState() == Enum.HumanoidStateType.Jumping then
                    h:ChangeState(Enum.HumanoidStateType.Running)
                end
            end)
        end)
    end
    SafeConnect(GetSignal(LocalPlayer, "CharacterAdded"), function(char)
        if crouchEnabled then deactivateCrouch() end
        crouchIdleId = nil
        crouchWalkId = nil
        char:WaitForChild("Humanoid", 10)
        crouchCacheAnims()
        if crouchMobileBtn then
            pcall(function() crouchMobileBtn.Image = CROUCH_BTN_IMG end)
        end
        if crouchJumpBtnRef then
            pcall(function() crouchJumpBtnRef.Visible = true end)
        end
    end)
    SafeConnect(GetSignal(UserInputService, "InputBegan"), function(input, processed)
        if processed then return end
        if not crouchFeatureEnabled then return end
        if input.KeyCode == Enum.KeyCode.LeftControl or input.KeyCode == Enum.KeyCode.C then
            if crouchEnabled then deactivateCrouch() else activateCrouch() end
        end
    end)
    movementSec:CreateToggle({
        Title = "Crouch",
        Subtitle = "Jongkok (LeftCtrl / C)",
        Default = false,
        Callback = function(state)
            crouchFeatureEnabled = state
            if not state then
                deactivateCrouch()
            end
            if crouchMobileBtn then
                pcall(function() crouchMobileBtn.Visible = state end)
            end
        end,
    })
    task.spawn(function()
        if not UserInputService.TouchEnabled then return end
        local playerGui = LocalPlayer:WaitForChild("PlayerGui", 10)
        if not playerGui then return end
        task.wait(1)
        local jumpBtn = nil
        for _, obj in ipairs(playerGui:GetDescendants()) do
            if obj:IsA("ImageButton") and (obj.Name == "JumpButton" or string.find(string.lower(obj.Name), "jump")) then
                jumpBtn = obj
                break
            end
        end
        crouchJumpBtnRef = jumpBtn
        local gui = Instance.new("ScreenGui")
        gui.Name = "JeyhubCrouchTouch"
        gui.ResetOnSpawn = false
        gui.Parent = playerGui
        local btn = Instance.new("ImageButton")
        btn.Name = "CrouchButton"
        btn.BackgroundTransparency = 1
        btn.Image = CROUCH_BTN_IMG
        btn.Visible = false
        btn.Parent = gui
        if jumpBtn then
            btn.Size = jumpBtn.Size
            btn.Position = UDim2.new(
                0, jumpBtn.AbsolutePosition.X - jumpBtn.AbsoluteSize.X - 10,
                0, jumpBtn.AbsolutePosition.Y
            )
        else
            btn.Size = UDim2.new(0, 60, 0, 60)
            btn.Position = UDim2.new(0, 30, 1, -150)
        end
        crouchMobileBtn = btn
        btn.MouseButton1Click:Connect(function()
            if crouchEnabled then deactivateCrouch() else activateCrouch() end
        end)
    end)
    local _wsTarget  = Vector3.zero
    local _wsCurr    = Vector3.zero
    local _wsAlpha   = 14
    local _jpStateConn = nil
    local function _hookJump(hum)
        if _jpStateConn then
            pcall(function() _jpStateConn:Disconnect() end)
            _jpStateConn = nil
        end
        if not hum then return end
        _jpStateConn = SafeConnect(GetSignal(hum, "StateChanged"), function(_, newState)
            if newState ~= Enum.HumanoidStateType.Jumping then return end
            if jpValue == 50 then return end
            local root = getRoot()
            if not root then return end
            task.defer(function()
                pcall(function()
                    local v = root.AssemblyLinearVelocity
                    root.AssemblyLinearVelocity = Vector3.new(v.X, jpValue, v.Z)
                end)
            end)
        end)
    end
    _hookJump(getHum())
    SafeConnect(GetSignal(LocalPlayer, "CharacterAdded"), function(char)
        task.wait(0.3)
        _hookJump(char and char:FindFirstChildOfClass("Humanoid"))
    end)
    local _bhopLast = 0
    DirectConnect(GetSignal(RunService, "Heartbeat"), function(dt)
        local anyActive = flyEnabled or airSwimEnabled or autoJumpEnabled
            or autoSprintEnabled or wsValue ~= 16
        if not anyActive then
            if _wsCurr.Magnitude > 0.1 then
                local alpha = 1 - math.exp(-_wsAlpha * dt)
                _wsCurr = _wsCurr:Lerp(Vector3.zero, alpha)
                local root = getRoot()
                if root then
                    pcall(function()
                        local v = root.AssemblyLinearVelocity
                        root.AssemblyLinearVelocity = Vector3.new(_wsCurr.X, v.Y, _wsCurr.Z)
                    end)
                end
            else
                _wsCurr  = Vector3.zero
                _wsTarget = Vector3.zero
            end
            return
        end
        pcall(function()
            local root = getRoot()
            local hum  = getHum()
            if flyEnabled and root then
                if not flyBodyGyro then
                    flyBodyGyro = Instance.new("BodyGyro", root)
                    flyBodyGyro.P = 9e4
                    flyBodyGyro.MaxTorque = Vector3.new(9e9, 9e9, 9e9)
                end
                if not flyBodyVel then
                    flyBodyVel = Instance.new("BodyVelocity", root)
                    flyBodyVel.MaxForce = Vector3.new(9e9, 9e9, 9e9)
                end
                local cam = workspace.CurrentCamera
                if cam then
                    flyBodyGyro.CFrame = cam.CFrame
                    local mv = Vector3.zero
                    if UserInputService:IsKeyDown(Enum.KeyCode.W) then mv = mv + cam.CFrame.LookVector  end
                    if UserInputService:IsKeyDown(Enum.KeyCode.S) then mv = mv - cam.CFrame.LookVector  end
                    if UserInputService:IsKeyDown(Enum.KeyCode.A) then mv = mv - cam.CFrame.RightVector end
                    if UserInputService:IsKeyDown(Enum.KeyCode.D) then mv = mv + cam.CFrame.RightVector end
                    if hum and mv.Magnitude == 0 and hum.MoveDirection.Magnitude > 0 then
                        local lm = cam.CFrame:VectorToObjectSpace(hum.MoveDirection)
                        mv = (cam.CFrame.LookVector * -lm.Z) + (cam.CFrame.RightVector * lm.X)
                    end
                    if hum then hum.PlatformStand = true end
                    flyBodyVel.Velocity = mv.Magnitude > 0 and (mv.Unit * flySpeedVal) or Vector3.zero
                end
            else
                if flyBodyGyro then pcall(function() flyBodyGyro:Destroy() end) flyBodyGyro = nil end
                if flyBodyVel  then pcall(function() flyBodyVel:Destroy()  end) flyBodyVel  = nil end
            end
            if not (hum and root) then return end
            if airSwimEnabled then
                pcall(function() hum:ChangeState(Enum.HumanoidStateType.Swimming) end)
            end
            if autoJumpEnabled then
                local now = tick()
                if now - _bhopLast >= 0.05 then
                    local st = hum:GetState()
                    if st == Enum.HumanoidStateType.Running
                        or st == Enum.HumanoidStateType.RunningNoPhysics
                        or st == Enum.HumanoidStateType.Landed then
                        pcall(function() hum:ChangeState(Enum.HumanoidStateType.Jumping) end)
                        _bhopLast = now
                    end
                end
            end
            hum.WalkSpeed = 16
            local activeSpeed = wsValue
            if autoSprintEnabled and hum.MoveDirection.Magnitude > 0.1 then
                activeSpeed = sprintSpeedVal
            end
            if activeSpeed ~= 16 and hum.MoveDirection.Magnitude > 0.1 then
                _wsTarget = Vector3.new(
                    hum.MoveDirection.X, 0, hum.MoveDirection.Z
                ).Unit * activeSpeed
            else
                _wsTarget = Vector3.zero
            end
            local alpha = 1 - math.exp(-_wsAlpha * dt)
            _wsCurr = _wsCurr:Lerp(_wsTarget, alpha)
            if _wsTarget.Magnitude > 0.1 or _wsCurr.Magnitude > 0.3 then
                local curY = root.AssemblyLinearVelocity.Y
                root.AssemblyLinearVelocity = Vector3.new(_wsCurr.X, curY, _wsCurr.Z)
            end
            local animator = hum:FindFirstChildOfClass("Animator")
            if animator then
                local targetAnimSpd = (activeSpeed == 16)
                    and 1.0
                    or math.clamp(math.sqrt(activeSpeed / 16), 0.6, 1.5)
                for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
                    pcall(function()
                        if math.abs(track.Speed - targetAnimSpd) > 0.05 then
                            track:AdjustSpeed(targetAnimSpd)
                        end
                    end)
                end
            end
            hum.UseJumpPower = true
            hum.JumpPower    = 50
        end)
    end)
    local protSec = tab:CreateSection("Survival & Defense", "Noclip, god mode, proteksi")
    local noclipEnabled = false
    local _noclipNames = { HumanoidRootPart=true, Torso=true, UpperTorso=true, LowerTorso=true, Head=true }
    local _noclipCache, _noclipCacheChar = {}, nil
    local function _rebuildNoclipCache(char)
        _noclipCache = {}
        _noclipCacheChar = char
        for _, v in ipairs(char:GetDescendants()) do
            if v:IsA("BasePart") and _noclipNames[v.Name] then
                _noclipCache[#_noclipCache + 1] = v
            end
        end
    end
    protSec:CreateToggle({
        Title = "Noclip Bypass",
        Subtitle = "Tembus tembok & lantai",
        Default = false,
        Callback = function(state) noclipEnabled = state
        _noclipCacheChar = nil end,
    })
    SafeConnect(GetSignal(RunService, "Stepped"), function()
        if not noclipEnabled then return end
        local char = getChar()
        if not char then return end
        if char ~= _noclipCacheChar then _rebuildNoclipCache(char) end
        for _, v in ipairs(_noclipCache) do
            if v.CanCollide then v.CanCollide = false end
        end
    end)
    local spiderEnabled = false
    protSec:CreateToggle({
        Title = "Spider Climb",
        Subtitle = "Naik tembok otomatis",
        Default = false,
        Callback = function(state) spiderEnabled = state end,
    })
    local spiderParams = RaycastParams.new()
    spiderParams.FilterType = Enum.RaycastFilterType.Exclude
    DirectConnect(GetSignal(RunService, "Heartbeat"), function()
        if not spiderEnabled then return end
        local char = getChar()
        local root = getRoot()
        local hum  = getHum()
        if not (char and root and hum and hum.MoveDirection.Magnitude > 0) then return end
        spiderParams.FilterDescendantsInstances = { char }
        local ray = workspace:Raycast(root.Position, root.CFrame.LookVector * 2.5, spiderParams)
        if ray then
            root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, 45, root.AssemblyLinearVelocity.Z)
        end
    end)
    local infJumpEnabled = false
    protSec:CreateToggle({
        Title = "Infinite Jump",
        Subtitle = "Lompat tanpa batas",
        Default = false,
        Callback = function(state) infJumpEnabled = state end,
    })
    SafeConnect(GetSignal(UserInputService, "JumpRequest"), function()
        if not infJumpEnabled then return end
        local hum = getHum()
        if hum and hum:GetState() ~= Enum.HumanoidStateType.Dead then
            hum:ChangeState(Enum.HumanoidStateType.Jumping)
        end
    end)
    local airWalkPart, airWalkConn, airWalkY = nil, nil, nil
    protSec:CreateToggle({
        Title = "Air Walk",
        Subtitle = "Jalan di udara",
        Default = false,
        Callback = function(state)
            if state then
                airWalkPart = Instance.new("Part")
                airWalkPart.Size = Vector3.new(15, 1, 15)
                airWalkPart.Transparency = 1
                airWalkPart.Anchored = true
                airWalkPart.Massless = true
                airWalkPart.CastShadow = false
                airWalkPart.Name = "BaseplateGround"
                airWalkPart.Parent = workspace
                airWalkY = nil
                airWalkConn = SafeConnect(GetSignal(RunService, "Stepped"), function()
                    local root = getRoot()
                    if not root then return end
                    if not airWalkY or UserInputService:IsKeyDown(Enum.KeyCode.Space) or root.AssemblyLinearVelocity.Y < -15 then
                        airWalkY = root.Position.Y - 3.5
                    end
                    airWalkPart.CFrame = CFrame.new(root.Position.X, airWalkY, root.Position.Z)
                    root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, 0, root.AssemblyLinearVelocity.Z)
                end)
            else
                if airWalkConn then pcall(function() airWalkConn:Disconnect() end) airWalkConn = nil end
                if airWalkPart then pcall(function() airWalkPart:Destroy() end) airWalkPart = nil end
            end
        end,
    })
    local walkOnWaterActive = false
    local waterPad, waterConn = nil, nil
    protSec:CreateToggle({
        Title = "Walk On Water",
        Subtitle = "Jalan di atas air",
        Default = false,
        Callback = function(state)
            walkOnWaterActive = state
            if state then
                if not waterPad then
                    waterPad = Instance.new("Part")
                    waterPad.Size = Vector3.new(6, 0.5, 6)
                    waterPad.Transparency = 1
                    waterPad.Anchored = true
                    waterPad.CanCollide = true
                    waterPad.Massless = true
                    waterPad.CastShadow = false
                    waterPad.Name = "TerrainWaterSurface"
                    waterPad.Parent = workspace
                end
                if not waterConn then
                    local waterParams = RaycastParams.new()
                    local char = getChar()
                    waterParams.FilterDescendantsInstances = { char, waterPad }
                    waterParams.FilterType = Enum.RaycastFilterType.Exclude
                    waterParams.IgnoreWater = false
                    local _waterDown = Vector3.new(0, -10, 0)
                    waterConn = DirectConnect(GetSignal(RunService, "Heartbeat"), function()
                        if not walkOnWaterActive then return end
                        local root = getRoot()
                        if not root then return end
                        local ray = workspace:Raycast(root.Position, _waterDown, waterParams)
                        if ray and ray.Material == Enum.Material.Water then
                            waterPad.CFrame = CFrame.new(root.Position.X, ray.Position.Y - 0.2, root.Position.Z)
                            waterPad.CanCollide = true
                        else
                            waterPad.CFrame = CFrame.new(0, -9999, 0)
                            waterPad.CanCollide = false
                        end
                    end)
                end
            else
                if waterConn then pcall(function() waterConn:Disconnect() end) waterConn = nil end
                if waterPad  then pcall(function() waterPad:Destroy() end)   waterPad  = nil end
            end
        end,
    })
