    local serverSec = tab:CreateSection("Server", "Hop & rejoin server")
    local function fetchPublicServers(sortOrder)
        local ok, list = pcall(function()
            local body = game:HttpGet("https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=" .. sortOrder .. "&limit=100")
            return HttpService:JSONDecode(body).data
        end)
        return ok and list or nil
    end
    serverSec:CreateButton({
        Title = "Server Hop",
        Subtitle = "Pindah server ada slot",
        ButtonText = "Hop",
        Callback = function()
            local servers = fetchPublicServers("Asc")
            if not servers or not TeleportSvc then return end
            for _, v in ipairs(servers) do
                if v.playing < v.maxPlayers and v.id ~= game.JobId then
                    pcall(function() TeleportSvc:TeleportToPlaceInstance(game.PlaceId, v.id, LocalPlayer) end)
                    break
                end
            end
        end,
    })
    serverSec:CreateButton({
        Title = "Low Population Server",
        Subtitle = "Server paling sepi",
        ButtonText = "Go",
        Callback = function()
            local servers = fetchPublicServers("Asc")
            if not servers or not TeleportSvc then return end
            local lowest = nil
            for _, v in ipairs(servers) do
                if v.playing > 0 and v.id ~= game.JobId then
                    if not lowest or v.playing < lowest.playing then lowest = v end
                end
            end
            if lowest then pcall(function() TeleportSvc:TeleportToPlaceInstance(game.PlaceId, lowest.id, LocalPlayer) end) end
        end,
    })
    serverSec:CreateButton({
        Title = "Max Population Server",
        Subtitle = "Server paling ramai",
        ButtonText = "Go",
        Callback = function()
            local servers = fetchPublicServers("Desc")
            if not servers or not TeleportSvc then return end
            for _, v in ipairs(servers) do
                if v.playing < v.maxPlayers and v.id ~= game.JobId then
                    pcall(function() TeleportSvc:TeleportToPlaceInstance(game.PlaceId, v.id, LocalPlayer) end)
                    break
                end
            end
        end,
    })
    serverSec:CreateButton({
        Title = "Random Server",
        Subtitle = "Server acak",
        ButtonText = "Go",
        Callback = function()
            local servers = fetchPublicServers("Asc")
            if not servers or #servers == 0 or not TeleportSvc then return end
            local r = servers[math.random(1, #servers)]
            if r and r.id ~= game.JobId then
                pcall(function() TeleportSvc:TeleportToPlaceInstance(game.PlaceId, r.id, LocalPlayer) end)
            end
        end,
    })
    serverSec:CreateButton({
        Title = "Rejoin",
        Subtitle = "Masuk ulang server ini",
        ButtonText = "Rejoin",
        Callback = function()
            if not TeleportSvc then return end
            pcall(function()
                local jobId = game.JobId
                if jobId and jobId ~= "" then
                    TeleportSvc:TeleportToPlaceInstance(game.PlaceId, jobId, LocalPlayer)
                else
                    TeleportSvc:Teleport(game.PlaceId, LocalPlayer)
                end
            end)
        end,
    })
    do
        local MktSvc     = SafeService("MarketplaceService")
        local GuiSvc     = SafeService("GuiService")
        local CoreGuiSvc = SafeService("CoreGui")
        local TweenSvc   = SafeService("TweenService")
        local FGP_LastPrompt       = { Id = nil, Type = nil, Nonce = 0 }
        local FGP_InstantOn        = false
        local FGP_AutoMassOn       = false
        local FGP_LastInstantNonce = -1
        local FGP_Status           = "Idle"
        local FGP_StatusLabel      = nil
        local function fgpFireFallback(event, ...)
            if type(firesignal) == "function" then
                pcall(firesignal, event, ...)
            end
        end
        local function fgpToggleMenu()
            pcall(function()
                if not CoreGuiSvc or not GuiSvc then return end
                local foundOverlay = false
                for _, child in ipairs(CoreGuiSvc:GetChildren()) do
                    if child:IsA("ScreenGui") and child.Name == "FoundationOverlay" and child.Enabled then
                        local saf      = child:FindFirstChild("SafeAreaFrame")
                        local portal   = saf and saf:FindFirstChild("OverlayPortal")
                        local backdrop = portal and portal:FindFirstChild("Backdrop")
                        local sheet    = portal and portal:FindFirstChild("SheetContainer")
                        if backdrop and sheet and TweenSvc then
                            foundOverlay = true
                            local info = TweenInfo.new(0.1, Enum.EasingStyle.Cubic, Enum.EasingDirection.In)
                            TweenSvc:Create(backdrop, info, { BackgroundTransparency = 1 }):Play()
                            local t = TweenSvc:Create(sheet, info, { Position = UDim2.new(0.5, 0, 0.5, 32) })
                            t:Play()
                            t.Completed:Connect(function()
                                pcall(function() GuiSvc:SetMenuIsOpen(true) end)
                                pcall(function() GuiSvc:SetMenuIsOpen(false) end)
                            end)
                            break
                        end
                    end
                end
                if not foundOverlay then
                    pcall(function() GuiSvc:SetMenuIsOpen(true)  end)
                    pcall(function() GuiSvc:SetMenuIsOpen(false) end)
                end
            end)
        end
        local function fgpFinish(id, pType)
            if not MktSvc or not id then return end
            local uid = LocalPlayer and LocalPlayer.UserId or 0
            if pType == "GamePass" then
                local ok = pcall(function() MktSvc:SignalPromptGamePassPurchaseFinished(uid, id, true) end)
                if not ok then fgpFireFallback(MktSvc.PromptGamePassPurchaseFinished, LocalPlayer, id, true) end
            elseif pType == "Product" then
                local ok = pcall(function() MktSvc:SignalPromptProductPurchaseFinished(uid, id, true) end)
                if not ok then fgpFireFallback(MktSvc.PromptProductPurchaseFinished, LocalPlayer, id, true) end
            elseif pType == "Asset" then
                local ok = pcall(function() MktSvc:SignalPromptPurchaseFinished(uid, id, true) end)
                if not ok then fgpFireFallback(MktSvc.PromptPurchaseFinished, LocalPlayer, id, true) end
            elseif pType == "Bundle" then
                local ok = pcall(function() MktSvc:SignalPromptBundlePurchaseFinished(uid, id, true) end)
                if not ok then fgpFireFallback(MktSvc.PromptBundlePurchaseFinished, LocalPlayer, id, true) end
            elseif pType == "Premium" then
                local ok = pcall(function() MktSvc:SignalPromptPremiumPurchaseFinished(true) end)
                if not ok then fgpFireFallback(MktSvc.PromptPremiumPurchaseFinished) end
            end
        end
        local function fgpSetStatus(text, color)
            FGP_Status = text or "Idle"
            if FGP_StatusLabel then
                pcall(function()
                    FGP_StatusLabel.Text       = "  " .. FGP_Status
                    FGP_StatusLabel.TextColor3 = color or Color3.fromRGB(170, 170, 170)
                end)
            end
        end
        local function fgpCapture(player, id, pType)
            if player ~= LocalPlayer then return end
            FGP_LastPrompt.Nonce = FGP_LastPrompt.Nonce + 1
            FGP_LastPrompt.Id    = id
            FGP_LastPrompt.Type  = pType
            fgpSetStatus("Prompt: " .. tostring(pType) .. " #" .. tostring(id), Color3.fromRGB(255, 210, 80))
            if FGP_InstantOn then
                local nonce = FGP_LastPrompt.Nonce
                task.spawn(function()
                    task.wait(0.05)
                    if FGP_LastPrompt.Nonce ~= nonce then return end
                    if FGP_LastInstantNonce == nonce then return end
                    FGP_LastInstantNonce = nonce
                    fgpFinish(id, pType)
                    fgpToggleMenu()
                    fgpSetStatus("Instant claimed: " .. tostring(pType) .. " #" .. tostring(id), Color3.fromRGB(80, 220, 110))
                end)
            end
        end
        if MktSvc then
            TrackConnection(SafeConnect(GetSignal(MktSvc, "PromptGamePassPurchaseRequested"),
                function(player, id) fgpCapture(player, id, "GamePass") end))
            TrackConnection(SafeConnect(GetSignal(MktSvc, "PromptProductPurchaseRequested"),
                function(player, id) fgpCapture(player, id, "Product") end))
            TrackConnection(SafeConnect(GetSignal(MktSvc, "PromptPurchaseRequested"),
                function(player, id) fgpCapture(player, id, "Asset") end))
            TrackConnection(SafeConnect(GetSignal(MktSvc, "PromptBundlePurchaseRequested"),
                function(player, id) fgpCapture(player, id, "Bundle") end))
            TrackConnection(SafeConnect(GetSignal(MktSvc, "PromptPremiumPurchaseRequested"),
                function(player) fgpCapture(player, 0, "Premium") end))
        end
        local function fgpRunMassPurchase()
            task.spawn(function()
                fgpSetStatus("Mass Purchase: fetching dev products" .. _CHR.ELLIPSIS, Color3.fromRGB(255, 160, 60))
                local uid = LocalPlayer and LocalPlayer.UserId or 0
                if MktSvc then
                    local okPage, page = pcall(function() return MktSvc:GetDeveloperProductsAsync() end)
                    if okPage and page then
                        while true do
                            local products = page:GetCurrentPage()
                            for _, info in ipairs(products) do
                                local id = info.ProductId
                                pcall(function() MktSvc:SignalPromptProductPurchaseFinished(uid, id, true) end)
                                task.wait(0.08)
                            end
                            if page.IsFinished then break end
                            pcall(function() page:AdvanceToNextPageAsync() end)
                        end
                    end
                end
                local HttpSvc    = SafeService("HttpService")
                local universeId = game.GameId
                if universeId == 0 then
                    pcall(function()
                        local res  = game:HttpGet("https://apis.roblox.com/universes/v1/places/" .. tostring(game.PlaceId) .. "/universe")
                        local data = HttpSvc:JSONDecode(res)
                        if data and data.universeId then universeId = data.universeId end
                    end)
                end
                if universeId and universeId > 0 then
                    pcall(function()
                        local cursor = ""
                        while cursor do
                            local url = "https://games.roblox.com/v1/games/" .. tostring(universeId) .. "/game-passes?limit=100"
                            if cursor ~= "" then url = url .. "&cursor=" .. cursor end
                            local res  = game:HttpGet(url)
                            local data = HttpSvc:JSONDecode(res)
                            if data and data.data then
                                for _, gp in ipairs(data.data) do
