                    code = code .. ('MktSvc:SignalPromptGamePassPurchaseFinished(%d, %d, true)'):format(uid, id)
                elseif pType == "Product" then
                    code = code .. ('MktSvc:SignalPromptProductPurchaseFinished(%d, %d, true)'):format(uid, id)
                elseif pType == "Asset" then
                    code = code .. ('MktSvc:SignalPromptPurchaseFinished(%d, %d, true)'):format(uid, id)
                elseif pType == "Bundle" then
                    code = code .. ('MktSvc:SignalPromptBundlePurchaseFinished(%d, %d, true)'):format(uid, id)
                elseif pType == "Premium" then
