    local previewSec = tab:CreateSection("Preview & Copy", "Text di-generate otomatis " .. _CHR.EM_DASH .. " tekan COPY lalu paste di report Roblox")
    local textBox = New("TextBox", {
        Size = UDim2.new(1, 0, 0, 102),
