    })
    Round(regenBtn, 8)
    Stroke(regenBtn, Palette.StrokeSoft, 1, 0.5)
    local statusLabel = New("TextLabel", {
        Size = UDim2.new(1, 0, 0, 12),
        BackgroundTransparency = 1,
        Text = "Pilih player dan kategori laporan terlebih dahulu.",
        Font = Enum.Font.Gotham,
        TextSize = 8,
        TextColor3 = CDIM,
        TextXAlignment = Enum.TextXAlignment.Left,
        LayoutOrder = 4,
        Parent = previewSec.Body,
    })
    local function updateOutput()
        if not selectedPlayer or not selectedCategory then
            textBox.Text       = "Pilih player dan kategori laporan di atas."
            textBox.TextColor3 = Palette.SubText
            copyBtn.Text       = "COPY TEXT"
            Tween(copyBtn, 0.15, nil, nil, { BackgroundColor3 = Palette.Accent })
            statusLabel.Text       = "Pilih player dan kategori laporan terlebih dahulu."
            statusLabel.TextColor3 = CDIM
            return
        end
        textBox.Text       = buildText(selectedPlayer, selectedCategory)
        textBox.TextColor3 = Palette.Text
        statusLabel.Text       = "Siap " .. _CHR.EM_DASH .. " tekan COPY lalu paste di kolom report Roblox."
        statusLabel.TextColor3 = COK
    end
    local function onCopy()
        if not selectedPlayer or not selectedCategory then
            statusLabel.Text       = "Pilih player dan kategori laporan dulu!"
            statusLabel.TextColor3 = CWARN
            Tween(copyBtn, 0.15, nil, nil, { BackgroundColor3 = CWARN })
            task.delay(1.5, function()
                Tween(copyBtn, 0.15, nil, nil, { BackgroundColor3 = Palette.Accent })
                statusLabel.TextColor3 = CDIM
            end)
            return
        end
        local text = buildText(selectedPlayer, selectedCategory)
        local ok = SafeClipboard(text)
        if ok then
            copyBtn.Text = "COPIED " .. _CHR.CHECK
            Tween(copyBtn, 0.15, nil, nil, { BackgroundColor3 = COK })
            statusLabel.Text       = "Berhasil dicopy! Buka report Roblox dan paste."
            statusLabel.TextColor3 = COK
            task.delay(2.5, function()
                copyBtn.Text = "COPY TEXT"
                Tween(copyBtn, 0.15, nil, nil, { BackgroundColor3 = Palette.Accent })
            end)
        else
            copyBtn.Text = "Tap & Copy Manual"
            Tween(copyBtn, 0.15, nil, nil, { BackgroundColor3 = CWARN })
            statusLabel.Text       = "Executor tidak support setclipboard " .. _CHR.EM_DASH .. " select all di text box, copy manual."
            statusLabel.TextColor3 = CWARN
            task.delay(3, function()
                copyBtn.Text = "COPY TEXT"
                Tween(copyBtn, 0.15, nil, nil, { BackgroundColor3 = Palette.Accent })
            end)
        end
    end
    SafeConnect(GetSignal(copyBtn,  "Activated"),   onCopy)
    SafeConnect(GetSignal(regenBtn, "Activated"),   updateOutput)
    SafeConnect(GetSignal(copyBtn,  "MouseEnter"),  function() Tween(copyBtn, 0.12, nil, nil, { BackgroundColor3 = Palette.AccentDark }) end)
    SafeConnect(GetSignal(copyBtn,  "MouseLeave"),  function() Tween(copyBtn, 0.12, nil, nil, { BackgroundColor3 = Palette.Accent    }) end)
    SafeConnect(GetSignal(regenBtn, "MouseEnter"),  function() Tween(regenBtn, 0.12, nil, nil, { BackgroundColor3 = Palette.ElementHover }) end)
    SafeConnect(GetSignal(regenBtn, "MouseLeave"),  function() Tween(regenBtn, 0.12, nil, nil, { BackgroundColor3 = Palette.Element     }) end)
    local plrOrder = 0
    local function buildPlayerRow(plr)
        plrOrder = plrOrder + 1
        local row = New("Frame", {
            Size = UDim2.new(1, 0, 0, 30),
            BackgroundColor3 = Palette.Glass,
            LayoutOrder = plrOrder,
            Parent = plrScroll,
        })
        local selBar = New("Frame", {
            Size = UDim2.new(0, 3, 1, 0),
            BackgroundColor3 = Palette.Glass,
            Parent = row,
        })
        local avatar = New("ImageLabel", {
            Size = UDim2.new(0, 20, 0, 20),
            Position = UDim2.new(0, 6, 0.5, -10),
            BackgroundColor3 = Palette.Element,
            Image = "",
            ScaleType = Enum.ScaleType.Crop,
            Parent = row,
        })
        Round(avatar, 10)
        local dispL = New("TextLabel", {
            Size = UDim2.new(1, -36, 0, 13),
            Position = UDim2.new(0, 30, 0, 3),
            Text = plr.DisplayName,
            Font = Enum.Font.GothamBold,
            TextSize = 10,
            TextColor3 = Palette.Text,
            TextTruncate = Enum.TextTruncate.AtEnd,
            TextXAlignment = Enum.TextXAlignment.Left,
            BackgroundTransparency = 1,
            Parent = row,
        })
        local nameL = New("TextLabel", {
            Size = UDim2.new(1, -36, 0, 10),
            Position = UDim2.new(0, 30, 0, 17),
            Text = "@" .. plr.Name,
            Font = Enum.Font.Gotham,
            TextSize = 8,
            TextColor3 = Palette.SubText,
            TextTruncate = Enum.TextTruncate.AtEnd,
            TextXAlignment = Enum.TextXAlignment.Left,
            BackgroundTransparency = 1,
            Parent = row,
        })
        New("Frame", {
            Size = UDim2.new(1, 0, 0, 1),
            Position = UDim2.new(0, 0, 1, -1),
            BackgroundColor3 = Palette.Element,
            BackgroundTransparency = 0.3,
            Parent = row,
        })
        local hit = New("TextButton", {
            Size = UDim2.new(1, 0, 1, 0),
            BackgroundTransparency = 1,
            Text = "",
            ZIndex = 2,
            Parent = row,
        })
        task.spawn(function()
            local ok2, url = pcall(function()
                return Players:GetUserThumbnailAsync(
                    plr.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size48x48
                )
            end)
            if ok2 and url and url ~= "" then
                pcall(function() avatar.Image = url end)
            end
        end)
        local function setSelected(on)
            Tween(selBar,  0.15, nil, nil, { BackgroundColor3 = on and accent          or Palette.Glass      })
            Tween(row,     0.15, nil, nil, { BackgroundColor3 = on and Palette.GlassLight or Palette.Glass   })
            pcall(function()
                nameL.TextColor3 = on and accent or Palette.SubText
            end)
        end
        SafeConnect(GetSignal(hit, "Activated"), function()
            selectedPlayer      = plr
            selLabel.Text       = plr.DisplayName .. "  @" .. plr.Name
            selLabel.TextColor3 = Palette.Text
            for _, fn in pairs(plrBtns) do fn(false) end
            setSelected(true)
            updateOutput()
        end)
        SafeConnect(GetSignal(hit, "MouseEnter"), function()
            if selectedPlayer ~= plr then Tween(row, 0.1, nil, nil, { BackgroundColor3 = Palette.GlassLight }) end
        end)
        SafeConnect(GetSignal(hit, "MouseLeave"), function()
            if selectedPlayer ~= plr then Tween(row, 0.1, nil, nil, { BackgroundColor3 = Palette.Glass      }) end
        end)
        plrBtns[plr] = setSelected
    end
    for idx, cat in ipairs(CATEGORIES) do
        local row = New("Frame", {
            Size = UDim2.new(1, 0, 0, 26),
            BackgroundColor3 = Palette.Glass,
            LayoutOrder = idx,
            Parent = catScroll,
        })
        local selBar = New("Frame", {
            Size = UDim2.new(0, 3, 1, 0),
            BackgroundColor3 = Palette.Glass,
            Parent = row,
        })
        local nameL = New("TextLabel", {
            Size = UDim2.new(1, -14, 1, 0),
            Position = UDim2.new(0, 12, 0, 0),
            Text = cat.label,
            Font = Enum.Font.Gotham,
            TextSize = 9,
            TextColor3 = Palette.SubText,
            TextTruncate = Enum.TextTruncate.AtEnd,
            TextXAlignment = Enum.TextXAlignment.Left,
            BackgroundTransparency = 1,
            Parent = row,
        })
        New("Frame", {
            Size = UDim2.new(1, 0, 0, 1),
            Position = UDim2.new(0, 0, 1, -1),
            BackgroundColor3 = Palette.Element,
            BackgroundTransparency = 0.3,
            Parent = row,
        })
        local hit = New("TextButton", {
            Size = UDim2.new(1, 0, 1, 0),
            BackgroundTransparency = 1,
            Text = "",
            ZIndex = 2,
            Parent = row,
        })
        local function setSelected(on)
            Tween(selBar, 0.15, nil, nil, { BackgroundColor3 = on and accent          or Palette.Glass    })
            Tween(row,    0.15, nil, nil, { BackgroundColor3 = on and Palette.GlassLight or Palette.Glass })
            pcall(function() nameL.TextColor3 = on and Palette.Text or Palette.SubText end)
        end
        SafeConnect(GetSignal(hit, "Activated"), function()
            selectedCategory = cat
            for _, fn in pairs(catBtns) do fn(false) end
            setSelected(true)
            updateOutput()
        end)
        SafeConnect(GetSignal(hit, "MouseEnter"), function()
            if selectedCategory ~= cat then Tween(row, 0.1, nil, nil, { BackgroundColor3 = Palette.GlassLight }) end
        end)
        SafeConnect(GetSignal(hit, "MouseLeave"), function()
            if selectedCategory ~= cat then Tween(row, 0.1, nil, nil, { BackgroundColor3 = Palette.Glass      }) end
        end)
        catBtns[cat] = setSelected
    end
    catScroll.CanvasSize = UDim2.new(0, 0, 0, #CATEGORIES * 26)
    local function refreshPlayers()
        for _, c in ipairs(plrScroll:GetChildren()) do
            if c:IsA("Frame") then c:Destroy() end
        end
        plrBtns  = {}
        plrOrder = 0
        local count = 0
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= LocalPlayer then
                buildPlayerRow(plr)
                count = count + 1
            end
        end
        plrScroll.CanvasSize = UDim2.new(0, 0, 0, count * 30)
    end
    refreshPlayers()
    SafeConnect(GetSignal(Players, "PlayerAdded"), function()
        task.wait(0.05)
        refreshPlayers()
    end)
    SafeConnect(GetSignal(Players, "PlayerRemoving"), function()
        task.wait(0.1)
        refreshPlayers()
        if selectedPlayer and not Players:FindFirstChild(selectedPlayer.Name) then
            selectedPlayer      = nil
            selLabel.Text       = "Player keluar dari server"
            selLabel.TextColor3 = CWARN
            updateOutput()
        end
    end)
    local function doRptManualSearch()
        local kw = rptManualBox.Text
        if kw == "" then return end
        local kw_low = kw:lower()
        local found = nil
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= LocalPlayer then
                if plr.Name:lower():find(kw_low, 1, true)
                or plr.DisplayName:lower():find(kw_low, 1, true) then
                    found = plr
                    break
                end
            end
        end
        if found then
            selectedPlayer      = found
            selLabel.Text       = found.DisplayName .. "  @" .. found.Name
            selLabel.TextColor3 = Palette.Text
            for _, fn in pairs(plrBtns) do fn(false) end
            if plrBtns[found] then plrBtns[found](true) end
            rptManualBox.Text = ""
            updateOutput()
        else
            local prevText  = selLabel.Text
            local prevColor = selLabel.TextColor3
            selLabel.Text       = "Tidak ditemukan: \"" .. kw .. "\""
            selLabel.TextColor3 = CWARN
            task.delay(1.5, function()
                selLabel.Text       = prevText
                selLabel.TextColor3 = prevColor
            end)
        end
    end
    SafeConnect(GetSignal(rptSearchBtn, "Activated"), function()
        PlayUISound("Click")
        doRptManualSearch()
    end)
    SafeConnect(GetSignal(rptManualBox, "FocusLost"), function(enterPressed)
        if enterPressed then doRptManualSearch() end
    end)
end
local function RenderTabBuildError(tabName, errMsg)
    local ok = pcall(function()
        local tabObj = CreatedTabs and CreatedTabs[tabName]
        if not tabObj or not tabObj.Page then return end
        local card = New("Frame", {
            BackgroundColor3 = Color3.fromRGB(9, 9, 9),
            BackgroundTransparency = 0.1,
            Size = UDim2.new(1, 0, 0, 0),
            AutomaticSize = _AutomaticSizeY or Enum.AutomaticSize.Y,
            Parent = tabObj.Page,
        })
        Round(card, 12)
        Stroke(card, Color3.fromRGB(66, 66, 66), 1.4, 0.25)
        Pad(card, 14, 14, 12, 12)
        New("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 6), Parent = card })
        New("TextLabel", {
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 16),
            Font = Enum.Font.GothamBold,
            Text = _CHR.WARNING .. " Tab '" .. tostring(tabName) .. "' failed to load",
            TextColor3 = Color3.fromRGB(100, 100, 100),
            TextSize = 12,
            TextXAlignment = Enum.TextXAlignment.Left,
            Parent = card,
        })
        New("TextLabel", {
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 0),
            AutomaticSize = _AutomaticSizeY or Enum.AutomaticSize.Y,
            Font = Enum.Font.Code,
            Text = tostring(errMsg),
            TextColor3 = Color3.fromRGB(183, 183, 183),
            TextSize = 10,
            TextWrapped = true,
            TextXAlignment = Enum.TextXAlignment.Left,
            Parent = card,
        })
        New("TextLabel", {
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 0),
            AutomaticSize = _AutomaticSizeY or Enum.AutomaticSize.Y,
            Font = Enum.Font.Gotham,
            Text = "Screenshot this and send it back so it can be fixed. Other tabs are unaffected.",
            TextColor3 = Color3.fromRGB(114, 114, 114),
            TextSize = 9,
            TextWrapped = true,
            TextXAlignment = Enum.TextXAlignment.Left,
            Parent = card,
        })
    end)
    if not ok then
        warn("[JEYHUB] RenderTabBuildError itself failed for tab:", tabName)
    end
end
local function BuildTabStaggered(tabLabel, buildFn)
    task.spawn(function()
        local ok, err = pcall(buildFn)
        if not ok then
            warn("[JEYHUB] Build" .. tabLabel:gsub("%s", "") .. "Tab failed (caught safely):", err)
            RenderTabBuildError(tabLabel, err)
        end
    end)
end
