local _espMutexOwner = nil
local _utilityEspMasterToggle = nil
local _physicsEspMasterToggle = nil
local function BuildUtilityTab()
    local tab = CreatedTabs and CreatedTabs["Utility"]
    if not tab or not tab.CreateSection then return end
    local RunService = RunService
    local Camera = workspace.CurrentCamera
    local function getLocalChar() return LocalPlayer and LocalPlayer.Character end
    local fightSec = tab:CreateSection("Combat Manipulation", "Aimbot, FOV circle, lock-on, prediction")
    local AimbotSettings = {
        Enabled   = false,
        FOV       = 150,
        ShowFOV   = false,
        FOVColor  = Color3.fromRGB(254, 254, 254),
        Smoothness = 0.5,
        TargetPart = "Head",
        TeamCheck  = false,
        WallCheck  = false,
        Prediction = 0,
    }
    local FOVCircle = Drawing.new("Circle")
    FOVCircle.Position  = Vector2.new(0, 0)
    FOVCircle.Radius    = AimbotSettings.FOV
    FOVCircle.Filled    = false
    FOVCircle.Color     = AimbotSettings.FOVColor
    FOVCircle.Visible   = false
    FOVCircle.Thickness = 1.5
    local CurrentTarget = nil
    local _AimbotRP = RaycastParams.new()
    _AimbotRP.FilterType = Enum.RaycastFilterType.Exclude
    local function GetAimTarget()
        local Cam        = Camera
        local CenterPos  = Cam.ViewportSize / 2
        if CurrentTarget and CurrentTarget.Character
            and CurrentTarget.Character:FindFirstChild("Humanoid")
            and CurrentTarget.Character.Humanoid.Health > 0
            and CurrentTarget.Character:FindFirstChild(AimbotSettings.TargetPart) then
            if not (AimbotSettings.TeamCheck and CurrentTarget.Team == LocalPlayer.Team) then
                local tp = CurrentTarget.Character[AimbotSettings.TargetPart]
                local p, onScreen = Cam:WorldToViewportPoint(tp.Position)
                if onScreen then
                    local dist = (Vector2.new(p.X, p.Y) - CenterPos).Magnitude
                    if dist <= AimbotSettings.FOV + 50 then
                        if AimbotSettings.WallCheck then
                            local rp = _AimbotRP
                            rp.FilterDescendantsInstances = {getLocalChar(), Cam}
                            local hit = workspace:Raycast(Cam.CFrame.Position, (tp.Position - Cam.CFrame.Position).Unit * 10000, rp)
                            if hit and hit.Instance:IsDescendantOf(CurrentTarget.Character) then
                                return CurrentTarget
                            end
                        else
                            return CurrentTarget
                        end
                    end
                end
            end
        end
        local _rp = _AimbotRP
        if AimbotSettings.WallCheck then
            _rp.FilterDescendantsInstances = {getLocalChar(), Camera}
        end
        local closest, shortest = nil, AimbotSettings.FOV
        for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= LocalPlayer and plr.Character and plr.Character:FindFirstChild("Humanoid") and plr.Character.Humanoid.Health > 0 and plr.Character:FindFirstChild(AimbotSettings.TargetPart) and not (AimbotSettings.TeamCheck and plr.Team ~= nil and plr.Team == LocalPlayer.Team) then
            local tp = plr.Character[AimbotSettings.TargetPart]
            local p, onScreen = Camera:WorldToViewportPoint(tp.Position)
            if onScreen then
                local dist = (Vector2.new(p.X, p.Y) - CenterPos).Magnitude
                if dist < shortest then
                    if AimbotSettings.WallCheck then
                        local hit = workspace:Raycast(Camera.CFrame.Position, (tp.Position - Camera.CFrame.Position).Unit * 10000, _rp)
                        if hit and hit.Instance:IsDescendantOf(plr.Character) then
                            closest, shortest = plr, dist
                        end
                    else
                        closest, shortest = plr, dist
                    end
                end
            end
        end
        end
        CurrentTarget = closest
        return closest
    end
    DirectConnect(GetSignal(RunService, "RenderStepped"), function()
        if not AimbotSettings.Enabled and not AimbotSettings.ShowFOV then
            if FOVCircle.Visible then FOVCircle.Visible = false end
            return
        end
        pcall(function()
            local Cam        = Camera
            local CenterPos  = Cam.ViewportSize / 2
            FOVCircle.Position = CenterPos
            FOVCircle.Radius   = AimbotSettings.FOV
            FOVCircle.Color    = AimbotSettings.FOVColor
            FOVCircle.Visible  = AimbotSettings.ShowFOV
            if AimbotSettings.Enabled then
                local target = GetAimTarget()
                if target and target.Character and target.Character:FindFirstChild(AimbotSettings.TargetPart) then
                    local tp = target.Character[AimbotSettings.TargetPart]
                    local predOffset = tp.AssemblyLinearVelocity * AimbotSettings.Prediction
                    local targetPos  = tp.Position + predOffset
                    local goalCF     = CFrame.lookAt(Cam.CFrame.Position, targetPos)
                    Cam.CFrame       = Cam.CFrame:Lerp(goalCF, AimbotSettings.Smoothness)
                else
                    CurrentTarget = nil
                end
            else
                CurrentTarget = nil
            end
        end)
    end)
    fightSec:CreateToggle({
        Title    = "Enable Aimbot",
        Subtitle = "Kunci kamera ke musuh terdekat dalam FOV",
        Default  = false,
        Callback = function(s)
            AimbotSettings.Enabled = s
            if not s then CurrentTarget = nil end
        end,
    })
    fightSec:CreateToggle({
        Title    = "Team Check",
        Subtitle = "Lewati pemain dari tim yang sama",
        Default  = false,
        Callback = function(s) AimbotSettings.TeamCheck = s end,
    })
    fightSec:CreateToggle({
        Title    = "Wall Check",
        Subtitle = "Lock musuh yang terlihat saja (bukan tembok)",
        Default  = false,
        Callback = function(s) AimbotSettings.WallCheck = s end,
    })
    fightSec:CreateDropdown({
        Title    = "Target Part",
        Subtitle = "Bagian tubuh yang dijadikan titik kunci",
        Options  = {"Head", "HumanoidRootPart", "UpperTorso"},
        Default  = "Head",
        Callback = function(v) AimbotSettings.TargetPart = v end,
    })
    fightSec:CreateToggle({
        Title    = "Show FOV Circle",
        Subtitle = "Tampilkan lingkaran FOV di layar",
        Default  = false,
        Callback = function(s) AimbotSettings.ShowFOV = s end,
    })
    fightSec:CreateColorPicker({
        Title    = "FOV Color",
        Subtitle = "Warna lingkaran FOV",
        Default  = Color3.fromRGB(254, 254, 254),
        Callback = function(c)
            AimbotSettings.FOVColor = c
            FOVCircle.Color = c
        end,
    })
    fightSec:CreateSlider({
        Title    = "FOV Radius",
        Subtitle = "Ukuran radius FOV (px dari tengah layar)",
        Min = 10, Max = 800, Step = 5, Default = 150,
        Callback = function(v) AimbotSettings.FOV = v end,
    })
    fightSec:CreateSlider({
        Title    = "Smoothness",
        Subtitle = "Kecepatan lock kamera (1=instan, 0=diam)",
        Min = 1, Max = 100, Step = 1, Default = 50,
        Callback = function(v) AimbotSettings.Smoothness = v / 100 end,
    })
    fightSec:CreateSlider({
        Title    = "Prediction",
        Subtitle = "Kompensasi pergerakan target (lead shots)",
        Min = 0, Max = 100, Step = 1, Default = 0,
        Callback = function(v) AimbotSettings.Prediction = v / 100 end,
    })
    local espSec = tab:CreateSection("Visuals & ESP", "Box, name, distance, health bar, tracers, skeleton, charms, X-Ray")
    local ESPSettings = {
        Enabled      = false,
        Box          = false,
        Name         = false,
        Distance     = false,
        Health       = false,
        Tracers      = false,
        Skeleton     = false,
        Charms       = false,
        CharmsWeapon = false,
        CharmsDropped = false,
        XRay         = false,
        ESPColor     = Color3.fromRGB(254, 254, 254),
    }
    local xrayOriginal = {}
    local SKELETON_BONES = {
        {"Head","UpperTorso"}, {"Head","Torso"},
        {"UpperTorso","LowerTorso"},
        {"LowerTorso","LeftUpperLeg"}, {"LeftUpperLeg","LeftLowerLeg"}, {"LeftLowerLeg","LeftFoot"},
        {"LowerTorso","RightUpperLeg"}, {"RightUpperLeg","RightLowerLeg"}, {"RightLowerLeg","RightFoot"},
        {"UpperTorso","LeftUpperArm"}, {"LeftUpperArm","LeftLowerArm"}, {"LeftLowerArm","LeftHand"},
        {"UpperTorso","RightUpperArm"}, {"RightUpperArm","RightLowerArm"}, {"RightLowerArm","RightHand"},
        {"Torso","Left Arm"}, {"Torso","Right Arm"}, {"Torso","Left Leg"}, {"Torso","Right Leg"},
    }
    local ESPCache = {}
    local function CreateESP(plr)
        if ESPCache[plr] then return end
        local d = {
            BoxFill       = Drawing.new("Square"),
            Box           = Drawing.new("Square"),
            BoxOutline    = Drawing.new("Square"),
            Name          = Drawing.new("Text"),
            Distance      = Drawing.new("Text"),
            HealthOutline = Drawing.new("Square"),
            HealthBar     = Drawing.new("Square"),
            HealthText    = Drawing.new("Text"),
            Tracer        = Drawing.new("Line"),
            SkeletonList  = {},
            Charm         = Instance.new("Highlight"),
        }
        d.BoxFill.Filled        = true
        d.BoxFill.Transparency  = 0.88
        d.Box.Thickness         = 1
        d.Box.Transparency      = 0.20
        d.Box.Filled            = false
        d.BoxOutline.Thickness  = 1
        d.BoxOutline.Transparency = 0.65
        d.BoxOutline.Filled     = false
        d.BoxOutline.Color      = Color3.new(0, 0, 0)
        d.Name.Size             = 11
        d.Name.Center           = true
        d.Name.Outline          = true
        d.Name.Font             = 2
        d.Distance.Size         = 10
        d.Distance.Center       = true
        d.Distance.Outline      = true
        d.Distance.Font         = 2
        d.CurrentHealth         = 100
        d._lastChar             = nil
        d._skelCache            = {}
        d.HealthOutline.Filled  = true
        d.HealthOutline.Color   = Color3.fromRGB(4, 4, 4)
        d.HealthOutline.Transparency = 0.2
        d.HealthBar.Filled      = true
        d.HealthText.Size       = 9
        d.HealthText.Center     = false
        d.HealthText.Outline    = true
        d.HealthText.Color      = Color3.fromRGB(100, 220, 100)
        d.HealthText.Font       = 2
        d.Tracer.Thickness      = 1
        d.Tracer.Transparency   = 0.65
        d.Charm.FillTransparency    = 0.35
        d.Charm.OutlineTransparency = 0.1
        d.Charm.DepthMode           = Enum.HighlightDepthMode.AlwaysOnTop
        for _ = 1, #SKELETON_BONES do
            local ln = Drawing.new("Line")
            ln.Thickness   = 1.2
            ln.Transparency = 0.9
            table.insert(d.SkeletonList, ln)
        end
        ESPCache[plr] = d
    end
    local function RemoveESP(plr)
        local d = ESPCache[plr]
        if not d then return end
        for k, v in pairs(d) do
            if k == "SkeletonList" then
                for _, ln in ipairs(v) do pcall(function() ln:Remove() end) end
            elseif k == "Charm" or k == "WeaponCharm" then
                pcall(function() v:Destroy() end)
            else
                pcall(function() v:Remove() end)
            end
        end
        ESPCache[plr] = nil
        if _espBoxCache then _espBoxCache[plr] = nil end
    end
    SafeConnect(GetSignal(Players, "PlayerAdded"),   CreateESP)
    SafeConnect(GetSignal(Players, "PlayerRemoving"), RemoveESP)
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= LocalPlayer then CreateESP(plr) end
    end
    local droppedCharmsCache = {}
    local _espDroppedFrame  = 0
    local _espGlobalFrame   = 0
    local _espBoxCache    = {}
    local _espNameCache   = {}
    local _espHealthCache = {}
    local _clamp = math.clamp
    local _floor = math.floor
    local _abs   = math.abs
    local _tan   = math.tan
    local _rad   = math.rad
    local _max   = math.max
    local _zl_cachedFOV  = 0
    local _zl_projY      = 0
    local function _zl_updateProj(vpY, fov)
        if fov ~= _zl_cachedFOV then
            _zl_cachedFOV = fov
            _zl_projY     = vpY / (2 * _tan(_rad(fov * 0.5)))
        end
    end
    local function _fastBox(pos, depth, projY)
        local scale = projY / depth
        local h = scale * 5.3
        local w = scale * 2.1
        return pos.X - w * 0.5, pos.Y - h * 0.58, w, h
    end
    local function _healthColor(ratio, plr)
        local c = _espHealthCache[plr]
        if c and _abs(c.r - ratio) < 0.01 then return c.col end
        local r   = _clamp(2 - ratio * 2, 0, 1)
        local g   = _clamp(ratio * 2,     0, 1)
        local col = Color3.new(r, g, 0)
        _espHealthCache[plr] = { r = ratio, col = col }
        return col
    end
    local function _playerName(plr)
        local c  = _espNameCache[plr]
        local dn = plr.DisplayName
        local un = plr.Name
        local k  = dn ~= un and (dn .. un) or un
        if c and c.k == k then return c.t end
        local t = (dn ~= un) and (dn .. "  @" .. un) or dn
        _espNameCache[plr] = { k = k, t = t }
        return t
    end
    DirectConnect(GetSignal(RunService, "RenderStepped"), function()
        if not ESPSettings.Enabled and not ESPSettings.CharmsDropped then return end
        _espGlobalFrame = _espGlobalFrame + 1
        local lagMode    = _ZL.lagStats.frameSkipRate > 0
        local isBoxFrame  = lagMode and (_espGlobalFrame % 6 == 0)
                                    or  (_espGlobalFrame % 2 == 0)
        local isSkelFrame = (not lagMode) and (_espGlobalFrame % 5 == 0)
        local Cam       = Camera
        local vp        = Cam.ViewportSize
        local vpHalfX   = vp.X * 0.5
        local vpTracerY = vp.Y * 0.96
        _zl_updateProj(vp.Y, Cam.FieldOfView)
        local projY = _zl_projY
        for plr, esp in pairs(ESPCache) do
            local visible = false
            local char = plr.Character
            if ESPSettings.Enabled and char then
                local hrp = char:FindFirstChild("HumanoidRootPart")
                local hum = char:FindFirstChild("Humanoid")
                if hrp and hum and hum.Health > 0 then
                    local pos, onScreen = Cam:WorldToViewportPoint(hrp.Position)
                    local depth = pos.Z
                    if onScreen and depth > 0 and depth <= 450 then
                        visible = true
                        local gc = ESPSettings.ESPColor
                        local bc = _espBoxCache[plr]
                        if isBoxFrame or not bc then
                            local bx, by, bw, bh = _fastBox(pos, depth, projY)
                            bc = { x = bx, y = by, w = bw, h = bh }
                            _espBoxCache[plr] = bc
                        end
                        if bc then
                            local bx, by, bw, bh = bc.x, bc.y, bc.w, bc.h
                            local cx = bx + bw * 0.5
                            if ESPSettings.Box then
                                local sv2 = Vector2.new(bw, bh)
                                local sp2 = Vector2.new(bx, by)
                                esp.BoxFill.Size        = sv2
                                esp.BoxFill.Position    = sp2
                                esp.BoxFill.Color       = gc
                                esp.BoxFill.Transparency = 0.88
                                esp.BoxFill.Visible     = true
                                esp.Box.Size            = sv2
                                esp.Box.Position        = sp2
                                esp.Box.Color           = gc
                                esp.Box.Visible         = true
                                esp.BoxOutline.Size     = sv2
                                esp.BoxOutline.Position = sp2
                                esp.BoxOutline.Visible  = true
                            else
                                esp.BoxFill.Visible    = false
                                esp.Box.Visible        = false
                                esp.BoxOutline.Visible = false
                            end
                            if ESPSettings.Name then
                                esp.Name.Text     = _playerName(plr)
                                esp.Name.Position = Vector2.new(cx, by - 14)
                                esp.Name.Color    = gc
                                esp.Name.Visible  = true
                            else
                                esp.Name.Visible = false
                            end
                            if ESPSettings.Distance then
                                esp.Distance.Text     = _floor(depth) .. "m"
                                esp.Distance.Position = Vector2.new(cx, by + bh + 2)
                                esp.Distance.Color    = Color3.new(0.651, 0.651, 0.651)
                                esp.Distance.Visible  = true
                            else
                                esp.Distance.Visible = false
                            end
                            if ESPSettings.Health then
                                local tH = hum.Health
                                local mH = hum.MaxHealth
                                if not esp.CurrentHealth then esp.CurrentHealth = tH end
                                esp.CurrentHealth = esp.CurrentHealth + (tH - esp.CurrentHealth) * 0.12
                                local ratio = _clamp(esp.CurrentHealth / mH, 0, 1)
                                local hc   = _healthColor(ratio, plr)
                                local barW = 4
                                local ot   = 1
                                local barX = bx - barW - 5 - ot
                                esp.HealthOutline.Size         = Vector2.new(barW + ot * 2, bh + ot * 2)
                                esp.HealthOutline.Position     = Vector2.new(barX - ot, by - ot)
                                esp.HealthOutline.Transparency = 0.35
                                esp.HealthOutline.Visible      = true
                                local barH = _max(bh * ratio, 1)
                                esp.HealthBar.Size         = Vector2.new(barW, barH)
                                esp.HealthBar.Position     = Vector2.new(barX, by + bh - barH)
                                esp.HealthBar.Color        = hc
                                esp.HealthBar.Transparency = 0
                                esp.HealthBar.Visible      = true
                                local pct = _floor(ratio * 100)
                                esp.HealthText.Text         = pct .. "%"
                                esp.HealthText.Position     = Vector2.new(barX - 1, by - 11)
                                esp.HealthText.Color        = hc
                                esp.HealthText.Transparency = 0
                                esp.HealthText.Visible      = true
                            else
                                esp.HealthBar.Visible     = false
                                esp.HealthOutline.Visible = false
                                esp.HealthText.Visible    = false
                            end
                            if ESPSettings.Tracers then
                                esp.Tracer.From    = Vector2.new(vpHalfX, vpTracerY)
                                esp.Tracer.To      = Vector2.new(cx, by + bh)
                                esp.Tracer.Color   = gc
                                esp.Tracer.Visible = true
                            else
                                esp.Tracer.Visible = false
                            end
                        end
                        if ESPSettings.Skeleton then
                            if isSkelFrame then
                                if esp._lastChar ~= char then
                                    esp._lastChar  = char
                                    esp._skelCache = {}
                                    for i, joint in ipairs(SKELETON_BONES) do
                                        esp._skelCache[i] = {
                                            char:FindFirstChild(joint[1]),
                                            char:FindFirstChild(joint[2])
                                        }
                                    end
                                end
                                for i = 1, #SKELETON_BONES do
                                    local entry = esp._skelCache[i]
                                    local p1 = entry and entry[1]
                                    local p2 = entry and entry[2]
                                    if p1 and p2 then
                                        local s1, v1 = Cam:WorldToViewportPoint(p1.Position)
                                        local s2, v2 = Cam:WorldToViewportPoint(p2.Position)
                                        if v1 or v2 then
                                            esp.SkeletonList[i].From    = Vector2.new(s1.X, s1.Y)
                                            esp.SkeletonList[i].To      = Vector2.new(s2.X, s2.Y)
                                            esp.SkeletonList[i].Color   = gc
                                            esp.SkeletonList[i].Visible = true
                                        else
                                            esp.SkeletonList[i].Visible = false
                                        end
                                    else
                                        esp.SkeletonList[i].Visible = false
                                    end
                                end
                            end
                        else
                            for _, ln in ipairs(esp.SkeletonList) do ln.Visible = false end
                        end
                        if ESPSettings.Charms then
                            if esp.Charm.Parent ~= char then esp.Charm.Parent = char end
                            esp.Charm.FillColor    = gc
                            esp.Charm.OutlineColor = gc
                            esp.Charm.Enabled      = true
                        else
                            esp.Charm.Enabled = false
                        end
                        if ESPSettings.CharmsWeapon then
                            local tool = char:FindFirstChildOfClass("Tool")
                            if tool then
                                if not esp.WeaponCharm then
                                    esp.WeaponCharm = Instance.new("Highlight")
                                    esp.WeaponCharm.FillTransparency    = 0.35
                                    esp.WeaponCharm.OutlineTransparency = 0.1
                                    esp.WeaponCharm.DepthMode           = Enum.HighlightDepthMode.AlwaysOnTop
                                end
                                if esp.WeaponCharm.Parent ~= tool then esp.WeaponCharm.Parent = tool end
                                esp.WeaponCharm.FillColor    = gc
                                esp.WeaponCharm.OutlineColor = gc
                                esp.WeaponCharm.Enabled      = true
                            else
                                if esp.WeaponCharm then esp.WeaponCharm.Enabled = false end
                            end
                        else
                            if esp.WeaponCharm then esp.WeaponCharm.Enabled = false end
                        end
                    end
                end
            end
            if not visible then
                esp.BoxFill.Visible       = false
                esp.Box.Visible           = false
                esp.BoxOutline.Visible    = false
                esp.Name.Visible          = false
                esp.Distance.Visible      = false
                esp.HealthBar.Visible     = false
                esp.HealthOutline.Visible = false
                esp.HealthText.Visible    = false
                esp.Tracer.Visible        = false
                for _, ln in ipairs(esp.SkeletonList) do ln.Visible = false end
                esp.Charm.Enabled = false
                if esp.WeaponCharm then esp.WeaponCharm.Enabled = false end
                _espBoxCache[plr] = nil
            end
        end
        _espDroppedFrame = _espDroppedFrame + 1
        if ESPSettings.CharmsDropped and _espDroppedFrame >= 6 then
            _espDroppedFrame = 0
            for _, tool in ipairs(workspace:GetChildren()) do
                if tool:IsA("Tool") then
                    if not droppedCharmsCache[tool] then
                        local hl = Instance.new("Highlight")
                        hl.FillTransparency    = 0.35
                        hl.OutlineTransparency = 0.1
                        hl.DepthMode           = Enum.HighlightDepthMode.AlwaysOnTop
                        hl.Parent = tool
                        droppedCharmsCache[tool] = hl
                    end
                    droppedCharmsCache[tool].FillColor    = ESPSettings.ESPColor
                    droppedCharmsCache[tool].OutlineColor = ESPSettings.ESPColor
                    droppedCharmsCache[tool].Enabled      = true
                end
            end
        elseif not ESPSettings.CharmsDropped then
            for _, hl in pairs(droppedCharmsCache) do
                if hl then hl.Enabled = false end
            end
        end
        for tool, hl in pairs(droppedCharmsCache) do
            if not tool or tool.Parent ~= workspace then
                if hl then hl:Destroy() end
                droppedCharmsCache[tool] = nil
            end
        end
    end)
    espSec:CreateColorPicker({
        Title    = "Global ESP Color",
        Subtitle = "Warna yang dipakai semua elemen ESP",
        Default  = Color3.fromRGB(254, 254, 254),
        Callback = function(c) ESPSettings.ESPColor = c end,
    })
    _utilityEspMasterToggle = espSec:CreateToggle({
        Title    = "Enable ESP Master",
        Subtitle = "Switch utama " .. _CHR.EM_DASH .. " tidak bisa dengan Physics ESP",
        Default  = false,
        Callback = function(s)
            if s then
                if _espMutexOwner == "physics" then
                    ShowNotification("ESP", "Physics Target ESP sedang aktif " .. _CHR.EM_DASH .. " matikan dulu", 3)
                    task.defer(function()
                        if _utilityEspMasterToggle then _utilityEspMasterToggle.Set(false, false) end
                    end)
                    return
                end
                _espMutexOwner = "utility"
            else
                if _espMutexOwner == "utility" then _espMutexOwner = nil end
            end
            ESPSettings.Enabled = s
        end,
    })
    espSec:CreateToggle({
        Title    = "ESP Box",
        Subtitle = "Kotak persegi panjang di sekeliling karakter",
        Default  = false,
        Callback = function(s) ESPSettings.Box = s end,
    })
    espSec:CreateToggle({
        Title    = "ESP Name",
        Subtitle = "Nama pemain di atas kepala",
        Default  = false,
        Callback = function(s) ESPSettings.Name = s end,
    })
    espSec:CreateToggle({
        Title    = "ESP Distance",
        Subtitle = "Jarak ke target",
        Default  = false,
        Callback = function(s) ESPSettings.Distance = s end,
    })
    espSec:CreateToggle({
        Title    = "ESP Health Bar",
        Subtitle = "Bar HP di sisi kiri kotak, warna hijau" .. _CHR.ARROW_RIGHT .. "merah",
        Default  = false,
        Callback = function(s) ESPSettings.Health = s end,
    })
    espSec:CreateToggle({
        Title    = "ESP Tracers",
        Subtitle = "Garis dari bawah layar ke kaki musuh",
        Default  = false,
        Callback = function(s) ESPSettings.Tracers = s end,
    })
    espSec:CreateToggle({
        Title    = "ESP Skeleton",
        Subtitle = "Garis tulang yang menghubungkan joint karakter",
        Default  = false,
        Callback = function(s) ESPSettings.Skeleton = s end,
    })
    espSec:CreateToggle({
        Title    = "ESP Charms (Full Body)",
        Subtitle = "Highlight penuh karakter musuh",
        Default  = false,
        Callback = function(s) ESPSettings.Charms = s end,
    })
    espSec:CreateToggle({
        Title    = "ESP Weapon Charms",
        Subtitle = "Highlight tool yang dipegang musuh",
        Default  = false,
        Callback = function(s) ESPSettings.CharmsWeapon = s end,
    })
    espSec:CreateToggle({
        Title    = "ESP Dropped Items",
        Subtitle = "Highlight semua Tool yang jatuh di workspace",
        Default  = false,
        Callback = function(s) ESPSettings.CharmsDropped = s end,
    })
    espSec:CreateToggle({
        Title    = "X-Ray Vision",
        Subtitle = "Semua BasePart non-karakter jadi semi-transparan",
        Default  = false,
        Callback = function(s)
            ESPSettings.XRay = s
            pcall(function()
                for _, v in ipairs(workspace:GetDescendants()) do
                    if v:IsA("BasePart")
                        and not v.Parent:FindFirstChild("Humanoid")
                        and not (v.Parent.Parent and v.Parent.Parent:FindFirstChild("Humanoid")) then
                        if s then
                            if not xrayOriginal[v] then xrayOriginal[v] = v.Transparency end
                            v.Transparency = 0.5
                        else
                            if xrayOriginal[v] ~= nil then
                                v.Transparency = xrayOriginal[v]
                                xrayOriginal[v] = nil
                            end
                        end
                    end
                end
            end)
        end,
    })
end
BuildTabStaggered("Utility", BuildUtilityTab)
task.wait()
local function BuildTrollTab()
    local tab = CreatedTabs and CreatedTabs["Troll"]
    if not tab or not tab.CreateSection then return end
    local RunService = RunService
    local function getChar()  return LocalPlayer and LocalPlayer.Character end
    local function getRoot()  local c = getChar() return c and c:FindFirstChild("HumanoidRootPart") end
    local function getHum()   local c = getChar() return c and c:FindFirstChildOfClass("Humanoid") end
    local spasmActive, spinBotActive, moonwalkActive = false, false, false
    local tposeActive, fakeLagActive = false, false
    local FL_INTERVAL   = 0.5
    local flLastTick    = 0
    local flGhostModel  = nil
    local flPartMap     = {}
    local NetworkClient = SafeService("NetworkClient")
    local function flRemoveGhost()
        if flGhostModel then
            pcall(function() flGhostModel:Destroy() end)
            flGhostModel = nil
        end
        table.clear(flPartMap)
    end
    local function flResetNetwork()
        pcall(function() setfflag("FFlagDebugSimPacketLoss", "0") end)
        pcall(function()
            if NetworkClient then
                sethiddenproperty(NetworkClient, "OutgoingKBPS", 10000)
            end
        end)
        local root = getRoot()
        if root then
            pcall(function() sethiddenproperty(root, "NetworkIsWaitingForFinalGoal", false) end)
        end
    end
    local function flCreateGhost()
        flRemoveGhost()
        local char = getChar()
        if not char then return end
        pcall(function()
            char.Archivable = true
            flGhostModel = char:Clone()
            char.Archivable = false
            flGhostModel.Name = "JeyHubServerGhost"
            for _, obj in ipairs(flGhostModel:GetDescendants()) do
                if obj:IsA("Script") or obj:IsA("LocalScript")
                    or obj:IsA("Animator") or obj:IsA("Weld")
                    or obj:IsA("WeldConstraint") or obj:IsA("Motor6D") then
                    obj:Destroy()
                elseif obj:IsA("BasePart") then
                    obj.CanCollide    = false
                    obj.Anchored      = true
                    obj.Transparency  = 0.7
                    obj.Material      = Enum.Material.SmoothPlastic
                    obj.Color         = Color3.fromRGB(140, 140, 160)
                end
            end
            for _, charPart in ipairs(char:GetDescendants()) do
                if charPart:IsA("BasePart") then
                    local gp
                    if charPart.Parent == char then
                        gp = flGhostModel:FindFirstChild(charPart.Name)
                    else
                        local pname = charPart.Parent and charPart.Parent.Name
                        local gparent = pname and flGhostModel:FindFirstChild(pname)
                        gp = gparent and gparent:FindFirstChild(charPart.Name)
                    end
                    if gp and gp:IsA("BasePart") then
                        flPartMap[charPart] = gp
                    end
                end
            end
            flGhostModel.Parent = workspace
        end)
    end
    local function flUpdateGhost()
        for charPart, ghostPart in pairs(flPartMap) do
            if charPart and charPart.Parent and ghostPart and ghostPart.Parent then
                ghostPart.CFrame = charPart.CFrame
            end
        end
    end
    DirectConnect(GetSignal(RunService, "Heartbeat"), function()
        if not fakeLagActive
            and not moonwalkActive
            and not tposeActive
            and not spasmActive
            and not spinBotActive then return end
        pcall(function()
            local root = getRoot()
            local hum  = getHum()
            local char = getChar()
            if not root or not hum or not char then return end
            if fakeLagActive then
                local now = os.clock()
                if now - flLastTick >= FL_INTERVAL then
                    flLastTick = now
                    flResetNetwork()
                    flUpdateGhost()
                else
                    pcall(function() setfflag("FFlagDebugSimPacketLoss", "100") end)
                    pcall(function()
                        if NetworkClient then
                            sethiddenproperty(NetworkClient, "OutgoingKBPS", 1)
                        end
                    end)
                    pcall(function()
                        sethiddenproperty(root, "NetworkIsWaitingForFinalGoal", true)
                    end)
                end
            end
            if moonwalkActive then
                hum.AutoRotate = false
                if hum.MoveDirection.Magnitude > 0 then
                    root.CFrame = CFrame.new(root.Position, root.Position - hum.MoveDirection)
                end
            else
                hum.AutoRotate = true
            end
            if tposeActive then
                local rS = (char:FindFirstChild("Torso") and char.Torso:FindFirstChild("Right Shoulder"))
                    or (char:FindFirstChild("RightUpperArm") and char.RightUpperArm:FindFirstChild("RightShoulder"))
                local lS = (char:FindFirstChild("Torso") and char.Torso:FindFirstChild("Left Shoulder"))
                    or (char:FindFirstChild("LeftUpperArm") and char.LeftUpperArm:FindFirstChild("LeftShoulder"))
                if rS and rS:IsA("Motor6D") then rS.Transform = CFrame.Angles(0, 0, math.rad(90)) end
                if lS and lS:IsA("Motor6D") then lS.Transform = CFrame.Angles(0, 0, math.rad(-90)) end
            end
            if spasmActive then
                root.CFrame = root.CFrame * CFrame.Angles(
                    math.rad(math.random(-360,360)),
                    math.rad(math.random(-360,360)),
                    math.rad(math.random(-360,360)))
            end
            if spinBotActive then
