                    local lS=(char:FindFirstChild("Torso") and char.Torso:FindFirstChild("Left Shoulder")) or (char:FindFirstChild("LeftUpperArm") and char.LeftUpperArm:FindFirstChild("LeftShoulder"))
                    if rS and rS:IsA("Motor6D") then rS.Transform=CFrame.new() end
                    if lS and lS:IsA("Motor6D") then lS.Transform=CFrame.new() end
