_phys.isSeatName = function(n)
    for i = 1, #_phys.seatKW do if n:find(_phys.seatKW[i], 1, true) then return true end end
    return false
end
_phys.isObject = function(obj)
    if not obj or not obj:IsA("BasePart") then return false end
    if obj.Anchored then return false end
    local connectedParts = obj:GetConnectedParts()
    for _, part in ipairs(connectedParts) do
        if part.Anchored then return false end
    end
    local ar = obj.AssemblyRootPart
    if ar and ar.Anchored then return false end
    if obj:FindFirstChildOfClass("Attachment") then return false end
    local par = obj.Parent
    while par do
        if par:IsA("Backpack") or par:IsA("Accessory") then return false end
        if par:IsA("Model") and par:FindFirstChildOfClass("Humanoid") then return false end
        par = par.Parent
    end
    return true
end
local function _PhysClaimObj(obj)
    if not _phys.physicsActive and not _phys.aegisActive then return end
    if not _phys.isObject(obj) then return end
    local lchar = LocalPlayer.Character
    if lchar and obj:IsDescendantOf(lchar) then return end
    local myHrp = lchar and lchar:FindFirstChild("HumanoidRootPart")
    if not myHrp or _phys.myPhysicsObjects[obj] then return end
    pcall(function()
        _phys.originalPartStates[obj] = {
            CFrame=obj.CFrame, Anchored=obj.Anchored, CanCollide=obj.CanCollide,
            Massless=obj.Massless, CustomPhys=obj.CustomPhysicalProperties, Parent=obj.Parent,
        }
    end)
    _phys.myPhysicsObjects[obj] = true
    pcall(function()
        if obj.Parent and obj.Parent:IsA("Tool") then obj.Parent = workspace end
        for _,x in ipairs(obj:GetDescendants()) do
            if x:IsA("BodyMover") or x:IsA("RocketPropulsion") or x:IsA("Constraint")
            or x:IsA("Weld") or x:IsA("WeldConstraint") or x:IsA("Motor6D")
            or x:IsA("BodyVelocity") or x:IsA("BodyPosition") or x:IsA("BodyForce")
            or x:IsA("AngularVelocity") or x:IsA("LinearVelocity")
            or x:IsA("Script") or x:IsA("LocalScript") then x:Destroy() end
        end
        local isOwned = true
        if type(isnetworkowner) == "function" then
            isOwned = isnetworkowner(obj)
        end
        if isOwned then
            obj.CFrame = myHrp.CFrame
            obj.Anchored = false
            obj.CanCollide = false
            obj.Massless = true
            obj.CustomPhysicalProperties = PhysicalProperties.new(math.huge, math.huge, 0, 100, 0)
        end
        if sethiddenproperty then
            pcall(function() sethiddenproperty(obj, "NetworkOwnership", LocalPlayer) end)
            pcall(function() sethiddenproperty(obj, "NetworkIsSleeping", false) end)
        end
        pcall(function() obj:SetNetworkOwner(LocalPlayer) end)
    end)
end
local function _PhysClearMovers()
    for _,m in pairs(_phys.victimMovers) do
        pcall(function() if m.bv then m.bv:Destroy() end end)
        pcall(function() if m.bav then m.bav:Destroy() end end)
    end
    _phys.victimMovers = {}
end
local function _PhysRestoreAll()
    local statesToRestore = _phys.originalPartStates
    _phys.originalPartStates = {}
    _phys.myPhysicsObjects   = {}
    for obj, state in pairs(statesToRestore) do
        if obj and obj.Parent then
            pcall(function()
                if sethiddenproperty then
                    pcall(function() sethiddenproperty(obj, "NetworkOwnership", nil) end)
                end
                pcall(function() obj:SetNetworkOwner(nil) end)
                obj.CFrame      = state.CFrame
                obj.Anchored    = state.Anchored
                obj.CanCollide  = state.CanCollide
                obj.Massless    = state.Massless
                obj.CustomPhysicalProperties = state.CustomPhys
                if state.Parent and state.Parent.Parent then obj.Parent = state.Parent end
                obj.AssemblyLinearVelocity  = Vector3.zero
                obj.AssemblyAngularVelocity = Vector3.zero
            end)
        end
    end
end
local function _PhysGetTargetPos(char)
    if not char then return nil end
    if _phys.targetPartName=="HumanoidRootPart" then
        local hrp=char:FindFirstChild("HumanoidRootPart")
        return hrp and hrp.Position
    else
        local l=char:FindFirstChild("LeftLeg") or char:FindFirstChild("LeftFoot") or char:FindFirstChild("LeftLowerLeg")
        local r=char:FindFirstChild("RightLeg") or char:FindFirstChild("RightFoot") or char:FindFirstChild("RightLowerLeg")
        if l and r then return (l.Position+r.Position)/2
        elseif l then return l.Position
        elseif r then return r.Position
        else local h=char:FindFirstChild("HumanoidRootPart") return h and h.Position end
    end
end
local function _PhysMakeFling(snapPos, myHrp)
    local F = _phys.HF
    local outDir = Vector3.new(0, 0, 1)
    if myHrp and snapPos then
        local d = snapPos - myHrp.Position
        if d.Magnitude > 0.1 then outDir = d.Unit end
    end
    return {
        linear  = Vector3.new(outDir.X * F, F, outDir.Z * F),
        angular = Vector3.new(F, F, F),
    }
end
local function _PhysMakeObliterate(snapPos, myHrp)
    local F = _phys.HF * 5
    local outDir = Vector3.new(0, 0, 1)
    if myHrp and snapPos then
        local d = snapPos - myHrp.Position
        if d.Magnitude > 0.1 then outDir = d.Unit end
    end
    return {
        linear  = Vector3.new(outDir.X * F, F, outDir.Z * F),
        angular = Vector3.new(F, F, F),
    }
end
local function _PhysApplyFling(obj, force, tChar)
    local tHrp = tChar:FindFirstChild("HumanoidRootPart")
    if not tHrp then return end
    local snapPos = tHrp.Position
    obj.CFrame                  = CFrame.new(snapPos)
    obj.AssemblyLinearVelocity  = force.linear
    obj.AssemblyAngularVelocity = force.angular
    pcall(function() obj.Velocity    = force.linear  end)
    pcall(function() obj.RotVelocity = force.angular end)
    local th = tChar:FindFirstChildOfClass("Humanoid")
    if th then pcall(function()
        th:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, true)
        th:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
        th.PlatformStand = true
        th:ChangeState(Enum.HumanoidStateType.Ragdoll)
    end) end
    pcall(function()
        tHrp.AssemblyLinearVelocity  = force.linear
        tHrp.AssemblyAngularVelocity = force.angular
    end)
    if firetouchinterest then
        local function _wave()
            if not (obj and obj.Parent and tChar and tChar.Parent) then return end
            local freshHrp = tChar:FindFirstChild("HumanoidRootPart")
            if not freshHrp then return end
            obj.CFrame                  = CFrame.new(freshHrp.Position)
            obj.AssemblyLinearVelocity  = force.linear
            obj.AssemblyAngularVelocity = force.angular
            for _, part in ipairs(tChar:GetDescendants()) do
                if part:IsA("BasePart") then
                    firetouchinterest(obj, part, 0)
                    firetouchinterest(obj, part, 1)
                end
            end
            pcall(function() freshHrp.AssemblyLinearVelocity = force.linear end)
        end
        _wave()
        task.defer(_wave)
        task.defer(function() task.defer(_wave) end)
    end
end
local function _PhysClearObstacles(pos,radius,excl)
    local op=OverlapParams.new()
    op.FilterDescendantsInstances=excl or {}
    op.FilterType=Enum.RaycastFilterType.Exclude
    for _,part in ipairs(workspace:GetPartBoundsInRadius(pos,radius,op)) do
        if part:IsA("BasePart") and part.CanCollide then part.CanCollide=false end
    end
end
local function _PhysUpdateTracker(name,vel,_pos)
    local t=_phys.targetVelTracker[name]
    if not t or not t._e then
        t={_e=true,vels={},smoothedVel=vel,smoothedAcc=Vector3.zero,strafeCount=0,lastStrafeDir=Vector3.zero,lastTime=tick(),vel=vel}
        _phys.targetVelTracker[name]=t
    end
    local now=tick()
    table.insert(t.vels,{time=now,vel=vel})
    while #t.vels>_phys.HIST do table.remove(t.vels,1) end
    t.smoothedVel=t.smoothedVel*0.45+vel*0.55
    if #t.vels>=2 then
        local o=t.vels[1]
        local n=t.vels[#t.vels]
        local dt=n.time-o.time
        if dt>0.005 then
            local ra=(n.vel-o.vel)*(1/dt)
            if ra.Magnitude>600 then ra=ra.Unit*600 end
            t.smoothedAcc=t.smoothedAcc*0.65+ra*0.35
        end
    end
    t.vel=vel
    return t
end
local function _PhysPredict(root,charModel,tName,myPos,extraExcl)
    local cv=root.AssemblyLinearVelocity
    local vm=cv.Magnitude
    if vm<0.5 then return root.Position+Vector3.new((math.random()-0.5)*0.3,(math.random()-0.5)*0.3,(math.random()-0.5)*0.3) end
    local isFast=vm>=200
    _PhysUpdateTracker(tName,cv,root.Position)
    local tr=_phys.targetVelTracker[tName]
    local dist=math.max((root.Position-myPos).Magnitude,1)
    local prop=dist/3500
    local t=math.clamp(_phys.emaPing*0.5+(_phys.emaJitter*0.25)+prop,0.008,0.45)
    local v0=isFast and cv or tr.smoothedVel
    local acc=isFast and Vector3.zero or tr.smoothedAcc
    local g=workspace.Gravity or 196.2
    if v0.Y<-0.5 or (not isFast and math.abs(v0.Y)>0.5) then acc=Vector3.new(acc.X,acc.Y-g,acc.Z) end
    local av=root.AssemblyAngularVelocity
    if av.Magnitude<0.01 then av=root.RotVelocity end
    local displacement=(v0*t)+(0.5*acc*t*t)+(av*t)*0.18
    if not isFast then
        local rp=RaycastParams.new()
        rp.FilterType=Enum.RaycastFilterType.Exclude
        local ex={charModel,LocalPlayer.Character}
        if extraExcl then for _,e in ipairs(extraExcl) do table.insert(ex,e) end end
        rp.FilterDescendantsInstances=ex
        local wr=workspace:Raycast(root.Position,displacement,rp)
        if wr then displacement=(wr.Position-root.Position)*0.92 end
    end
    return root.Position+displacement
end
local function _PhysEnforceSpectate()
    if not _phys.isSpectating or not _phys.targetPlayer then return end
    local c=_phys.targetPlayer.Character
    local h=c and c:FindFirstChildOfClass("Humanoid")
    local cam=workspace.CurrentCamera
    if h and cam then pcall(function()
        if cam.CameraSubject~=h then cam.CameraSubject=h end
        cam.CameraType=Enum.CameraType.Custom
    end) end
end
local function _PhysStopSpectate()
    local mc=LocalPlayer.Character
    local mh=mc and mc:FindFirstChildOfClass("Humanoid")
    local cam=workspace.CurrentCamera
    pcall(function()
        if cam then cam.CameraType=Enum.CameraType.Custom if mh then cam.CameraSubject=mh end end
    end)
    _phys.isSpectating=false
end
local function _PhysSendRe()
    pcall(function()
        local h=LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
        game:GetService("Chat"):Chat(h,"!re",Enum.ChatColor.Green)
    end)
    pcall(function() game:GetService("TextChatService").TextChannels.RBXGeneral:SendAsync("!re") end)
end
local function BuildPhysicsTab()
    local tab = CreatedTabs and CreatedTabs["Physics"]
    if not tab or not tab.CreateSection then return end
    if not _phys.logicInit then
        _phys.logicInit = true
        if not getgenv().JEYHUB_PHYSNET then
            getgenv().JEYHUB_PHYSNET = true
            local _nf = 0
            SafeConnect(GetSignal(RunService,"Heartbeat"),function()
                _nf=_nf+1
                if _nf%30==0 then pcall(function() sethiddenproperty(LocalPlayer,"SimulationRadius",math.huge) end) end
            end)
        end
        SafeConnect(GetSignal(workspace,"DescendantAdded"),function(obj)
            task.defer(function()
                task.wait(0.02)
                pcall(_PhysClaimObj,obj)
            end)
        end)
        local _hbFrame=0
        SafeConnect(GetSignal(RunService,"Heartbeat"),function(dt)
            _hbFrame=_hbFrame+1
            _phys.spectateFrame=_phys.spectateFrame+1
            if _phys.spectateFrame%6==0 then pcall(_PhysEnforceSpectate) end
            local rawPing=0.05
            pcall(function()
                rawPing=LocalPlayer:GetNetworkPing()
                if rawPing<=0 or rawPing~=rawPing then rawPing=0.05 end
            end)
            rawPing=math.clamp(rawPing,0.01,2.0)
            local prev=_phys.emaPing
            _phys.emaPing=_phys.emaPing*0.85+rawPing*0.15
            _phys.emaJitter=_phys.emaJitter*0.90+math.abs(rawPing-prev)*0.10
            local tp=_phys.targetPlayer
            if tp then
                local char=tp.Character
                local hum=char and char:FindFirstChildOfClass("Humanoid")
                if char and char~=_phys.targetTracker.Character then
                    if _phys.targetTracker.Character~=nil then
                        ShowNotification("Physics","Target respawned: "..(tp.DisplayName or tp.Name),2.5)
                    end
                    _phys.targetTracker.Character=char
                    _phys.targetTracker.IsDead=false
                    _phys.targetTracker.WasSitting=false
                end
                if hum and hum.Health>0 then
                    if hum.Sit and not _phys.targetTracker.WasSitting then
                        ShowNotification("Physics","Target is sitting!",2)
                        _phys.targetTracker.WasSitting=true
                    elseif not hum.Sit then _phys.targetTracker.WasSitting=false end
                end
                if _phys.targetTracker.Character and _phys.physicsActive then
                    if not char or not char.Parent or (hum and hum.Health<=0) then
                        if not _phys.targetTracker.IsDead then
                            ShowNotification("Physics","Target died/disappeared",2)
                            _phys.targetTracker.IsDead=true
                        end
                    end
                end
            else
                _phys.targetTracker.Character=nil
                _phys.targetTracker.IsDead=false
                _phys.targetTracker.WasSitting=false
            end
            if not _phys.physicsActive and not _phys.aegisActive then return end
            local lchar=LocalPlayer.Character
            local myHrp=lchar and lchar:FindFirstChild("HumanoidRootPart")
            local myHum=lchar and lchar:FindFirstChildOfClass("Humanoid")
            if _phys.aegisActive and myHrp and myHum then
                if myHrp.AssemblyLinearVelocity.Magnitude>250 then
                    myHrp.AssemblyLinearVelocity=Vector3.new(0,myHrp.AssemblyLinearVelocity.Y,0)
                    myHrp.AssemblyAngularVelocity=Vector3.zero
                end
                local st=myHum:GetState()
                if st==Enum.HumanoidStateType.Ragdoll or st==Enum.HumanoidStateType.FallingDown then
                    myHum:ChangeState(Enum.HumanoidStateType.GettingUp)
                end
                myHum.PlatformStand=false
            end
            if _hbFrame%30==0 and sethiddenproperty then
                pcall(function() sethiddenproperty(LocalPlayer,"SimulationRadius",math.huge) end)
                pcall(function() sethiddenproperty(LocalPlayer,"MaximumSimulationRadius",math.huge) end)
            end
            local hasTarget = tp and tp.Character
                and tp.Character:FindFirstChild("Humanoid")
                and tp.Character.Humanoid.Health > 0
            for obj, _ in pairs(_phys.myPhysicsObjects) do
                if obj and obj.Parent then
                    pcall(function()
                        if _hbFrame % 20 == 0 and sethiddenproperty then
                            sethiddenproperty(obj, "NetworkOwnership", LocalPlayer)
                            sethiddenproperty(obj, "NetworkIsSleeping", false)
                            pcall(function() obj:SetNetworkOwner(LocalPlayer) end)
                        end
                        local isOwned = true
                        if type(isnetworkowner) == "function" then
                            isOwned = isnetworkowner(obj)
                        end
                        if isOwned and myHrp then
                            obj.Anchored   = false
                            obj.CanCollide = false
                            obj.Massless   = true
                            obj.CanQuery   = false
                            obj.CustomPhysicalProperties = PhysicalProperties.new(math.huge, math.huge, 0, 100, 0)
                            if sethiddenproperty then
                                pcall(function() sethiddenproperty(obj, "NetworkIsSleeping", false) end)
                            end
                            if not (_phys.physicsActive and hasTarget) then
                                if _phys.aegisActive then
                                    obj.Massless      = true
                                    obj.CanCollide    = false
                                    obj.CanQuery      = false
                                    obj.CFrame        = CFrame.new(myHrp.Position.X, myHrp.Position.Y - 10, myHrp.Position.Z)
                                    obj.AssemblyLinearVelocity  = Vector3.zero
                                    obj.AssemblyAngularVelocity = Vector3.zero
                                end
                            end
                            if obj.Position.Y < _phys.VOID_SAFE or (obj.Position - myHrp.Position).Magnitude > _phys.AURA_RAD + 100 then
                                obj.CFrame = CFrame.new(myHrp.Position.X, _phys.VOID_SAFE + 25, myHrp.Position.Z)
                                obj.AssemblyLinearVelocity = Vector3.zero
                            end
                        end
                    end)
                else _phys.myPhysicsObjects[obj] = nil end
            end
            if _hbFrame % 20 == 0 and myHrp then
                local scanR  = _phys.aegisActive and 150 or 10
                local scanOp = OverlapParams.new()
                scanOp.FilterDescendantsInstances = {lchar}
                scanOp.FilterType = Enum.RaycastFilterType.Exclude
                for _, obj in ipairs(workspace:GetPartBoundsInRadius(myHrp.Position, scanR, scanOp)) do
                    if _phys.isObject(obj) and not _phys.myPhysicsObjects[obj] then
                        pcall(_PhysClaimObj, obj)
                    end
                end
            end
            if not (_phys.physicsActive and tp and tp.Character) then return end
            local targ        = tp
            local activeObjects = {}
            for b, _ in pairs(_phys.myPhysicsObjects) do
                if b and b.Parent then
                    local isOwned = true
                    if type(isnetworkowner) == "function" then isOwned = isnetworkowner(b) end
                    if isOwned then table.insert(activeObjects, b) end
                end
            end
            local validAoe = {}
            local crowdedT = {}
            if _phys.areaMode > 0 and targ.Character and targ.Character:FindFirstChild("HumanoidRootPart") then
                local tPos = _PhysGetTargetPos(targ.Character) or targ.Character.HumanoidRootPart.Position
                local alive = {}
                for _, plr in ipairs(Players:GetPlayers()) do
                    if plr ~= LocalPlayer and not _phys.excludedPlayers[plr.Name]
                    and plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") then
                        local ph = plr.Character:FindFirstChild("Humanoid")
                        if ph and ph.Health > 0 then
                            local sitting = ph.SeatPart and _phys.isSeatName(string.lower(ph.SeatPart.Name)) or false
                            if not (_phys.ignoreSit and sitting) then
                                table.insert(alive, plr)
                                if plr ~= targ then
                                    table.insert(validAoe, {Player=plr, Distance=(plr.Character.HumanoidRootPart.Position - tPos).Magnitude})
                                end
                            end
                        end
                    end
                end
                table.sort(validAoe, function(a, b) return a.Distance < b.Distance end)
                if _phys.areaMode == 4 then
                    _phys.crowdFrame = _phys.crowdFrame + 1
                    if _phys.crowdFrame % 12 == 0 then
                        _phys.cachedCrowded = {}
                        for _, pa in ipairs(alive) do
                            local posA = pa.Character.HumanoidRootPart.Position
                            for _, pb in ipairs(alive) do
                                if pa ~= pb and (posA - pb.Character.HumanoidRootPart.Position).Magnitude <= 45 then
                                    _phys.cachedCrowded[#_phys.cachedCrowded+1] = pa
                                    break
                                end
                            end
                        end
                    end
                    crowdedT = _phys.cachedCrowded
                end
            end
            for bi, obj in ipairs(activeObjects) do
                if targ and targ.Character and targ.Character:FindFirstChild("HumanoidRootPart") then
                    pcall(function()
                        local ec  = targ.Character
                        local hrp = ec:FindFirstChild("HumanoidRootPart")
                        if not hrp then return end
                        obj.CanCollide = true
                        obj.Massless   = false
                        obj.CustomPhysicalProperties = PhysicalProperties.new(math.huge, 0, math.huge, 0, math.huge)
                        if _phys.areaMode > 0 then
                            local areaR    = (_phys.areaMode == 5) and 999999 or 50
                            local assigned = nil
                            if _phys.areaMode == 5 then
                                assigned = (not _phys.excludedPlayers[targ.Name]) and targ
                                    or (#validAoe > 0 and validAoe[1].Player or nil)
                            elseif _phys.areaMode == 4 and #validAoe > 0 then
                                if not _phys.targetTracker.ApocTarget then
                                    _phys.targetTracker.ApocTarget = nil
                                    _phys.targetTracker.ApocTime = tick()
                                end
                                local mc2 = nil
                                for _, p in ipairs(#crowdedT > 0 and crowdedT or validAoe) do
                                    local pp = (type(p) == "table") and p.Player or p
                                    if pp ~= _phys.targetTracker.ApocTarget and pp.Character
                                    and pp.Character:FindFirstChild("HumanoidRootPart") then mc2 = pp
                                    break end
                                end
                                if mc2 then _phys.targetTracker.ApocTarget = mc2
                                _phys.targetTracker.ApocTime = tick() end
                                assigned = _phys.targetTracker.ApocTarget or (validAoe[1] and validAoe[1].Player)
                            elseif _phys.areaMode == 3 and #validAoe > 0 then
                                assigned = validAoe[((bi-1) % #validAoe) + 1].Player
                            elseif _phys.areaMode == 1 or _phys.areaMode == 2 then
                                local inR = {}
                                for _, v in ipairs(validAoe) do
                                    if v.Distance <= areaR then table.insert(inR, v.Player) end
                                end
                                if #inR > 0 then assigned = inR[((bi-1) % #inR) + 1] end
                            end
                            if assigned and assigned.Character and assigned.Character:FindFirstChild("HumanoidRootPart") then
                                local f = _PhysMakeFling(assigned.Character.HumanoidRootPart.Position, myHrp)
                                _PhysClearObstacles(assigned.Character.HumanoidRootPart.Position, 7, {assigned.Character, lchar, obj})
                                _PhysApplyFling(obj, f, assigned.Character)
                            end
                            if _phys.areaMode == 2 and not _phys.excludedPlayers[targ.Name] then
                                local th2 = ec:FindFirstChild("Humanoid")
                                local sit2 = th2 and th2.SeatPart and _phys.isSeatName(string.lower(th2.SeatPart.Name)) or false
                                if not (_phys.ignoreSit and sit2) then
                                    local f2 = _PhysMakeFling(hrp.Position, myHrp)
                                    _PhysApplyFling(obj, f2, ec)
                                end
                            end
                        elseif not _phys.excludedPlayers[targ.Name] then
                            local th3  = ec:FindFirstChild("Humanoid")
                            local sit3 = th3 and th3.SeatPart and _phys.isSeatName(string.lower(th3.SeatPart.Name)) or false
                            if not (_phys.ignoreSit and sit3) then
                                local f = _PhysMakeFling(hrp.Position, myHrp)
                                _PhysClearObstacles(hrp.Position, 7, {ec, lchar, obj})
                                _PhysApplyFling(obj, f, ec)
                            end
                        end
                    end)
                end
            end
            for b, _ in pairs(_phys.myPhysicsObjects) do
                if not b or not b.Parent then _phys.myPhysicsObjects[b] = nil end
            end
        end)
        SafeConnect(GetSignal(RunService,"Stepped"),function()
            local lchar=LocalPlayer.Character
            local hum=lchar and lchar:FindFirstChildOfClass("Humanoid")
            local root=lchar and lchar:FindFirstChild("HumanoidRootPart")
            if _phys.aegisAntiFling and root then
                if root.AssemblyLinearVelocity.Magnitude>300 or root.AssemblyAngularVelocity.Magnitude>300 then
                    root.AssemblyLinearVelocity=Vector3.new(0,root.AssemblyLinearVelocity.Y,0)
                    root.AssemblyAngularVelocity=Vector3.zero
                end
            end
            if _phys.aegisAntiRagdoll and hum then
                hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll,false)
                hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown,false)
                hum.PlatformStand=false
                local st=hum:GetState()
                if st==Enum.HumanoidStateType.Ragdoll or st==Enum.HumanoidStateType.FallingDown or st==Enum.HumanoidStateType.Physics then
                    hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                end
            end
            if _phys.aegisActive then
                if not lchar or not hum or not root then return end
                if not _G.JHPhysAuraTick or (os.clock()-_G.JHPhysAuraTick)>0.33 then
                    _G.JHPhysAuraTick=os.clock()
                    local op=OverlapParams.new()
                    op.FilterDescendantsInstances={lchar}
                    op.FilterType=Enum.RaycastFilterType.Exclude
                    for _,obj in ipairs(workspace:GetPartBoundsInRadius(root.Position,150,op)) do
                        if _phys.isObject(obj) and not _phys.myPhysicsObjects[obj] then pcall(_PhysClaimObj,obj) end
                    end
                end
            end
        end)
        SafeConnect(GetSignal(RunService, "Heartbeat"), function()
            if not _phys.multiHit then return end
            if not firetouchinterest then return end
            local tp = _phys.targetPlayer
            if not tp or not tp.Character then return end
            local tc  = tp.Character
            local tr  = tc:FindFirstChild("HumanoidRootPart")
            local th  = tc:FindFirstChildOfClass("Humanoid")
            if not tr or not th or th.Health <= 0 then return end
            local lchar  = LocalPlayer.Character
            local myHrpM = lchar and lchar:FindFirstChild("HumanoidRootPart")
            local outDirM = Vector3.new(0, 0, 1)
            if myHrpM then
                local _dm = tr.Position - myHrpM.Position
                if _dm.Magnitude > 0.1 then outDirM = _dm.Unit end
            end
            local mhForce = 4e12
            local mhFv    = Vector3.new(outDirM.X * mhForce, mhForce, outDirM.Z * mhForce)
            pcall(function()
                th:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, true)
                th:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
                th.PlatformStand = true
                th:ChangeState(Enum.HumanoidStateType.Ragdoll)
            end)
            pcall(function() tr.AssemblyLinearVelocity = mhFv end)
            local allParts = {}
            for _, _p in ipairs(tc:GetDescendants()) do
                if _p:IsA("BasePart") then table.insert(allParts, _p) end
            end
            for obj, _ in pairs(_phys.myPhysicsObjects) do
                if obj and obj.Parent then
                    pcall(function()
                        obj.CFrame                  = CFrame.new(tr.Position)
                        obj.CanCollide              = true
                        obj.Massless                = false
                        obj.CustomPhysicalProperties = PhysicalProperties.new(math.huge, 0, math.huge, 0, math.huge)
                        obj.AssemblyLinearVelocity  = mhFv
                        obj.AssemblyAngularVelocity = mhFv
                        for _ = 1, _phys.MULTI_HIT_N do
                            for _, part in ipairs(allParts) do
                                firetouchinterest(obj, part, 0)
                                firetouchinterest(obj, part, 1)
                            end
                        end
                        task.defer(function()
                            if not (obj and obj.Parent and tc) then return end
                            local freshHrp = tc:FindFirstChild("HumanoidRootPart")
                            if not freshHrp then return end
                            obj.CFrame                  = CFrame.new(freshHrp.Position)
                            obj.AssemblyLinearVelocity  = mhFv
                            obj.AssemblyAngularVelocity = mhFv
                            for _, part in ipairs(allParts) do
                                firetouchinterest(obj, part, 0)
                                firetouchinterest(obj, part, 1)
                            end
                            pcall(function() freshHrp.AssemblyLinearVelocity = mhFv end)
                        end)
                    end)
                end
            end
        end)
        local eok = pcall(function() return Drawing and Drawing.new("Square") end)
