            drw.Box.Filled = false
            drw.BoxOutline.Thickness  = 1.5
            drw.BoxOutline.Filled = false
            drw.BoxOutline.Color      = Color3.new(0, 0, 0)
            drw.Name.Size             = 11
            drw.Name.Center = true
            drw.Name.Outline = true
            drw.Name.Font = 2
            drw.Distance.Size         = 10
            drw.Distance.Center = true
            drw.Distance.Outline = true
            drw.Distance.Font = 2
            drw.Distance.Color        = Color3.fromRGB(166, 166, 166)
            drw.HealthOutline.Filled  = true
            drw.HealthOutline.Color = Color3.fromRGB(4, 4, 4)
            drw.HealthOutline.Transparency = 0.2
            drw.HealthBar.Filled      = true
            drw.HealthText.Size       = 9
            drw.HealthText.Center = false
            drw.HealthText.Outline = true
            drw.HealthText.Color      = Color3.fromRGB(254, 254, 254)
            drw.HealthText.Font = 2
            drw.Tracer.Thickness      = 1
            drw.Tracer.Transparency = 0.65
            local charmOk, singleCharm = pcall(function()
                local h = Instance.new("Highlight")
                h.FillTransparency    = 0.35
                h.OutlineTransparency = 0.1
                h.DepthMode           = Enum.HighlightDepthMode.AlwaysOnTop
                h.Parent = game:GetService("CoreGui")
                return h
            end)
            drw.Charm = charmOk and singleCharm or nil
            drw.WeaponCharm = nil
            _phys.ESPDrawings = drw
            local function _hideAllDrawings()
                drw.BoxFill.Visible    = false
                drw.Box.Visible = false
                drw.BoxOutline.Visible = false
                drw.Name.Visible       = false
                drw.Distance.Visible = false
                drw.HealthBar.Visible  = false
                drw.HealthOutline.Visible = false
                drw.HealthText.Visible = false
                drw.Tracer.Visible     = false
                for _, ln in ipairs(drw.SkeletonList) do ln.Visible = false end
                if drw.Charm       then drw.Charm.Enabled = false
                drw.Charm.Parent = game:GetService("CoreGui") end
                if drw.WeaponCharm then drw.WeaponCharm.Enabled = false end
            end
            SafeConnect(GetSignal(RunService, "RenderStepped"), function()
                if not _phys.ESPEnabled then _hideAllDrawings()
                return end
                local tp = _phys.targetPlayer
                if not tp or not tp.Character then _hideAllDrawings()
                return end
                local char = tp.Character
                local hrp  = char:FindFirstChild("HumanoidRootPart")
                local hum  = char:FindFirstChildOfClass("Humanoid")
                local head = char:FindFirstChild("Head") or hrp
                if not hrp or not hum or hum.Health <= 0 then _hideAllDrawings()
                return end
                local cam = workspace.CurrentCamera
                local pos, onScreen = cam:WorldToViewportPoint(hrp.Position)
                if not onScreen then _hideAllDrawings()
                return end
                local gc = SE.ESPColor
                local headPos = cam:WorldToViewportPoint(head.Position + Vector3.new(0, 0.6, 0))
                local footOffset = (hum.HipHeight or 2.0) + 1.35
                local legPos  = cam:WorldToViewportPoint(hrp.Position - Vector3.new(0, footOffset, 0))
                local height  = math.abs(headPos.Y - legPos.Y)
                local rightW  = hrp.CFrame * Vector3.new(0.6, 0, 0)
                local rightS  = cam:WorldToViewportPoint(rightW)
                local width   = math.max(math.abs(rightS.X - pos.X) * 2, height * 0.4)
                if SE.Box then
                    local fillSz = Vector2.new(width, height)
                    local fillPs = Vector2.new(pos.X - width/2, headPos.Y)
                    drw.BoxFill.Size     = fillSz
                    drw.BoxFill.Position = fillPs
                    drw.BoxFill.Color    = gc
                    drw.BoxFill.Transparency = 0.88
                    drw.BoxFill.Visible  = true
                    drw.Box.Size         = fillSz
                    drw.Box.Position = fillPs
                    drw.Box.Color        = gc
                    drw.Box.Visible = true
                    drw.BoxOutline.Size     = drw.Box.Size
                    drw.BoxOutline.Position = drw.Box.Position
                    drw.BoxOutline.Visible  = true
                else
                    drw.BoxFill.Visible = false
                    drw.Box.Visible = false
                    drw.BoxOutline.Visible = false
                end
                if SE.Name then
                    if tp ~= _phys.lastEspTarget then
                        _phys.lastEspTarget  = tp
                        _phys.cachedEspName  = (tp.DisplayName ~= tp.Name)
                            and (tp.DisplayName .. "  @" .. tp.Name) or tp.DisplayName
                    end
                    drw.Name.Text     = _phys.cachedEspName
                    drw.Name.Position = Vector2.new(pos.X, headPos.Y - 14)
                    drw.Name.Color    = gc
                    drw.Name.Visible = true
                else
                    drw.Name.Visible = false
                end
                if SE.Distance then
                    local dist = (cam.CFrame.Position - hrp.Position).Magnitude
                    drw.Distance.Text     = math.floor(dist) .. "m"
                    drw.Distance.Position = Vector2.new(pos.X, headPos.Y + height + 2)
                    drw.Distance.Visible  = true
                else
                    drw.Distance.Visible = false
                end
                if SE.Health then
                    local tH  = hum.Health
                    local mH = hum.MaxHealth
                    _phys.CurrentHealth = _phys.CurrentHealth + (tH - _phys.CurrentHealth) * 0.12
                    local ratio = math.clamp(_phys.CurrentHealth / mH, 0, 1)
                    local r  = math.clamp(2 - ratio * 2, 0, 1)
                    local g  = math.clamp(ratio * 2, 0, 1)
                    local hc = Color3.new(r, g, 0)
                    local bw = 4
                    local ot = 1
                    local bx = pos.X - width/2 - bw - 4 - ot
                    drw.HealthOutline.Size     = Vector2.new(bw + ot*2, height + ot*2)
                    drw.HealthOutline.Position = Vector2.new(bx - ot, headPos.Y - ot)
                    drw.HealthOutline.Visible  = true
                    local bh = math.max(height * ratio, 1)
                    drw.HealthBar.Size     = Vector2.new(bw, bh)
                    drw.HealthBar.Position = Vector2.new(bx, headPos.Y + height - bh)
                    drw.HealthBar.Color    = hc
                    drw.HealthBar.Visible = true
                    drw.HealthText.Text        = tostring(math.floor(_phys.CurrentHealth))
                    drw.HealthText.Position    = Vector2.new(bx - 1, drw.HealthBar.Position.Y - 10)
                    drw.HealthText.Transparency = ratio > 0.98 and 0.6 or 0
                    drw.HealthText.Visible     = true
                else
                    drw.HealthBar.Visible = false
                    drw.HealthOutline.Visible = false
                    drw.HealthText.Visible = false
                end
                if SE.Tracers then
                    local vp = cam.ViewportSize
                    drw.Tracer.From    = Vector2.new(vp.X * 0.5, vp.Y * 0.96)
                    drw.Tracer.To      = Vector2.new(pos.X, legPos.Y)
                    drw.Tracer.Color   = gc
                    drw.Tracer.Visible = true
                else
                    drw.Tracer.Visible = false
                end
                if SE.Skeleton then
                    for i, joint in ipairs(SKEL_BONES) do
                        local p1 = char:FindFirstChild(joint[1])
                        local p2 = char:FindFirstChild(joint[2])
                        if p1 and p2 then
                            local s1, v1 = cam:WorldToViewportPoint(p1.Position)
                            local s2, v2 = cam:WorldToViewportPoint(p2.Position)
                            if v1 or v2 then
                                drw.SkeletonList[i].From    = Vector2.new(s1.X, s1.Y)
                                drw.SkeletonList[i].To      = Vector2.new(s2.X, s2.Y)
                                drw.SkeletonList[i].Color   = gc
                                drw.SkeletonList[i].Visible = true
                            else
                                drw.SkeletonList[i].Visible = false
                            end
                        else
                            drw.SkeletonList[i].Visible = false
                        end
                    end
                else
                    for _, ln in ipairs(drw.SkeletonList) do ln.Visible = false end
                end
                if SE.Charms then
                    if drw.Charm then
                        if drw.Charm.Parent ~= char then drw.Charm.Parent = char end
                        drw.Charm.FillColor    = gc
                        drw.Charm.OutlineColor = gc
                        drw.Charm.Enabled      = true
                    end
                else
                    if drw.Charm then drw.Charm.Enabled = false end
                end
                if SE.CharmsWeapon then
                    local tool = char:FindFirstChildOfClass("Tool")
                    if tool then
                        if not drw.WeaponCharm then
                            drw.WeaponCharm = Instance.new("Highlight")
                            drw.WeaponCharm.FillTransparency    = 0.35
                            drw.WeaponCharm.OutlineTransparency = 0.1
                            drw.WeaponCharm.DepthMode           = Enum.HighlightDepthMode.AlwaysOnTop
                        end
                        if drw.WeaponCharm.Parent ~= tool then drw.WeaponCharm.Parent = tool end
                        drw.WeaponCharm.FillColor    = gc
                        drw.WeaponCharm.OutlineColor = gc
                        drw.WeaponCharm.Enabled      = true
                    else
                        if drw.WeaponCharm then drw.WeaponCharm.Enabled = false end
                    end
                else
                    if drw.WeaponCharm then drw.WeaponCharm.Enabled = false end
                end
            end)
        end
        local function _onToolEquipped(child)
            if _phys.ghostThrow and child:IsA("Tool") then
                task.defer(function()
                    if child.Parent==LocalPlayer.Character then
                        child:Activate()
                        local h2=LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
                        if h2 then h2:UnequipTools() end
                    end
                end)
            end
        end
        if LocalPlayer.Character then SafeConnect(GetSignal(LocalPlayer.Character,"ChildAdded"),_onToolEquipped) end
        SafeConnect(GetSignal(LocalPlayer,"CharacterAdded"),function(nc)
            SafeConnect(GetSignal(nc,"ChildAdded"),_onToolEquipped)
        end)
