    local function _BH_SpawnVisual(pos)
        if _phys.blackhole_visual and _phys.blackhole_visual.Parent then
            pcall(function() _phys.blackhole_visual.Position = pos end)
            return
        end
        local v = Instance.new("Part")
        v.Name             = "_JeyBH_Visual"
        v.Shape            = Enum.PartType.Ball
        v.Size             = Vector3.new(4, 4, 4)
        v.Anchored         = true
        v.CanCollide       = false
        v.CanTouch         = false
        v.CastShadow       = false
        v.Color            = Color3.fromRGB(0, 0, 0)
        v.Transparency     = 0.15
        v.Material         = Enum.Material.Neon
        v.Position         = pos
        local sg = Instance.new("SelectionSphere")
        sg.SurfaceTransparency = 0.7
        sg.SurfaceColor3       = Color3.fromRGB(80, 0, 180)
        sg.Adornee             = v
        sg.Parent              = v
        v.Parent               = workspace
        _phys.blackhole_visual = v
    end
    local function _BH_RemoveVisual()
        if _phys.blackhole_visual then
            pcall(function() _phys.blackhole_visual:Destroy() end)
            _phys.blackhole_visual = nil
        end
    end
    local function _BH_SetPosition(pos)
        _phys.blackholePosition = pos
        if _phys.blackholeActive then
            _BH_SpawnVisual(pos)
        end
    end
    SafeConnect(GetSignal(RunService, "Heartbeat"), function(dt)
        if not _phys.blackholeActive then return end
        local lchar = LocalPlayer.Character
        local myHrp = lchar and lchar:FindFirstChild("HumanoidRootPart")
        if not myHrp then return end
        _phys.blackhole_frame = _phys.blackhole_frame + 1
        local fr = _phys.blackhole_frame
        if _phys.blackholeFollowMode == "player" then
            _phys.blackholePosition = myHrp.Position
        elseif _phys.blackholeFollowMode == "look" and fr % 10 == 0 then
            local cam = workspace.CurrentCamera
            if cam then
                local origin = cam.CFrame.Position
                local direction = cam.CFrame.LookVector * (_phys.blackholeRadius * 1.5)
                local rp = RaycastParams.new()
                rp.FilterDescendantsInstances = {lchar}
                rp.FilterType = Enum.RaycastFilterType.Exclude
                local hit = workspace:Raycast(origin, direction, rp)
                if hit then
                    _phys.blackholePosition = hit.Position
                end
            end
        end
        local bhPos  = _phys.blackholePosition
        local radius = _phys.blackholeRadius
        local force  = _phys.blackholePullForce
        local dDist  = _phys.blackholeDestroyDist
        local doOwn  = (fr % 12 == 0)
        local doApply = (fr % 3  == 0)
        if _phys.blackhole_visual and _phys.blackhole_visual.Parent then
            pcall(function() _phys.blackhole_visual.Position = bhPos end)
        end
        local op = OverlapParams.new()
        op.FilterDescendantsInstances = {lchar}
        op.FilterType = Enum.RaycastFilterType.Exclude
        local parts = workspace:GetPartBoundsInRadius(bhPos, radius, op)
        for _, obj in ipairs(parts) do
            if not obj or not obj.Parent then continue end
            if obj.Anchored then continue end
            if obj == _phys.blackhole_visual then continue end
            local skipObj = false
            local pp = obj.Parent
            while pp do
                if pp:IsA("Backpack") or pp:IsA("Accessory") then skipObj = true
                break end
                if not _phys.blackholeAffectPlayers
                   and pp:IsA("Model") and pp:FindFirstChildOfClass("Humanoid") then
                    skipObj = true
                    break
                end
                pp = pp.Parent
            end
            if skipObj then continue end
            pcall(function()
                if doOwn then
                    if _phys.blackholeAutoRestore and not _phys.bh_savedState[obj] then
                        _phys.bh_savedState[obj] = {
                            cframe     = obj.CFrame,
                            anchored   = obj.Anchored,
                            canCollide = obj.CanCollide,
                        }
                    end
                    if sethiddenproperty then
                        sethiddenproperty(obj, "NetworkOwnership", LocalPlayer)
                        sethiddenproperty(obj, "NetworkIsSleeping", false)
                    end
                    pcall(function() obj:SetNetworkOwner(LocalPlayer) end)
                    obj.Anchored   = false
                    obj.CanCollide = false
                end
                local diff = bhPos - obj.Position
                local dist = diff.Magnitude
                if dist < 0.1 then return end
                if dist < dDist then
                    if _phys.blackholeBreakWelds then
                        pcall(function()
                            local par = obj.Parent
                            if par then
                                for _, w in ipairs(par:GetChildren()) do
                                    if (w:IsA("WeldConstraint") or w:IsA("Weld") or w:IsA("Motor6D"))
                                       and (w.Part0 == obj or w.Part1 == obj) then
                                        w:Destroy()
                                    end
                                end
                            end
                            for _, w in ipairs(obj:GetChildren()) do
                                if w:IsA("WeldConstraint") or w:IsA("Weld") or w:IsA("Motor6D") then
                                    w:Destroy()
                                end
                            end
                        end)
                    end
                    if _phys.blackholeDestroyParts then
                        pcall(function() obj:Destroy() end)
                        _phys.blackhole_claimed[obj] = nil
                        _phys.blackhole_frozen[obj]  = nil
                        return
                    end
                    if _phys.blackholeFreezeAtCore then
                        _phys.blackhole_frozen[obj] = true
                        obj.AssemblyLinearVelocity  = Vector3.zero
                        obj.AssemblyAngularVelocity = Vector3.zero
                        obj.Anchored   = true
                        obj.CanCollide = false
                        obj.Position   = bhPos + Vector3.new(
                            (math.random() - 0.5) * dDist * 0.4,
                            (math.random() - 0.5) * dDist * 0.4,
                            (math.random() - 0.5) * dDist * 0.4
                        )
                        return
                    end
                    return
                end
                if not doApply then return end
                local gravity = force * (radius / math.max(dist, 1))
                local dirIn   = diff.Unit
                local angMult = _phys.blackholeSpinParts and 1 or 0
                obj.AssemblyLinearVelocity = dirIn * gravity
                obj.AssemblyAngularVelocity = Vector3.new(
                    (math.random()*2-1) * gravity * angMult * 0.4,
                    (math.random()*2-1) * gravity * angMult * 0.4,
                    (math.random()*2-1) * gravity * angMult * 0.4
                )
                _phys.blackhole_claimed[obj] = true
            end)
        end
        if _phys.blackholeAffectPlayers and doApply then
            for _, plr in ipairs(Players:GetPlayers()) do
                if plr == LocalPlayer then continue end
                local pchar = plr.Character
                local phrp  = pchar and pchar:FindFirstChild("HumanoidRootPart")
                if not phrp then continue end
                local diff = bhPos - phrp.Position
                local dist = diff.Magnitude
                if dist > radius or dist < 0.1 then continue end
                pcall(function()
                    if sethiddenproperty then
                        sethiddenproperty(phrp, "NetworkOwnership", LocalPlayer)
                    end
                    pcall(function() phrp:SetNetworkOwner(LocalPlayer) end)
                    local gravity = force * (radius / math.max(dist, 1))
                    phrp.AssemblyLinearVelocity = diff.Unit * gravity
                end)
            end
        end
        if fr % 90 == 0 then
            for obj, _ in pairs(_phys.blackhole_claimed) do
                if not obj or not obj.Parent then _phys.blackhole_claimed[obj] = nil end
            end
        end
    end)
    local bhSec = tab:CreateSection("Blackhole", "Singularitas gravitasi \226\128\148 tarik semua part & player ke satu titik")
