local function BuildServerFinderTab()
    local tab = CreatedTabs and CreatedTabs["Server Finder"]
    if not tab or not tab.CreateSection then return end
    local accent      = TabAccents["Server Finder"] or Palette.Accent
    local TeleportSvc = SafeService("TeleportService")
    local RunSvc      = SafeService("RunService")
    local sfServers   = {}
    local sfRawPool   = {}
    local sfScanning  = false
    local sfScanToken = 0
    local sfSort      = "Asc"
    local sfCursor    = nil
    local sfAllLoaded = false
    local sfPage      = 0
    local rowN        = 0
    local fMinPlayers = 0
    local fMaxPlayers = 9999
    local fMinSlots   = 1
    local fMaxSlots   = 9999
    local fKeyword    = ""
    local fHideEmpty  = false
    local fHideFull   = true
    local function sfFetch(url)
        local body, pingMs
        local t0 = tick()
        pcall(function()
            if typeof(syn) == "table" and typeof(syn.request) == "function" then
                body = syn.request({ Url = url, Method = "GET" }).Body
            elseif typeof(http_request) == "function" then
                body = http_request({ Url = url, Method = "GET" }).Body
            elseif typeof(http) == "table" and typeof(http.request) == "function" then
                local res = http.request({ Url = url, Method = "GET" })
                body = res.Body or res.body
            elseif typeof(fluxus) == "table" and typeof(fluxus.request) == "function" then
                body = fluxus.request({ Url = url, Method = "GET" }).Body
            elseif typeof(request) == "function" then
                body = request({ Url = url, Method = "GET" }).Body
            else
                body = game:HttpGet(url)
            end
        end)
        pingMs = math.floor((tick() - t0) * 1000)
        return body, pingMs
    end
    local function passFilter(s)
        local slots = (s.maxPlayers or 0) - (s.playing or 0)
        if fHideFull  and slots <= 0 then return false end
        if fHideEmpty and s.playing <= 0 then return false end
        if s.playing < fMinPlayers then return false end
        if s.playing > fMaxPlayers then return false end
        if slots < fMinSlots then return false end
        if slots > fMaxSlots then return false end
        if fKeyword ~= "" then
            local id = tostring(s.id or "")
            if not id:lower():find(fKeyword:lower(), 1, true) then return false end
        end
        return true
    end
