        if #sfServers == 0 then
            summaryLabel.Text = "Avg: --  |  Total Players: --  |  Total Slots: --"
            return
        end
        local totalPlayers, totalSlots = 0, 0
        for _, s in ipairs(sfServers) do
            totalPlayers = totalPlayers + (s.playing or 0)
            totalSlots   = totalSlots   + ((s.maxPlayers or 0) - (s.playing or 0))
        end
        local avg = math.floor(totalPlayers / #sfServers)
        summaryLabel.Text = string.format(
            "Avg: %d/srv  |  Players: %d  |  Free Slots: %d",
            avg, totalPlayers, totalSlots
