        { maxPing = 65,  code = "ID",  bg = Color3.fromRGB(190, 35, 35)  },
        { maxPing = 95,  code = "JP",  bg = Color3.fromRGB(30, 30, 30)   },
        { maxPing = 130, code = "AU",  bg = Color3.fromRGB(0, 80, 160)   },
        { maxPing = 180, code = "US",  bg = Color3.fromRGB(40, 60, 180)  },
        { maxPing = 260, code = "EU",  bg = Color3.fromRGB(20, 40, 160)  },
        { maxPing = 350, code = "BR",  bg = Color3.fromRGB(30, 120, 40)  },
        { maxPing = 999, code = "??",  bg = Color3.fromRGB(32, 32, 32)   },
    }
    local function resolveRegion(ping)
        local p = tonumber(ping) or 999
        for _, r in ipairs(REGION_DATA) do
            if p <= r.maxPing then return r.code, r.bg end
        end
        return "??", Color3.fromRGB(32, 32, 32)
    end
    local function addServerRow(s, idx)
        pcall(function() emptyLabel.Parent = nil end)
        rowN = rowN + 1
        local slots     = math.max(0, (s.maxPlayers or 0) - (s.playing or 0))
        local fillRatio = math.clamp((s.playing or 0) / math.max(s.maxPlayers or 1, 1), 0, 1)
        local srvFPS    = math.floor(tonumber(s.fps)  or 0)
        local srvPing   = math.floor(tonumber(s.ping) or 0)
        local fullId    = tostring(s.id or "N/A")
        local shortId   = #fullId > 11 and (fullId:sub(1, 8) .. _CHR.ELLIPSIS) or fullId
        local regionCode, regionBg = resolveRegion(srvPing)
