            Parent   = joinBtn,
        })
        local jStr = Stroke(joinBtn, Color3.fromRGB(70, 70, 70), 1, 0.45)
        AddButtonHover(joinBtn, jStr, 0.1)
        joinBtn.MouseButton1Click:Connect(function()
            PlayUISound("Click")
            if TeleportSvc and s.id then
                pcall(function()
                    TeleportSvc:TeleportToPlaceInstance(game.PlaceId, s.id, LocalPlayer)
                end)
            end
        end)
        row.MouseEnter:Connect(function()
            Tween(row, 0.1, nil, nil, { BackgroundColor3 = Color3.fromRGB(18, 18, 18), BackgroundTransparency = 0 })
        end)
        row.MouseLeave:Connect(function()
            Tween(row, 0.15, nil, nil, { BackgroundColor3 = Color3.fromRGB(8, 8, 8), BackgroundTransparency = 0.03 })
        end)
