    local function applyFilters()
        for _, c in ipairs(listScroll:GetChildren()) do
            if c:IsA("Frame") and c ~= loadMoreBtn then
                pcall(function() c:Destroy() end)
            end
        end
        sfServers = {}
        rowN      = 0
        pcall(function() emptyLabel.Parent = listScroll end)
        for _, s in ipairs(sfRawPool) do
            if passFilter(s) then
                table.insert(sfServers, s)
                addServerRow(s, #sfServers)
            end
        end
        local n = #sfServers
        listCountLabel.Text = n .. " SERVER" .. (n == 1 and "" or "S") .. " SHOWN"
        if n == 0 then
            pcall(function() emptyLabel.Text = "No servers match the current filters." end)
        end
        loadMoreBtn.Visible = not sfAllLoaded and #sfRawPool > 0
        updateSummary()
    end
    applyBtn.MouseButton1Click:Connect(function()
        PlayUISound("Click")
        if #sfRawPool == 0 then
            statusLabel.Text       = "  [INFO] No data " .. _CHR.EM_DASH .. " press Scan first."
            statusLabel.TextColor3 = Color3.fromRGB(180, 140, 60)
            return
        end
        applyFilters()
        statusLabel.Text       = "  [FILTER] Applied " .. _CHR.EM_DASH .. " " .. #sfServers .. " match."
        statusLabel.TextColor3 = Color3.fromRGB(100, 200, 100)
    end)
    local function fetchPage(myToken, isLoadMore)
        if sfScanToken ~= myToken then return end
        sfPage = sfPage + 1
        pcall(function()
            statusLabel.Text       = "  [SCAN] Page " .. sfPage .. " " .. _CHR.EM_DASH .. " " .. #sfRawPool .. " fetched so far..."
            statusLabel.TextColor3 = Color3.fromRGB(200, 200, 80)
        end)
        local url = "https://games.roblox.com/v1/games/" .. game.PlaceId
            .. "/servers/Public?sortOrder=" .. sfSort .. "&limit=100"
        if sfCursor then url = url .. "&cursor=" .. sfCursor end
        local body, pingMs = sfFetch(url)
        _ = pingMs
        local function finishScan(errMsg)
            sfScanning = false
            pcall(function()
                scanBtn.Text       = "SCAN SERVERS"
                scanBtn.TextColor3 = Color3.fromRGB(10, 10, 10)
                loadMoreBtn.Text       = "LOAD MORE"
                loadMoreBtn.TextColor3 = accent
            end)
            if errMsg then
                statusLabel.Text       = errMsg
                statusLabel.TextColor3 = Color3.fromRGB(200, 70, 70)
            end
        end
        if not body then finishScan("  [ERR] Fetch failed " .. _CHR.EM_DASH .. " check HTTP permissions.")
        return end
        local ok, decoded = pcall(function() return HttpService:JSONDecode(body) end)
        if not ok or not decoded or not decoded.data then finishScan("  [ERR] Parse error " .. _CHR.EM_DASH .. " no server data.")
        return end
        for _, s in ipairs(decoded.data) do
            table.insert(sfRawPool, s)
            if passFilter(s) then
                table.insert(sfServers, s)
                addServerRow(s, #sfServers)
            end
        end
        sfCursor    = decoded.nextPageCursor
        sfAllLoaded = not sfCursor
        local n = #sfServers
        listCountLabel.Text    = n .. " SERVER" .. (n == 1 and "" or "S") .. " SHOWN"
        statusLabel.Text       = "  [DONE] " .. n .. " match from " .. #sfRawPool .. " fetched."
        statusLabel.TextColor3 = Color3.fromRGB(100, 200, 100)
        if sfAllLoaded then
            statusLabel.Text    = "  [DONE] All pages loaded " .. _CHR.EM_DASH .. " " .. n .. " servers match."
            loadMoreBtn.Visible = false
        else
            loadMoreBtn.Visible = true
        end
        updateSummary()
        finishScan()
    end
    scanBtn.MouseButton1Click:Connect(function()
        PlayUISound("Click")
        if sfScanning then return end
        sfScanning  = true
        sfScanToken = sfScanToken + 1
        local myToken = sfScanToken
        scanBtn.Text       = "SCANNING..."
        scanBtn.TextColor3 = Color3.fromRGB(120, 120, 120)
        clearList()
        task.spawn(function()
            fetchPage(myToken, false)
        end)
    end)
    loadMoreBtn.MouseButton1Click:Connect(function()
        PlayUISound("Click")
        if sfScanning or sfAllLoaded then return end
        sfScanning = true
        loadMoreBtn.Text       = "LOADING..."
        loadMoreBtn.TextColor3 = Color3.fromRGB(100, 100, 100)
        local myToken = sfScanToken
        task.spawn(function()
            fetchPage(myToken, true)
            pcall(function()
                loadMoreBtn.Text       = "LOAD MORE"
                loadMoreBtn.TextColor3 = accent
            end)
        end)
    end)
end
BuildTabStaggered("Server Finder", BuildServerFinderTab)
task.wait()
BuildTabStaggered("Execute", BuildExecuteTab)
task.wait()
local function BuildScriptHubTab()
    local tab = CreatedTabs and CreatedTabs["Script Hub"]
    if not tab or not tab.CreateSection then return end
    local accent = TabAccents["Script Hub"] or Palette.Accent
    local sbPage           = 1
    local sbMode           = "trending"
    local sbLoading        = false
    local sbStatusLbl      = nil
    local sbLoadMoreBtn    = nil
    local sbSearchBox      = nil
    local sbGrid           = nil
    local sbScrollFrame    = nil
    local activePill       = "trending"
    local pillFrames       = {}
    local FetchScripts     = nil
    local sbFilterHidePatched = false
    local filterPillFrames    = {}
    local function SetStatus(msg, col)
        pcall(function()
            sbStatusLbl.Text       = "  " .. tostring(msg)
            sbStatusLbl.TextColor3 = col or Color3.fromRGB(78, 78, 78)
        end)
    end
    local function ClearGrid()
        if not sbGrid then return end
        for _, child in ipairs(sbGrid:GetChildren()) do
            if not child:IsA("UIGridLayout") and not child:IsA("UIPadding") then
                pcall(function() child:Destroy() end)
            end
        end
    end
    local function StylePills()
        for key, pf in pairs(pillFrames) do
            local isActive = (activePill == key)
            Tween(pf.bg, 0.15, nil, nil, {
                BackgroundColor3 = isActive and accent or Color3.fromRGB(14, 14, 14),
            })
            Tween(pf.lbl, 0.15, nil, nil, {
                TextColor3 = isActive and Color3.fromRGB(10, 10, 10) or Color3.fromRGB(155, 155, 155),
            })
            Tween(pf.stroke, 0.15, nil, nil, {
                Transparency = isActive and 0.05 or 0.6,
            })
        end
    end
    local function StyleFilterPills()
        for _, pf in pairs(filterPillFrames) do
            local isActive = pf.getState()
            Tween(pf.bg, 0.15, nil, nil, {
                BackgroundColor3 = isActive and accent or Color3.fromRGB(18, 18, 18),
            })
            Tween(pf.lbl, 0.15, nil, nil, {
                TextColor3 = isActive and Color3.fromRGB(10, 10, 10) or Color3.fromRGB(120, 120, 120),
            })
            Tween(pf.stroke, 0.15, nil, nil, {
                Transparency = isActive and 0.05 or 0.7,
            })
        end
    end
    local function MakeBadge(parent, text, bgR, bgG, bgB, txR, txG, txB)
        local bg = New("Frame", {
            Size                   = UDim2.new(0, 0, 0, 13),
            AutomaticSize          = _AutomaticSizeX or Enum.AutomaticSize.X,
            BackgroundColor3       = Color3.fromRGB(bgR, bgG, bgB),
            BackgroundTransparency = 0.15,
            Parent                 = parent,
        })
        Round(bg, 4)
        local lbl = New("TextLabel", {
            Size                   = UDim2.new(0, 0, 1, 0),
            AutomaticSize          = _AutomaticSizeX or Enum.AutomaticSize.X,
            BackgroundTransparency = 1,
            Font                   = Enum.Font.GothamBold,
            Text                   = text,
            TextColor3             = Color3.fromRGB(txR, txG, txB),
            TextSize               = 7,
            Parent                 = bg,
        })
        Pad(lbl, 4, 4, 0, 0)
    end
    local function ExecCode(code, titleStr)
        if not code or code:match("^%s*$") then
            SetStatus("Script kosong " .. _CHR.EM_DASH .. " tidak bisa diexecute", Color3.fromRGB(180, 80, 80))
            return
        end
        SetStatus("Executing: " .. titleStr .. "...", Color3.fromRGB(180, 180, 180))
        task.spawn(function()
            local ok, execErr = pcall(function()
                if typeof(loadstring) == "function" then
                    local fn, compErr = loadstring(code)
                    if fn then
                        task.spawn(fn)
                    else
                        warn("[ScriptHub] Compile error:", compErr)
                        SetStatus("Compile err " .. _CHR.EM_DASH .. " " .. tostring(compErr):sub(1, 50), Color3.fromRGB(180, 80, 80))
                        return
                    end
                end
            end)
            if ok then
                SetStatus("Done: " .. titleStr, Color3.fromRGB(110, 200, 110))
            else
                SetStatus("Runtime err " .. _CHR.EM_DASH .. " " .. tostring(execErr):sub(1, 50), Color3.fromRGB(180, 80, 80))
            end
        end)
    end
    local function MakeScriptCard(scriptData, order)
        local gameId     = scriptData.game and scriptData.game.gameId
        local title      = scriptData.title or "Untitled"
        local gameName   = (scriptData.game and scriptData.game.name) or "Unknown"
        local verified   = scriptData.verified
        local hasKey     = scriptData.key
        local views      = scriptData.views or 0
        local isPatched  = scriptData.isPatched
        local isUniv     = scriptData.isUniversal
        local gameImgUrl = scriptData.game and scriptData.game.imageUrl
        local slug       = scriptData.slug or ""
        local scriptCode = scriptData.script or ""
        if sbFilterHidePatched and isPatched then return nil end
        local card = New("Frame", {
            BackgroundColor3       = Color3.fromRGB(6, 6, 6),
            BackgroundTransparency = 0,
            ClipsDescendants       = true,
            LayoutOrder            = order,
            Parent                 = sbGrid,
        })
        Round(card, 10)
        local cardStroke = Stroke(card, Color3.fromRGB(28, 28, 28), 1, 0.25)
        local thumbFrame = New("Frame", {
            Size             = UDim2.new(1, 0, 0, 82),
            BackgroundColor3 = Color3.fromRGB(12, 12, 12),
            ClipsDescendants = true,
            Parent           = card,
        })
        Round(thumbFrame, 10)
        local thumb = New("ImageLabel", {
            Size                = UDim2.new(1, 0, 1, 0),
            BackgroundTransparency = 1,
            Image               = "",
            ScaleType           = Enum.ScaleType.Crop,
            ImageTransparency   = 0.06,
            Parent              = thumbFrame,
        })
        if gameId and gameId > 0 then
            LoadThumbnail(thumb, "rbxthumb://type=GameIcon&id=" .. tostring(gameId) .. "&w=150&h=150")
        elseif gameImgUrl and gameImgUrl ~= "" then
            LoadThumbnail(thumb, gameImgUrl)
        else
            ApplyGradientFallback(thumb)
        end
        local fadeFrame = New("Frame", {
            Size             = UDim2.new(1, 0, 0.55, 0),
            Position         = UDim2.new(0, 0, 0.45, 0),
            BackgroundColor3 = Color3.fromRGB(6, 6, 6),
            BackgroundTransparency = 0,
            BorderSizePixel  = 0,
            Parent           = thumbFrame,
        })
        New("UIGradient", {
            Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0, 1),
                NumberSequenceKeypoint.new(1, 0),
            }),
            Rotation = 90,
            Parent   = fadeFrame,
        })
        local badgeRow = New("Frame", {
            Size             = UDim2.new(1, -8, 0, 16),
            Position         = UDim2.new(0, 4, 0, 4),
            BackgroundTransparency = 1,
            Parent           = thumbFrame,
        })
        New("UIListLayout", {
            FillDirection     = Enum.FillDirection.Horizontal,
            Padding           = UDim.new(0, 3),
            VerticalAlignment = Enum.VerticalAlignment.Center,
            Parent            = badgeRow,
        })
        if hasKey    then MakeBadge(badgeRow, "KEY",       100, 68, 8,   255, 200, 70)  end
        if isUniv    then MakeBadge(badgeRow, "UNIV",      24, 52, 105,  120, 170, 255) end
        if isPatched then MakeBadge(badgeRow, "PATCHED",   90, 18, 18,   255, 120, 120) end
        local infoFrame = New("Frame", {
            Size              = UDim2.new(1, -10, 0, 0),
            AutomaticSize     = _AutomaticSizeY or Enum.AutomaticSize.Y,
            Position          = UDim2.new(0, 5, 0, 85),
            BackgroundTransparency = 1,
            Parent            = card,
        })
        New("UIListLayout", {
            Padding = UDim.new(0, 2),
            Parent  = infoFrame,
        })
        New("TextLabel", {
            Size              = UDim2.new(1, 0, 0, 0),
            AutomaticSize     = _AutomaticSizeY or Enum.AutomaticSize.Y,
            BackgroundTransparency = 1,
            Font              = Enum.Font.GothamBold,
            Text              = title,
            TextColor3        = Color3.fromRGB(228, 228, 228),
            TextSize          = 10,
            TextWrapped       = true,
            TextTruncate      = Enum.TextTruncate.AtEnd,
            TextXAlignment    = Enum.TextXAlignment.Left,
            Parent            = infoFrame,
        })
        New("TextLabel", {
            Size              = UDim2.new(1, 0, 0, 12),
            BackgroundTransparency = 1,
            Font              = Enum.Font.Gotham,
            Text              = gameName,
            TextColor3        = Color3.fromRGB(90, 90, 90),
            TextSize          = 9,
            TextTruncate      = Enum.TextTruncate.AtEnd,
            TextXAlignment    = Enum.TextXAlignment.Left,
            Parent            = infoFrame,
        })
        local viewsStr = views >= 1000 and (math.floor(views / 1000) .. "k") or tostring(views)
        New("TextLabel", {
            Size              = UDim2.new(1, 0, 0, 11),
            BackgroundTransparency = 1,
            Font              = Enum.Font.Code,
            Text              = viewsStr .. " views",
            TextColor3        = Color3.fromRGB(62, 62, 62),
            TextSize          = 8,
            TextXAlignment    = Enum.TextXAlignment.Left,
            Parent            = infoFrame,
        })
        local btnText  = isPatched and "COPY" or "EXECUTE"
        local btnColor = isPatched and Color3.fromRGB(110, 110, 110) or accent
        local execBtn = New("TextButton", {
            Size              = UDim2.new(1, -8, 0, 22),
            Position          = UDim2.new(0, 4, 1, -26),
            BackgroundColor3  = Color3.fromRGB(14, 14, 14),
            BackgroundTransparency = 0,
            Font              = Enum.Font.GothamBold,
            Text              = btnText,
            TextColor3        = btnColor,
            TextSize          = 9,
            AutoButtonColor   = false,
            Parent            = card,
        })
        Round(execBtn, 7)
        local execStroke = Stroke(execBtn, accent, 1, isPatched and 0.72 or 0.38)
        SafeConnect(GetSignal(card, "MouseEnter"), function()
            Tween(card, 0.15, nil, nil, { BackgroundColor3 = Color3.fromRGB(14, 14, 14) })
            Tween(cardStroke, 0.15, nil, nil, { Transparency = 0, Color = accent })
        end)
        SafeConnect(GetSignal(card, "MouseLeave"), function()
            Tween(card, 0.18, nil, nil, { BackgroundColor3 = Color3.fromRGB(6, 6, 6) })
            Tween(cardStroke, 0.18, nil, nil, { Transparency = 0.25, Color = Color3.fromRGB(28, 28, 28) })
        end)
        AddButtonHover(execBtn, execStroke, 0.08)
        SafeConnect(GetSignal(execBtn, "MouseButton1Click"), function()
            PlayUISound("Click")
            if isPatched then
                pcall(function()
                    if typeof(setclipboard) == "function" then
                        setclipboard(scriptCode ~= "" and scriptCode or ("-- " .. title .. " (patched)"))
                    elseif typeof(toclipboard) == "function" then
                        toclipboard(scriptCode ~= "" and scriptCode or ("-- " .. title .. " (patched)"))
                    end
                end)
                SetStatus("Copied: " .. title, Color3.fromRGB(160, 160, 160))
                return
            end
            if scriptCode ~= "" then
                ExecCode(scriptCode, title)
            else
                SetStatus("Fetching: " .. title .. "...", Color3.fromRGB(180, 180, 180))
                task.spawn(function()
                    local rawUrl = "https://scriptblox.com/api/script/raw/" .. slug
                    local body, err = SafeHttpGet(rawUrl)
                    if body and body ~= "" then
                        ExecCode(body, title)
                    else
                        SetStatus("Fetch gagal " .. _CHR.EM_DASH .. " " .. (err or "network error"), Color3.fromRGB(180, 80, 80))
                    end
                end)
            end
        end)
        return card
    end
    FetchScripts = function(reset)
        if sbLoading then return end
        sbLoading = true
        if reset then
            sbPage = 1
            ClearGrid()
            pcall(function() sbLoadMoreBtn.Visible = false end)
        end
        SetStatus("Loading...", Color3.fromRGB(180, 180, 180))
        local q = (sbSearchBox and sbSearchBox.Text:match("^%s*(.-)%s*$")) or ""
        local url
        if sbMode == "search" and q ~= "" then
            local encoded = ""
            pcall(function() encoded = HttpService:UrlEncode(q) end)
            if encoded == "" then
                encoded = q:gsub("[^%w%-_%.~]", function(c)
                    return string.format("%%%02X", string.byte(c))
                end)
            end
            url = "https://scriptblox.com/api/script/search?q=" .. encoded .. "&page=" .. sbPage
        elseif sbMode == "trending" then
            url = "https://scriptblox.com/api/script/trending"
        elseif sbMode == "free" then
            url = "https://scriptblox.com/api/script/fetch?mode=free&page=" .. sbPage
        elseif sbMode == "universal" then
            url = "https://scriptblox.com/api/script/fetch?mode=universal&page=" .. sbPage
        else
            url = "https://scriptblox.com/api/script/fetch?page=" .. sbPage
        end
        task.spawn(function()
            local body, err = SafeHttpGet(url)
            if not body or body == "" then
                SetStatus("Gagal load " .. _CHR.EM_DASH .. " " .. (err or "network error"), Color3.fromRGB(180, 80, 80))
                sbLoading = false
                return
            end
            local ok, data = pcall(function() return HttpService:JSONDecode(body) end)
            if not ok or not data or not data.result then
                SetStatus("Parse error " .. _CHR.EM_DASH .. " response tidak valid", Color3.fromRGB(180, 80, 80))
                sbLoading = false
                return
            end
            local scripts    = data.result.scripts or {}
            local totalPages = data.result.totalPages or 1
            local count      = #scripts
            if count == 0 then
                SetStatus("Tidak ada hasil" .. (q ~= "" and (" untuk: " .. q) or ""), Color3.fromRGB(90, 90, 90))
                sbLoading = false
                pcall(function() sbLoadMoreBtn.Visible = false end)
                return
            end
            local existingCount = 0
            if sbGrid then
                for _, child in ipairs(sbGrid:GetChildren()) do
                    if child:IsA("Frame") then existingCount = existingCount + 1 end
                end
            end
            local rendered = 0
            for i, scriptData in ipairs(scripts) do
                task.wait()
                local card = MakeScriptCard(scriptData, existingCount + i)
                if card then rendered = rendered + 1 end
            end
            local hasMore = (sbPage < totalPages) and (sbMode ~= "trending")
            pcall(function() sbLoadMoreBtn.Visible = hasMore end)
            local total = existingCount + rendered
            SetStatus(
                "Menampilkan " .. total .. " script" .. (hasMore and "  " .. _CHR.EM_DASH .. "  Ada lebih banyak" or ""),
                Color3.fromRGB(85, 85, 85)
            )
            sbLoading = false
        end)
    end
