    local function findRemoteByName(query)
        query = query:match("^%s*(.-)%s*$")
        if query == "" then return nil end
        local low = query:lower()
        local ok, res = pcall(function()
            local parts = string.split(query, ".")
            local node = game
            for _, p in ipairs(parts) do
                node = node:FindFirstChild(p)
                if not node then error("not found") end
            end
            if not (node:IsA("RemoteEvent") or node:IsA("RemoteFunction")) then
                error("not a remote")
            end
            return node
        end)
        if ok and res then return res end
        for _, r in ipairs(discoveredRemotes) do
            if r.name:lower() == low or string.find(r.name:lower(), low, 1, true) then
                return r.inst
            end
        end
        local found = nil
        pcall(function()
            for _, d in game:GetDescendants() do
                if (d:IsA("RemoteEvent") or d:IsA("RemoteFunction")) then
                    if d.Name:lower() == low or string.find(d.Name:lower(), low, 1, true) then
                        found = d
                        break
                    end
                end
            end
        end)
        return found
    end
